(* 注意：接口 plus_assoc 方向为 Id (plus a (plus b c))          *)
(* (plus (plus a b) c)（LHS 右结合），与标准库相反。           *)
(* ============================================================ *)

Section RingLemmas.
Context {RI : RealInterfaceEnhanced}.
Local Existing Instance RI_base.

(* 代数恒等式自动化简，替代手工 id_trans/id_cong 拼接。        *)

(* 加法逆的唯一性：b 和 c 都是 a 的右逆 ⟹ b = c *)
Lemma plus_inv_unique :
  forall a b c : R, Id (plus a b) zero -> Id (plus a c) zero -> Id b c.
Proof.
  intros a b c Hab Hac.
  pose proof (id_sym (plus_zero b)) as H1.                 (* b = b + 0 *)
  pose proof (id_cong (fun x => plus b x) (id_sym Hac)) as H2.
                                                           (* b + 0 = b + (a + c) *)
  pose proof (plus_assoc b a c) as H3.                     (* b + (a + c) = (b + a) + c *)
  pose proof (id_cong (fun x => plus x c) (plus_comm b a)) as H4.
                                                           (* (b + a) + c = (a + b) + c *)
  pose proof (id_cong (fun x => plus x c) Hab) as H5.      (* (a + b) + c = 0 + c *)
  pose proof (id_trans (plus_comm zero c) (plus_zero c)) as H6.  (* 0 + c = c *)
  exact (id_trans H1 (id_trans H2 (id_trans H3 (id_trans H4 (id_trans H5 H6))))).
Qed.

(* 负号对加法分配：opp (a+b) = (-a) + (-b) *)
Lemma opp_plus :
  forall a b : R, Id (opp (plus a b)) (plus (opp a) (opp b)).
Proof.
  intros a b.
  apply id_sym.
  apply (plus_inv_unique (plus a b)).
  - (* 重组为 zero。注意：接口 plus_assoc 方向为
       Id (plus a (plus b c)) (plus (plus a b) c)（右结合 = 左结合），
       与标准库相反，以下 rewrite 按此方向。 *)
    rewrite <- (plus_assoc a b (plus (opp a) (opp b))).
    rewrite (plus_assoc b (opp a) (opp b)).
    rewrite (plus_comm b (opp a)).
    rewrite <- (plus_assoc (opp a) b (opp b)).
    rewrite (plus_opp b).
    rewrite (plus_zero (opp a)).
    apply plus_opp.
  - apply plus_opp.
Qed.

(* 右分配律：a·c + b·c = (a+b)·c（由交换律与 distrib 推出） *)
Lemma mult_plus_distr_r :
  forall a b c : R, Id (mult (plus a b) c) (plus (mult a c) (mult b c)).
Proof.
  intros a b c.
  rewrite (mult_comm (plus a b) c).
  rewrite distrib.
  rewrite (mult_comm c a).
  rewrite (mult_comm c b).
  reflexivity.
Qed.

(* 负号对乘法：(-a)·b = -(a·b) *)
Lemma opp_mult_r :
  forall a b : R, Id (mult (opp a) b) (opp (mult a b)).
Proof.
  intros a b.
  apply (plus_inv_unique (mult a b)).
  - rewrite <- (mult_plus_distr_r a (opp a) b).
    rewrite (plus_opp a).
    rewrite (mult_comm zero b).
    rewrite (mult_zero b).
    reflexivity.
  - apply plus_opp.
Qed.

(* 负号对乘法：a·(-b) = -(a·b) *)
Lemma opp_mult_l :
  forall a b : R, Id (mult a (opp b)) (opp (mult a b)).
Proof.
  intros a b.
  rewrite (mult_comm a (opp b)).
  rewrite (opp_mult_r b a).
  rewrite (mult_comm b a).
  reflexivity.
Qed.

(* 2·a = a + a（2 := plus one one） *)
Lemma two_mult :
  forall a : R, Id (mult (plus one one) a) (plus a a).
Proof.
  intro a.
  rewrite (mult_comm (plus one one) a).
  rewrite distrib.
  rewrite (mult_one a).
  reflexivity.
Qed.

(* 双重取负：opp (opp a) = a *)
Lemma double_neg :
  forall a : R, Id (opp (opp a)) a.
Proof.
  intros a.
  apply id_sym.  (* 目标变为 Id a (opp (opp a)) *)

  (* 1. Id a (plus a zero) *)
  pose proof (plus_zero a) as H1.
  pose proof (id_sym H1) as H2.    (* Id a (plus a zero) *)

  (* 2. zero = plus (opp a) (opp (opp a)) *)
  pose proof (plus_opp (opp a)) as H3.
    (* Id (plus (opp a) (opp (opp a))) zero *)
  pose proof (id_sym H3) as H4.    (* Id zero (plus (opp a) (opp (opp a))) *)

  (* 3. plus a zero = plus a (plus (opp a) (opp (opp a))) *)
  pose proof (id_cong (fun x => plus a x) H4) as H5.

  (* 4. plus a (plus (opp a) (opp (opp a))) = plus (plus a (opp a)) (opp (opp a)) *)
  pose proof (plus_assoc a (opp a) (opp (opp a))) as H6.

  (* 5. plus a (opp a) = zero *)
  pose proof (plus_opp a) as H10.  (* Id (plus a (opp a)) zero *)

  (* 6. plus (plus a (opp a)) (opp (opp a)) = plus zero (opp (opp a)) *)
  pose proof (id_cong (fun x => plus x (opp (opp a))) H10) as H7.

  (* 7. plus zero (opp (opp a)) = plus (opp (opp a)) zero *)
  pose proof (plus_comm zero (opp (opp a))) as H8.

  (* 8. plus (opp (opp a)) zero = opp (opp a) *)
  pose proof (plus_zero (opp (opp a))) as H12.

  (* 将所有等式串联 *)
  exact (id_trans H2 (id_trans H5 (id_trans H6 (id_trans H7 (id_trans H8 H12))))).
Qed.

(* 1 ≠ 0：由 one_pos 与 lt_irrefl 推出（纯 Set 层，Empty_set 归谬） *)
Lemma one_neq_zero : Not (Id one zero).
Proof.
  intro H.
  apply (lt_irrefl zero).
  exact (match H in (Id _ y) return lt zero y with
         | id_refl => one_pos
         end).
Qed.

(* ============================================================ *)
(* 分析辅助引理（ε-δ 证明用；纯 Set 层）                       *)
(* ============================================================ *)

(* 2 := plus one one 的正性 *)
Lemma two_pos : lt zero (plus one one).
Proof.
  apply plus_positive; apply one_pos.
Qed.

(* eps/2 正性：lt zero a ⟹ lt zero (inv_2 · a) *)
Lemma half_pos :
  forall a, lt zero a -> lt zero (mult (inv_pos (plus one one) two_pos) a).
Proof.
  intros a Ha.
  apply mult_positive.
  - apply inv_pos_pos.   (* 目标 lt zero (inv_pos (plus one one) two_pos) 已含前提参数 *)
  - exact Ha.
Qed.

(* eps/2 加倍还原：inv_2·a + inv_2·a = a *)
Lemma half_twice :
  forall a,
    Id (plus (mult (inv_pos (plus one one) two_pos) a)
             (mult (inv_pos (plus one one) two_pos) a)) a.
Proof.
  intro a.
  rewrite <- (two_mult (mult (inv_pos (plus one one) two_pos) a)).
  rewrite (mult_assoc (plus one one) (inv_pos (plus one one) two_pos) a).
  rewrite (inv_pos_correct (plus one one) two_pos).
  rewrite (mult_comm one a).
  rewrite (mult_one a).
  reflexivity.
Qed.

(* 加法中项交换：(a+b)+(c+d) = (a+c)+(b+d) *)
Lemma plus_swap_mid :
  forall a b c d : R,
    Id (plus (plus a b) (plus c d)) (plus (plus a c) (plus b d)).
Proof.
  intros a b c d.
  rewrite <- (plus_assoc a b (plus c d)).
  rewrite (plus_assoc b c d).
  rewrite (plus_comm b c).
  rewrite <- (plus_assoc c b d).
  rewrite <- (plus_assoc a c (plus b d)).
  reflexivity.
Qed.

(* 减法对加法分配：(a+b)-(c+d) = (a-c)+(b-d) *)
Lemma minus_plus_distr :
  forall a b c d : R,
    Id (minus (plus a b) (plus c d)) (plus (minus a c) (minus b d)).
Proof.
  intros a b c d.
  unfold minus.
  rewrite (opp_plus c d).
  exact (plus_swap_mid a b (opp c) (opp d)).
Qed.

(* ============================================================ *)
(* differentiable_mult 辅助引理（纯 Set 层）                    *)
(* ============================================================ *)

(* |a| + 1 > 0：由 one_pos + abs_nonneg + le_plus_compat + lt_le_trans 推出 *)
Lemma abs_plus_one_pos : forall a : R, lt zero (plus (abs a) one).
Proof.
  intro a.
  apply (lt_le_trans _ one _).
  - apply one_pos.
  - apply (le_trans _ (plus zero one) _).
    + rewrite (plus_comm zero one). rewrite (plus_zero one). apply le_refl.
    + apply le_plus_compat.
      * apply abs_nonneg.
      * apply le_refl.
Qed.

(* b ≥ 0 时 a ≤ a + b *)
Lemma le_plus_nonneg_r : forall a b : R, le zero b -> le a (plus a b).
Proof.
  intros a b Hb.
  apply (le_trans _ (plus a zero) _).
  - rewrite (plus_zero a). apply le_refl.
  - apply le_plus_compat.
    + apply le_refl.
    + exact Hb.
Qed.

(* |a| ≤ |a| + 1 *)
Lemma abs_le_abs_plus_one : forall a : R, le (abs a) (plus (abs a) one).
Proof.
  intro a.
  apply le_plus_nonneg_r.
  apply (lt_le_iff zero one). left. apply one_pos.
Qed.

(* 非负 + 正 = 正：le zero a + lt zero b ⟹ lt zero (plus a b) *)
Lemma plus_le_lt_pos : forall a b : R, le zero a -> lt zero b -> lt zero (plus a b).
Proof.
  intros a b Ha Hb.
  apply (lt_le_trans _ b _).
  - exact Hb.
  - apply (le_trans _ (plus zero b) _).
    + rewrite (plus_comm zero b). rewrite (plus_zero b). apply le_refl.
    + apply le_plus_compat; [exact Ha | apply le_refl].
Qed.

(* log 对 exp_neg 是逆：log (e^{-x}) = -x（由 log_inv_exp_neg + log_inv_log + double_neg） *)
Lemma log_exp_neg : forall x : R, Id (log (exp_neg x)) (opp x).
Proof.
  intro x.
  assert (H1 : Id (log_inv (exp_neg x)) x) by exact (log_inv_exp_neg x).
  assert (H2 : Id (log_inv (exp_neg x)) (opp (log (exp_neg x))))
    by exact (log_inv_log (exp_neg x) (exp_neg_pos x)).
  assert (H3 : Id x (opp (log (exp_neg x)))) by exact (id_trans (id_sym H1) H2).
  exact (id_trans (id_sym (double_neg (log (exp_neg x)))) (id_cong opp (id_sym H3))).
Qed.

(* log 对逆元：log (1/x) = -log x（由 log_mult + log_one + plus_inv_unique） *)
Lemma log_inv_one_inv : forall x : R, forall Hx : lt zero x,
  Id (log (inv_pos x Hx)) (opp (log x)).
Proof.
  intros x Hx.
  assert (Hprod : Id (mult (inv_pos x Hx) x) one)
    by exact (id_trans (mult_comm (inv_pos x Hx) x) (inv_pos_correct x Hx)).
  assert (Hlm : Id (log (mult (inv_pos x Hx) x)) (plus (log (inv_pos x Hx)) (log x)))
    by exact (log_mult (inv_pos x Hx) x (inv_pos_pos x Hx) Hx).
  assert (Hz : Id (plus (log (inv_pos x Hx)) (log x)) zero).
  {
    assert (Hl1 : Id (log (mult (inv_pos x Hx) x)) zero)
      by exact (id_trans (id_cong log Hprod) (log_one)).
    exact (id_trans (id_sym Hlm) Hl1).
  }
  apply (plus_inv_unique (log x)).
  - apply (id_trans (plus_comm (log x) (log (inv_pos x Hx))) Hz).
  - apply plus_opp.
Qed.

(* e^{-log x} = x（x > 0）：由 log_inv_log（log_inv x = -log x）+
   exp_neg_log_inv（exp_neg (log_inv x) = x）推出。
   RLHF 对齐的 partition_condition 证明需要（e^{-E/β} = π_ref·e^{r/β}）。 *)
Lemma exp_neg_opp_log :
  forall x : R, forall Hx : lt zero x,
    Id (exp_neg (opp (log x))) x.
Proof.
  intros x Hx.
  assert (H1 : Id (log_inv x) (opp (log x))) by exact (log_inv_log x Hx).
  assert (H2 : Id (exp_neg (opp (log x))) (exp_neg (log_inv x)))
    by exact (id_cong (fun t => exp_neg t) (id_sym H1)).
  assert (H3 : Id (exp_neg (log_inv x)) x) by exact (exp_neg_log_inv x).
  exact (id_trans H2 H3).
Qed.

(* exp_neg 的和差：e^{-(a+b)} = e^{-a}·e^{-b}（exp_neg_plus 反向） *)
Lemma exp_neg_opp_plus :
  forall a b : R, Id (exp_neg (opp (plus a b))) (mult (exp_neg (opp a)) (exp_neg (opp b))).
Proof.
  intros a b.
  assert (H1 : Id (opp (plus a b)) (plus (opp a) (opp b)))
    by exact (opp_plus a b).
  assert (H2 : Id (exp_neg (opp (plus a b))) (exp_neg (plus (opp a) (opp b))))
    by exact (id_cong (fun t => exp_neg t) H1).
  assert (H3 : Id (exp_neg (plus (opp a) (opp b))) (mult (exp_neg (opp a)) (exp_neg (opp b))))
    by exact (exp_neg_plus (opp a) (opp b)).
  exact (id_trans H2 H3).
Qed.

(* log 对商：log (a/b) = log a - log b（由 log_mult + log_inv_one_inv） *)
Lemma log_div :
  forall a b : R, forall Ha : lt zero a, forall Hb : lt zero b,
    Id (log (mult a (inv_pos b Hb))) (minus (log a) (log b)).
Proof.
  intros a b Ha Hb.
  assert (Hlm : Id (log (mult a (inv_pos b Hb))) (plus (log a) (log (inv_pos b Hb))))
    by exact (log_mult a (inv_pos b Hb) Ha (inv_pos_pos b Hb)).
  assert (Hli : Id (log (inv_pos b Hb)) (opp (log b)))
    by exact (log_inv_one_inv b Hb).
  assert (Htot : Id (log (mult a (inv_pos b Hb))) (plus (log a) (opp (log b))))
    by exact (id_trans Hlm (id_cong (fun x => plus (log a) x) Hli)).
  unfold minus.
  exact Htot.
Qed.

(* 减法消元：a + (b - a) = b *)
Lemma minus_plus_cancel : forall a b : R, Id (plus a (minus b a)) b.
Proof.
  intros a b.
  unfold minus.
  rewrite plus_assoc.
  rewrite (plus_comm a b).
  rewrite <- (plus_assoc b a (opp a)).
  rewrite (plus_opp a).
  rewrite (plus_zero b).
  reflexivity.
Qed.

(* 减法消元（右）：(a + b) - a = b *)
Lemma minus_plus_cancel_r : forall a b : R, Id (minus (plus a b) a) b.
Proof.
  intros a b.
  unfold minus.
  rewrite <- (plus_assoc a b (opp a)).
  rewrite (plus_comm b (opp a)).
  rewrite (plus_assoc a (opp a) b).
  rewrite (plus_opp a).
  rewrite (plus_comm zero b).
  rewrite (plus_zero b).
  reflexivity.
Qed.

(* 减法的右分配：a - (b + c) = (a - b) - c *)
Lemma minus_plus_r : forall a b c : R,
  Id (minus a (plus b c)) (minus (minus a b) c).
Proof.
  intros a b c.
  unfold minus.
  rewrite (opp_plus b c).
  rewrite plus_assoc.
  reflexivity.
Qed.

(* 负号对减法：-(a - b) = (-a) + b *)
Lemma opp_minus : forall a b : R, Id (opp (minus a b)) (plus (opp a) b).
Proof.
  intros a b.
  unfold minus.
  rewrite (opp_plus a (opp b)).
  rewrite (double_neg b).
  reflexivity.
Qed.

(* |a - b| = |b - a|（减法对称；逐出稳态偏差量化需要。
   由 minus a b = opp (minus b a) + abs_opp 推出） *)
Lemma abs_minus_sym :
  forall a b : R, Id (abs (minus a b)) (abs (minus b a)).
Proof.
  intros a b.
  (* minus a b = opp (minus b a)（opp_minus 反向） *)
  assert (H1 : Id (minus a b) (opp (minus b a))).
  {
    assert (H2 : Id (opp (minus b a)) (plus (opp b) a)) by exact (opp_minus b a).
    assert (H3 : Id (plus (opp b) a) (plus a (opp b))) by exact (plus_comm (opp b) a).
    assert (H4 : Id (opp (minus b a)) (plus a (opp b))) by exact (id_trans H2 H3).
    exact (id_sym H4).
  }
  assert (H5 : Id (abs (minus a b)) (abs (opp (minus b a)))) by exact (id_cong abs H1).
  assert (H6 : Id (abs (opp (minus b a))) (abs (minus b a))) by exact (abs_opp (minus b a)).
  exact (id_trans H5 H6).
Qed.

(* log 对商反号：log (a/b) = -log (b/a)（由 log_div 两次 + opp_minus + double_neg） *)
Lemma log_div_neg :
  forall a b : R, forall Ha : lt zero a, forall Hb : lt zero b,
    Id (log (mult a (inv_pos b Hb))) (opp (log (mult b (inv_pos a Ha)))).
Proof.
  intros a b Ha Hb.
  assert (H1 : Id (log (mult a (inv_pos b Hb))) (minus (log a) (log b)))
    by exact (log_div a b Ha Hb).
  assert (H2 : Id (log (mult b (inv_pos a Ha))) (minus (log b) (log a)))
    by exact (log_div b a Hb Ha).
  assert (H3 : Id (minus (log b) (log a)) (opp (minus (log a) (log b))))
    by exact (id_trans (plus_comm (log b) (opp (log a))) (id_sym (opp_minus (log a) (log b)))).
  assert (H4 : Id (opp (log (mult b (inv_pos a Ha)))) (opp (minus (log b) (log a))))
    by exact (id_cong opp H2).
  assert (H5 : Id (opp (minus (log b) (log a))) (minus (log a) (log b))).
  {
    assert (H5a : Id (opp (minus (log b) (log a))) (opp (opp (minus (log a) (log b)))))
      by exact (id_cong opp H3).
    exact (id_trans H5a (double_neg (minus (log a) (log b)))).
  }
  assert (H6 : Id (opp (log (mult b (inv_pos a Ha)))) (minus (log a) (log b)))
    by exact (id_trans H4 H5).
  exact (id_trans H1 (id_sym H6)).
Qed.

(* 增量分解：a - b = (a - (b + c)) + c *)
Lemma minus_split : forall a b c : R,
  Id (minus a b) (plus (minus a (plus b c)) c).
Proof.
  intros a b c.
  unfold minus.
  rewrite (opp_plus b c).
  rewrite (plus_assoc a (opp b) (opp c)).
  rewrite <- (plus_assoc (plus a (opp b)) (opp c) c).
  rewrite (plus_comm (opp c) c).
  rewrite (plus_opp c).
  rewrite (plus_zero (plus a (opp b))).
  reflexivity.
Qed.

(* 乘法单调（右因子）：a ≥ 0 且 b ≤ c ⟹ a·b ≤ a·c *)
Lemma le_mult_compat_r : forall a b c : R,
  le zero a -> le b c -> le (mult a b) (mult a c).
Proof.
  intros a b c Ha Hbc.
  rewrite (mult_comm a b). rewrite (mult_comm a c).
  apply le_mult_compat_weak. exact Ha. exact Hbc.
Qed.

(* 2·((1/2)·(1/2)·e)·h = (1/2·e)·h（epsilon 份额合并） *)
Lemma two_times_quarter : forall e h' : R,
  Id (mult (plus one one) (mult (mult (inv_pos (plus one one) two_pos) (mult (inv_pos (plus one one) two_pos) e)) h'))
     (mult (mult (inv_pos (plus one one) two_pos) e) h').
Proof.
  intros e h'.
  rewrite (mult_assoc (plus one one) (mult (inv_pos (plus one one) two_pos) (mult (inv_pos (plus one one) two_pos) e)) h').
  rewrite (mult_assoc (plus one one) (inv_pos (plus one one) two_pos) (mult (inv_pos (plus one one) two_pos) e)).
  rewrite (inv_pos_correct (plus one one) two_pos).
  rewrite (mult_comm one (mult (inv_pos (plus one one) two_pos) e)).
  rewrite (mult_one (mult (inv_pos (plus one one) two_pos) e)).
  reflexivity.
Qed.

(* 乘积增量分解：(a+da)(b+db) - ab = a·db + b·da + da·db *)
Lemma mult_delta_split : forall a b da db : R,
  Id (minus (mult (plus a da) (plus b db)) (mult a b))
     (plus (mult a db) (plus (mult b da) (mult da db))).
Proof.
  intros a b da db.
  unfold minus.
  rewrite distrib.
  rewrite (mult_plus_distr_r a da b).
  rewrite (mult_plus_distr_r a da db).
  rewrite <- (plus_assoc (mult a b) (mult da b) (plus (mult a db) (mult da db))).
  rewrite <- (plus_assoc (mult a b) (plus (mult da b) (plus (mult a db) (mult da db))) (opp (mult a b))).
  rewrite (plus_comm (mult da b) (plus (mult a db) (mult da db))).
  rewrite <- (plus_assoc (mult a db) (mult da db) (mult da b)).
  rewrite (plus_comm (plus (mult a db) (plus (mult da db) (mult da b))) (opp (mult a b))).
  rewrite (plus_assoc (mult a b) (opp (mult a b)) (plus (mult a db) (plus (mult da db) (mult da b)))).
  rewrite (plus_opp (mult a b)).
  rewrite (plus_comm zero (plus (mult a db) (plus (mult da db) (mult da b)))).
  rewrite (plus_zero (plus (mult a db) (plus (mult da db) (mult da b)))).
  rewrite (plus_comm (mult da db) (mult da b)).
  rewrite (mult_comm da b).
  reflexivity.
Qed.

(* 五元加减重组：(A + (B+C)) - (D+E) = (A-D) + ((B-E) + C) *)
Lemma minus_plus_quad : forall A B C D E : R,
  Id (minus (plus A (plus B C)) (plus D E))
     (plus (minus A D) (plus (minus B E) C)).
Proof.
  intros A B C D E.
  unfold minus.
  rewrite (opp_plus D E).
  rewrite (plus_swap_mid A (plus B C) (opp D) (opp E)).
  rewrite <- (plus_assoc B C (opp E)).
  rewrite (plus_comm C (opp E)).
  rewrite (plus_assoc B (opp E) C).
  reflexivity.
Qed.

(* mult 对减法的分配：a·(b-c) = a·b - a·c *)
Lemma mult_minus_distr_l : forall a b c : R,
  Id (mult a (minus b c)) (minus (mult a b) (mult a c)).
Proof.
  intros a b c.
  unfold minus.
  rewrite distrib.
  rewrite (opp_mult_l a c).
  reflexivity.
Qed.

(* 乘积误差分解：f(x+h)g(x+h) - [f(x)g(x) + (df·g + f·dg)·h]
   = f(x)·(Δg - dg·h) + g(x)·(Δf - df·h) + Δf·Δg *)
Lemma mult_diff_decomp :
  forall (f g : R -> R) (df dg : R -> R) (x h : R),
  Id (minus (mult (f (plus x h)) (g (plus x h)))
            (plus (mult (f x) (g x))
                  (mult (plus (mult (df x) (g x)) (mult (f x) (dg x))) h)))
     (plus (mult (f x) (minus (g (plus x h)) (plus (g x) (mult (dg x) h))))
           (plus (mult (g x) (minus (f (plus x h)) (plus (f x) (mult (df x) h))))
                 (mult (minus (f (plus x h)) (f x)) (minus (g (plus x h)) (g x))))).
Proof.
  intros f g df dg x h.
  assert (Hder : Id (mult (plus (mult (df x) (g x)) (mult (f x) (dg x))) h)
                    (plus (mult (g x) (mult (df x) h)) (mult (f x) (mult (dg x) h)))).
  {
    rewrite (mult_plus_distr_r (mult (df x) (g x)) (mult (f x) (dg x)) h).
    rewrite <- (mult_assoc (df x) (g x) h).
    rewrite (mult_comm (g x) h).
    rewrite (mult_assoc (df x) h (g x)).
    rewrite (mult_comm (mult (df x) h) (g x)).
    rewrite <- (mult_assoc (f x) (dg x) h).
    reflexivity.
  }
  rewrite Hder.
  assert (Hf : Id (minus (mult (f (plus x h)) (g (plus x h)))
                         (plus (mult (f x) (g x)) (plus (mult (g x) (mult (df x) h)) (mult (f x) (mult (dg x) h)))))
                  (minus (mult (plus (f x) (minus (f (plus x h)) (f x))) (g (plus x h)))
                         (plus (mult (f x) (g x)) (plus (mult (g x) (mult (df x) h)) (mult (f x) (mult (dg x) h)))))).
  { apply id_sym.
    apply (id_cong (fun t => minus (mult t (g (plus x h)))
                                  (plus (mult (f x) (g x)) (plus (mult (g x) (mult (df x) h)) (mult (f x) (mult (dg x) h)))))).
    exact (minus_plus_cancel (f x) (f (plus x h))). }
  rewrite Hf.
  assert (Hg : Id (minus (mult (plus (f x) (minus (f (plus x h)) (f x))) (g (plus x h)))
                         (plus (mult (f x) (g x)) (plus (mult (g x) (mult (df x) h)) (mult (f x) (mult (dg x) h)))))
                  (minus (mult (plus (f x) (minus (f (plus x h)) (f x))) (plus (g x) (minus (g (plus x h)) (g x))))
                         (plus (mult (f x) (g x)) (plus (mult (g x) (mult (df x) h)) (mult (f x) (mult (dg x) h)))))).
  { apply id_sym.
    apply (id_cong (fun t => minus (mult (plus (f x) (minus (f (plus x h)) (f x))) t)
                                  (plus (mult (f x) (g x)) (plus (mult (g x) (mult (df x) h)) (mult (f x) (mult (dg x) h)))))).
    exact (minus_plus_cancel (g x) (g (plus x h))). }
  rewrite Hg.
  rewrite (minus_plus_r (mult (plus (f x) (minus (f (plus x h)) (f x))) (plus (g x) (minus (g (plus x h)) (g x))))
                        (mult (f x) (g x))
                        (plus (mult (g x) (mult (df x) h)) (mult (f x) (mult (dg x) h)))).
  rewrite (mult_delta_split (f x) (g x) (minus (f (plus x h)) (f x)) (minus (g (plus x h)) (g x))).
  rewrite (plus_comm (mult (g x) (mult (df x) h)) (mult (f x) (mult (dg x) h))).
  rewrite (minus_plus_quad (mult (f x) (minus (g (plus x h)) (g x)))
                           (mult (g x) (minus (f (plus x h)) (f x)))
                           (mult (minus (f (plus x h)) (f x)) (minus (g (plus x h)) (g x)))
                           (mult (f x) (mult (dg x) h))
                           (mult (g x) (mult (df x) h))).
  rewrite <- (mult_minus_distr_l (f x) (minus (g (plus x h)) (g x)) (mult (dg x) h)).
  rewrite <- (minus_plus_r (g (plus x h)) (g x) (mult (dg x) h)).
  rewrite <- (mult_minus_distr_l (g x) (minus (f (plus x h)) (f x)) (mult (df x) h)).
  rewrite <- (minus_plus_r (f (plus x h)) (f x) (mult (df x) h)).
  reflexivity.
Qed.

(* 乘法左消去：a > 0 ⟹ a·b = a·c ⟹ b = c（有序域标准性质；
   由乘逆元 + 结合律 + 交换律推出，自由能最小点唯一性需要） *)
Lemma mult_cancel_l :
  forall a b c : R, lt zero a -> Id (mult a b) (mult a c) -> Id b c.
Proof.
  intros a b c Ha Habc.
  (* 两边左乘 inv_pos a Ha：inv a · (a·b) = inv a · (a·c) *)
  assert (H1 : Id (mult (inv_pos a Ha) (mult a b))
                  (mult (inv_pos a Ha) (mult a c)))
    by exact (id_cong (fun x => mult (inv_pos a Ha) x) Habc).
  (* 重组：(inv a · a) · b = b *)
  assert (Hlb : Id (mult (inv_pos a Ha) (mult a b)) b).
  {
    assert (H2 : Id (mult (inv_pos a Ha) (mult a b))
                    (mult (mult (inv_pos a Ha) a) b))
      by exact (mult_assoc (inv_pos a Ha) a b).
    assert (H3 : Id (mult (mult (inv_pos a Ha) a) b)
                    (mult one b))
      by exact (id_cong (fun x => mult x b)
                        (id_trans (mult_comm (inv_pos a Ha) a) (inv_pos_correct a Ha))).
    assert (H4 : Id (mult one b) b)
      by exact (id_trans (mult_comm one b) (mult_one b)).
    exact (id_trans H2 (id_trans H3 H4)).
  }
  assert (Hrc : Id (mult (inv_pos a Ha) (mult a c)) c).
  {
    assert (H5 : Id (mult (inv_pos a Ha) (mult a c))
                    (mult (mult (inv_pos a Ha) a) c))
      by exact (mult_assoc (inv_pos a Ha) a c).
    assert (H6 : Id (mult (mult (inv_pos a Ha) a) c)
                    (mult one c))
      by exact (id_cong (fun x => mult x c)
                        (id_trans (mult_comm (inv_pos a Ha) a) (inv_pos_correct a Ha))).
    assert (H7 : Id (mult one c) c)
      by exact (id_trans (mult_comm one c) (mult_one c)).
    exact (id_trans H5 (id_trans H6 H7)).
  }
  exact (id_trans (id_sym Hlb) (id_trans H1 Hrc)).
Qed.

(* 乘法右消去：a > 0 ⟹ b·a = c·a ⟹ b = c（由左消去 + 交换律） *)
Lemma mult_cancel_r :
  forall a b c : R, lt zero a -> Id (mult b a) (mult c a) -> Id b c.
Proof.
  intros a b c Ha Hba.
  apply (mult_cancel_l a b c Ha).
  assert (H1 : Id (mult a b) (mult b a)) by exact (mult_comm a b).
  assert (H2 : Id (mult c a) (mult a c)) by exact (mult_comm c a).
  exact (id_trans H1 (id_trans Hba H2)).
Qed.

(* 减法非负：a ≤ b ⟹ 0 ≤ b - a（由 le_plus_compat 推导；
   Gibbs 等号条件 d(s) ≥ 0 需要） *)
Lemma le_minus_nonneg :
  forall a b : R, le a b -> le zero (minus b a).
Proof.
  intros a b Hab.
  unfold minus.
  assert (H1 : le (plus a (opp a)) (plus b (opp a)))
    by exact (le_plus_compat a b (opp a) (opp a) Hab (le_refl (opp a))).
  assert (H2 : Id (plus a (opp a)) zero) by exact (plus_opp a).
  apply (le_id_l zero (plus a (opp a)) (plus b (opp a)) (id_sym H2) H1).
Qed.

(* 减法为零消去：a - b = 0 ⟹ a = b（Gibbs 等号条件 d(s) = 0 ⟹ 项相等） *)
Lemma minus_eq_cancel :
  forall a b : R, Id (minus a b) zero -> Id a b.
Proof.
  intros a b Hab.
  unfold minus in Hab.
  assert (H1 : Id (opp b) (opp a))
    by exact (plus_inv_unique a (opp b) (opp a) Hab (plus_opp a)).
  assert (H2 : Id (opp (opp b)) (opp (opp a))) by exact (id_cong opp H1).
  assert (H3 : Id b (opp (opp a))) by exact (id_trans (id_sym (double_neg b)) H2).
  exact (id_sym (id_trans H3 (double_neg a))).
Qed.

(* 减法自零：a = b ⟹ a - b = 0（minus_eq_cancel 的逆；逐出零破缺需要） *)
Lemma minus_self_zero :
  forall a b : R, Id a b -> Id (minus a b) zero.
Proof.
  intros a b Hab.
  unfold minus.
  assert (H1 : Id (plus a (opp b)) (plus b (opp b)))
    by exact (id_cong (fun x => plus x (opp b)) Hab).
  exact (id_trans H1 (plus_opp b)).
Qed.

(* 加法消去（右）：a + b = a ⟹ b = 0（两边加 -a，重组为 0 + b = b） *)
Lemma plus_cancel_zero :
  forall a b : R, Id (plus a b) a -> Id b zero.
Proof.
  intros a b Hab.
  (* 两边左加 -a：-a + (a + b) = -a + a = 0 *)
  assert (H1 : Id (plus (opp a) (plus a b)) (plus (opp a) a))
    by exact (id_cong (fun x => plus (opp a) x) Hab).
  assert (H2 : Id (plus (opp a) (plus a b)) (plus (plus (opp a) a) b))
    by exact (plus_assoc (opp a) a b).
  assert (H3 : Id (plus (plus (opp a) a) b) (plus zero b))
    by exact (id_cong (fun x => plus x b) (id_trans (plus_comm (opp a) a) (plus_opp a))).
  assert (H4 : Id (plus zero b) b)
    by exact (id_trans (plus_comm zero b) (plus_zero b)).
  assert (H5 : Id (plus (plus (opp a) a) b) b)
    by exact (id_trans H3 H4).
  assert (H6 : Id (plus (opp a) (plus a b)) b)
    by exact (id_trans H2 H5).
  assert (H7 : Id (plus (opp a) a) zero)
    by exact (id_trans (plus_comm (opp a) a) (plus_opp a)).
  assert (H8 : Id (plus (opp a) (plus a b)) zero)
    by exact (id_trans H1 H7).
  exact (id_trans (id_sym H6) H8).
Qed.

(* 加法左消去：a + b = a + c ⟹ b = c（由 minus_plus_cancel_r 推出） *)
Lemma plus_cancel_l :
  forall a b c : R, Id (plus a b) (plus a c) -> Id b c.
Proof.
  intros a b c Habc.
  assert (H1 : Id (minus (plus a b) a) (minus (plus a c) a))
    by exact (id_cong (fun x => minus x a) Habc).
  assert (H2 : Id (minus (plus a b) a) b) by exact (minus_plus_cancel_r a b).
  assert (H3 : Id (minus (plus a c) a) c) by exact (minus_plus_cancel_r a c).
  assert (H4 : Id b (minus (plus a c) a)) by exact (id_trans (id_sym H2) H1).
  exact (id_trans H4 H3).
Qed.
(* 环消去（熵差-相对熵恒等式核心）：
   由 a·(-b) = a·(-c) + a·d 且 a > 0 推出 c - b = d。
   证明：两边加 a·c 得 a·(c - b) = a·d（distrib 反向 + 抵消），
   再 a > 0 消去（mult_cancel_l）。 *)
Lemma ring_d_cancel :
  forall a b c d : R,
    lt zero a ->
    Id (mult a (opp b)) (plus (mult a (opp c)) (mult a d)) ->
    Id (minus c b) d.
Proof.
  intros a b c d Ha Hmain.
  (* 第一步：mult a (minus c b) = mult a d *)
  assert (Hmul : Id (mult a (minus c b)) (mult a d)).
  {
    assert (Hd : Id (mult a (minus c b))
                   (plus (mult a c) (mult a (opp b))))
      by (unfold minus; exact (distrib a c (opp b))).
    assert (Hopp : Id (mult a (opp c)) (opp (mult a c)))
      by exact (opp_mult_l a c).
    assert (Hswap : Id (plus (mult a c) (plus (mult a (opp c)) (mult a d)))
                      (plus (plus (mult a c) (mult a (opp c))) (mult a d)))
      by exact (plus_assoc (mult a c) (mult a (opp c)) (mult a d)).
    assert (Hc0 : Id (plus (mult a c) (mult a (opp c))) zero)
      by exact (id_trans (id_cong (fun x => plus (mult a c) x) Hopp) (plus_opp (mult a c))).
    assert (Hr : Id (plus (plus (mult a c) (mult a (opp c))) (mult a d))
                    (plus zero (mult a d)))
      by exact (id_cong (fun x => plus x (mult a d)) Hc0).
    assert (Hz : Id (plus zero (mult a d)) (mult a d))
      by exact (id_trans (plus_comm zero (mult a d)) (plus_zero (mult a d))).
    assert (Hp1 : Id (plus (mult a c) (mult a (opp b)))
                     (plus (mult a c) (plus (mult a (opp c)) (mult a d))))
      by exact (id_cong (fun x => plus (mult a c) x) Hmain).
    assert (Hp2 : Id (plus (mult a c) (plus (mult a (opp c)) (mult a d)))
                     (mult a d))
      by exact (id_trans Hswap (id_trans Hr Hz)).
    exact (id_trans Hd (id_trans Hp1 Hp2)).
  }
  (* 第二步：a > 0 ⟹ minus c b = d *)
  exact (mult_cancel_l a (minus c b) d Ha Hmul).
Qed.

Lemma ring_minus_trans :
  forall a b c : R, Id (minus a b) (minus (minus a c) (minus b c)).
Proof.
  intros a b c.
  (* 两边同加 c：目标是 a - b = (a-c)-(b-c)
     等价于 (a - b) + c = (a - c) - (b - c) + c = a - c - b + c + c？不对。
     直接用 plus_inv_unique 证明。 *)
  (* 展开 RHS：minus (minus a c) (minus b c)
     = plus (plus a (opp c)) (opp (plus b (opp c)))
     = plus a (plus (opp c) (plus (opp b) (opp (opp c)))) [assoc + opp_plus]
     = plus a (plus (opp c) (plus (opp b) c)) [double_neg]
     = plus a (plus (opp c) (plus c (opp b))) [comm]
     = plus a (plus (plus (opp c) c) (opp b)) [assoc]
     = plus a (plus zero (opp b)) [opp 抵消]
     = plus a (opp b) [zero]
     = minus a b [unfold] *)
  unfold minus.
  (* 目标：plus a (opp b) = plus (plus a (opp c)) (opp (plus b (opp c))) *)
  assert (H1 : Id (plus (plus a (opp c)) (opp (plus b (opp c))))
                  (plus a (plus (opp c) (opp (plus b (opp c))))))
    by exact (id_sym (plus_assoc a (opp c) (opp (plus b (opp c))))).
  assert (H2 : Id (plus (opp c) (opp (plus b (opp c))))
                  (plus (opp c) (plus (opp b) (opp (opp c)))))
    by exact (id_cong (fun x => plus (opp c) x) (opp_plus b (opp c))).
  assert (H3 : Id (plus (opp c) (plus (opp b) (opp (opp c))))
                  (plus (opp c) (plus (opp b) c)))
    by exact (id_cong (fun x => plus (opp c) (plus (opp b) x)) (double_neg c)).
  assert (H4 : Id (plus (opp c) (plus (opp b) c))
                  (plus (opp c) (plus c (opp b))))
    by exact (id_cong (fun x => plus (opp c) x) (plus_comm (opp b) c)).
  assert (H5 : Id (plus (opp c) (plus c (opp b)))
                  (plus (plus (opp c) c) (opp b)))
    by exact (plus_assoc (opp c) c (opp b)).
  assert (H6 : Id (plus (plus (opp c) c) (opp b))
                  (plus zero (opp b)))
    by exact (id_cong (fun x => plus x (opp b)) (id_trans (plus_comm (opp c) c) (plus_opp c))).
  assert (H7 : Id (plus zero (opp b)) (opp b))
    by exact (id_trans (plus_comm zero (opp b)) (plus_zero (opp b))).
  assert (H8 : Id (plus (opp c) (opp (plus b (opp c)))) (opp b))
    by exact (id_trans H2 (id_trans H3 (id_trans H4 (id_trans H5 (id_trans H6 H7))))).
  assert (H9 : Id (plus (plus a (opp c)) (opp (plus b (opp c))))
                  (plus a (opp b)))
    by exact (id_trans H1 (id_cong (fun x => plus a x) H8)).
  exact (id_sym H9).
Qed.

(* ============================================================ *)
(* Set 层自动化：Id 代数化简策略（路径 1）                    *)
(* ============================================================ *)
(* Stdlib Proper/Setoid 依赖 Prop 层 relation，与 Set 层 Id     *)
(* 宇宙不兼容。替代方案：Ltac 组合 apply（内核转换匹配）闭环   *)
(* 恒等引理。定义在 RingLemmas 内（RI 实例在上下文，引理已证）。 *)

Ltac id_simpl_step :=
  first [ apply double_neg | apply plus_zero | apply plus_opp
        | apply mult_one | apply mult_zero
        | apply opp_plus | apply opp_mult_l | apply opp_mult_r
        | apply minus_plus_cancel_r ].

Ltac id_simpl := repeat id_simpl_step.

(* id_ring：直接闭合或化简后反射 *)
Ltac id_ring := first [ apply double_neg | apply plus_zero | apply plus_opp
                       | apply mult_one | apply mult_zero
                       | apply opp_plus | apply opp_mult_l | apply opp_mult_r
                       | id_simpl; reflexivity ].

(* ============================================================ *)
(* id_ring 自动化演示（在 section 内，RI 可用）                *)
(* ============================================================ *)
Lemma id_ring_demo_double_neg :
  forall a : R, Id (opp (opp a)) a.
Proof. intro a. id_ring. Qed.

Lemma id_ring_demo_plus_opp :
  forall a : R, Id (plus a (opp a)) zero.
Proof. intro a. id_ring. Qed.

Lemma id_ring_demo_mult_one :
  forall a : R, Id (mult a one) a.
Proof. intro a. id_ring. Qed.

End RingLemmas.

(* ============================================================ *)
(* 状态空间接口：向量空间结构 + 度量 + 收敛（Set 层）        *)
(* ============================================================ *)

Class StateSpace (RI : RealInterface) := {
  S : Set;

  szero : S;
  splus : S -> S -> S;
  smult : R -> S -> S;
  sopp  : S -> S;

  splus_assoc : forall a b c : S, Id (splus a (splus b c)) (splus (splus a b) c);
  splus_comm  : forall a b : S, Id (splus a b) (splus b a);
  splus_zero  : forall a : S, Id (splus a szero) a;
  splus_opp   : forall a : S, Id (splus a (sopp a)) szero;
  smult_one   : forall a : S, Id (smult one a) a;
  smult_assoc : forall a b : R, forall x : S, Id (smult a (smult b x)) (smult (mult a b) x);
  smult_distrib_r : forall a : R, forall x y : S,
                      Id (smult a (splus x y)) (splus (smult a x) (smult a y));
  smult_distrib_l : forall a b : R, forall x : S,
                      Id (smult (plus a b) x) (splus (smult a x) (smult b x));

  smetric : S -> S -> R;
  smetric_sym       : forall a b : S, Id (smetric a b) (smetric b a);
  smetric_pos       : forall a b : S, le zero (smetric a b);
  smetric_zero      : forall a b : S, Id (smetric a b) zero -> Id a b;
  smetric_triangle  : forall a b c : S,
                        le (smetric a c) (plus (smetric a b) (smetric b c));

  clim : (nat -> S) -> S -> Set;
  clim_unique : forall u l1 l2, clim u l1 -> clim u l2 -> Id l1 l2;

  cauchy_complete_S :
    forall (u : nat -> S),
      (forall eps : R, lt zero eps ->
        sigT (fun N : nat => forall m n : nat,
          NatLe N m -> NatLe N n ->
          lt (smetric (u m) (u n)) eps)) ->
      sigT (fun l : S => clim u l);
}.

(* ============ 0. Real 自状态空间：clim := lim 的实例 ============ *)
Section RealSelfStateSpace.
Context {RI : RealInterface}.

(* 左单位元：1·a == a（RealInterface 只给右单位 mult_one，由 mult_comm 补左） *)
Lemma smult_one_l : forall a : @R RI, Id (@mult RI (@one RI) a) a.
Proof.
  intro a.
  apply (id_trans (@mult_comm RI (@one RI) a) (@mult_one RI a)).
Qed.

(* 右分配律：(a+b)·x == a·x + b·x（mult_comm + distrib 直接组装；
   库内 mult_plus_distr_r(L389) 在 Enhanced 层，此处底层自给） *)
Lemma smult_distrib_l_real : forall a b x : @R RI,
  Id (@mult RI (@plus RI a b) x) (@plus RI (@mult RI a x) (@mult RI b x)).
Proof.
  intros a b x.
  apply (id_sym (id_trans (id_trans (id_trans
    (id_cong (fun z => @plus RI (@mult RI a x) z) (@mult_comm RI b x))
    (id_cong (fun z => @plus RI z (@mult RI x b)) (@mult_comm RI a x)))
    (id_sym (@distrib RI x a b)))
    (id_sym (@mult_comm RI (@plus RI a b) x)))).
Qed.

(* 全部字段由 RI 字段直供（clim := @lim RI / clim_unique := @lim_unique RI /
   cauchy_complete_S := @cauchy_complete RI 即桥本体）。 *)
Definition RealSelfSS : StateSpace RI :=
  {| S := @R RI;
     szero := @zero RI;
     splus := @plus RI;
     smult := @mult RI;
     sopp  := @opp RI;
     splus_assoc := @plus_assoc RI;
     splus_comm  := @plus_comm RI;
     splus_zero  := @plus_zero RI;
     splus_opp   := @plus_opp RI;
     smult_one   := smult_one_l;
     smult_assoc := @mult_assoc RI;
     smult_distrib_r := @distrib RI;
     smult_distrib_l := smult_distrib_l_real;
     smetric := @metric RI;
     smetric_sym := @metric_sym RI;
     smetric_pos := @metric_pos RI;
     smetric_zero := @metric_zero RI;
     smetric_triangle := @metric_triangle RI;
     clim := @lim RI;
     clim_unique := @lim_unique RI;
     cauchy_complete_S := @cauchy_complete RI |}.

(* 打印：clim/clim_unique/cauchy_complete_S 在实例上的类型 *)

End RealSelfStateSpace.

(* ============================================================ *)
(* Hilbert 空间（P0：注意力 Q·K 内积的几何基础）               *)
(* ============================================================ *)
(* Transformer 注意力本质是内积空间中的正交投影（Query-Key 点积 *)
(* 是内积，Softmax 是内积下的 Gibbs 测度，Value 是线性投影）。   *)
(* 本类为 StateSpace 增加内积结构，连接 AttentionGibbsBridge 的  *)
(* 抽象 logits 与 Q·K^T 的具体几何。                           *)
(* ------------------------------------------------------------ *)

Class HilbertSpace (RI : RealInterface) (SS : StateSpace RI) : Set := {
  inner : S -> S -> R;
  inner_sym       : forall x y : S, Id (inner x y) (inner y x);
  inner_pos       : forall x : S, le zero (inner x x);
  inner_definite  : forall x : S, Id (inner x x) zero -> Id x szero;
  inner_splus_l   : forall x y z : S,
    Id (inner (splus x y) z) (plus (inner x z) (inner y z));
  inner_smult_l   : forall (a : R) (x y : S),
    Id (inner (smult a x) y) (mult a (inner x y));

  (* 正交投影：注意力中 Value 的加权平均本质。
     proj u v = 沿 u 方向对 v 的（度量）投影。 *)
  proj : S -> S -> S;
  proj_linear     : forall u v w : S, Id (proj u (splus v w)) (splus (proj u v) (proj u w));
  proj_orthogonal : forall u v : S,
    Id (inner (splus v (sopp (proj u v))) u) zero;
}.

(* ============================================================ *)
(* Hilbert 空间非平凡定理（P0：注意力几何的核心性质）          *)
(* ============================================================ *)
(* 以下定理从 HilbertSpace 公理推出注意力机制的关键代数性质，   *)
(* 全部为非平凡推导（非公理重述），支撑 Q·K 投影的几何语义。    *)

Section HilbertTheorems.
Context {RI : RealInterfaceEnhanced}.
Context {SS : StateSpace RI}.
Context {HS : HilbertSpace RI SS}.

Let R := @R RI.
Let S := @S RI SS.
Let zero := @zero RI.
Let one := @one RI.
Let plus := @plus RI.
Let mult := @mult RI.
Let opp := @opp RI.
Let le := @le RI.
Let smetric := @smetric RI SS.
Let inner := @inner RI SS HS.
Let splus := @splus RI SS.
Let sopp := @sopp RI SS.
Let proj := @proj RI SS HS.

(* 正交残差存在性（信息性证明：给出残差向量 w := v - proj u v，
   使得 ⟨w, u⟩ = 0 且 v = proj u v + w——正交分解的构造性见证）。
   这是注意力 Value 分解（投影 + 残差）的 sigT 形式。 *)
Theorem orthogonal_decomposition_exists :
  forall u v : S,
    sigT (fun w : S =>
      And (Id (inner w u) zero)
          (Id v (splus (proj u v) w))).
Proof.
  intros u v.
  (* 取 w := splus v (sopp (proj u v))（v 减去其投影） *)
  exists (splus v (sopp (proj u v))).
  split.
  - (* ⟨v - proj u v, u⟩ = 0：proj_orthogonal 直接给出 *)
    exact (proj_orthogonal u v).
  - (* v = proj u v + (v - proj u v)：splus_opp + splus_assoc 抵消 *)
    assert (Hopp : Id (splus (proj u v) (splus v (sopp (proj u v))))
                    (splus (proj u v) (splus (sopp (proj u v)) v))).
    { apply (id_cong (fun x => splus (proj u v) x)).
      exact (splus_comm v (sopp (proj u v))). }
    assert (Hassoc : Id (splus (proj u v) (splus (sopp (proj u v)) v))
                        (splus (splus (proj u v) (sopp (proj u v))) v)).
    { exact (splus_assoc (proj u v) (sopp (proj u v)) v). }
    assert (Hinv : Id (splus (proj u v) (sopp (proj u v))) szero)
      by exact (splus_opp (proj u v)).
    assert (Hzero : Id (splus szero v) v)
      by exact (id_trans (splus_comm szero v) (splus_zero v)).
    exact (id_sym (id_trans Hopp (id_trans Hassoc (id_trans (id_cong (fun x => splus x v) Hinv) Hzero)))).
Qed.

(* ============================================================ *)
(* 正交分解唯一性（非平凡平行版本：投影的几何确定性）          *)
(* ============================================================ *)
(* orthogonal_decomposition_exists 给出分解 v = p + w（⟨w,u⟩=0，    *)
(* p := proj u v）的存在性；此处证明唯一性：若 w1、w2 都满足      *)
(* v = p + w，则 w1 = w2。证明用向量空间消去律（左加 sopp p 折叠：*)
(* sopp p + (p + w) = w，经 splus_assoc/comm/opp），非平凡：       *)
(* 约 15 步 S 层代数链。正交条件（⟨w,u⟩=0）与唯一性相容——        *)
(* 残差 w := v - p 是唯一正交残差，注意力 Value 投影的分解确定。  *)
(* ------------------------------------------------------------ *)

Theorem orthogonal_decomposition_unique :
  forall u v w1 w2 : S,
    Id (inner w1 u) zero -> Id v (splus (proj u v) w1) ->
    Id (inner w2 u) zero -> Id v (splus (proj u v) w2) ->
    Id w1 w2.
Proof.
  intros u v w1 w2 _ Hv1 _ Hv2.
  (* v = p + w1 且 v = p + w2 ⟹ p + w1 = p + w2 *)
  assert (Heq : Id (splus (proj u v) w1) (splus (proj u v) w2))
    by exact (id_trans (id_sym Hv1) Hv2).
  (* 两侧左加 sopp p（p := proj u v） *)
  assert (Hc : Id (splus (sopp (proj u v)) (splus (proj u v) w1))
                  (splus (sopp (proj u v)) (splus (proj u v) w2)))
    by exact (id_cong (fun x => splus (sopp (proj u v)) x) Heq).
  (* 左端折叠：sopp p + (p + w1) = w1 *)
  assert (Hl1 : Id (splus (sopp (proj u v)) (splus (proj u v) w1)) w1).
  {
    assert (H1 : Id (splus (sopp (proj u v)) (splus (proj u v) w1))
                    (splus (splus (sopp (proj u v)) (proj u v)) w1))
      by exact (splus_assoc (sopp (proj u v)) (proj u v) w1).
    assert (H2 : Id (splus (splus (sopp (proj u v)) (proj u v)) w1)
                    (splus szero w1))
      by exact (id_cong (fun x => splus x w1)
                        (id_trans (splus_comm (sopp (proj u v)) (proj u v))
                                  (splus_opp (proj u v)))).
    assert (H3 : Id (splus szero w1) w1)
      by exact (id_trans (splus_comm szero w1) (splus_zero w1)).
    exact (id_trans H1 (id_trans H2 H3)).
  }
  (* 右端折叠：sopp p + (p + w2) = w2（对称） *)
  assert (Hl2 : Id (splus (sopp (proj u v)) (splus (proj u v) w2)) w2).
  {
    assert (H1 : Id (splus (sopp (proj u v)) (splus (proj u v) w2))
                    (splus (splus (sopp (proj u v)) (proj u v)) w2))
      by exact (splus_assoc (sopp (proj u v)) (proj u v) w2).
    assert (H2 : Id (splus (splus (sopp (proj u v)) (proj u v)) w2)
                    (splus szero w2))
      by exact (id_cong (fun x => splus x w2)
                        (id_trans (splus_comm (sopp (proj u v)) (proj u v))
                                  (splus_opp (proj u v)))).
    assert (H3 : Id (splus szero w2) w2)
      by exact (id_trans (splus_comm szero w2) (splus_zero w2)).
    exact (id_trans H1 (id_trans H2 H3)).
  }
  (* w1 = LHS1 = LHS2 = w2 *)
  exact (id_trans (id_sym Hl1) (id_trans Hc Hl2)).
Qed.

End HilbertTheorems.

Fixpoint iterate {A : Set} (f : A -> A) (n : nat) (x : A) : A :=
  match n with
  | O => x
  | Datatypes.S n' => f (iterate f n' x)
  end.

Class SumOver (RI : RealInterface) (SS : StateSpace RI) : Set := {
  sum_over_S : (S -> R) -> R;
  sum_over_S_linear :
    forall (a : R) (f : S -> R),
      Id (sum_over_S (fun s => mult a (f s))) (mult a (sum_over_S f));
  sum_over_S_add :
    forall f g : S -> R,
      Id (sum_over_S (fun s => plus (f s) (g s)))
         (plus (sum_over_S f) (sum_over_S g));
  (* 外延性（函数 Proper 性）：逐点相等 ⟹ 求和相等。
     构造性可接受（任何具体求和均满足），用于详细平衡 ⟹ 稳态等推导。 *)
  sum_over_S_ext :
    forall f g : S -> R, (forall s, Id (f s) (g s)) -> Id (sum_over_S f) (sum_over_S g);
  (* 求和的保序性：逐点 ≤ ⟹ 求和 ≤（构造性可接受；任何具体求和
     （有限和 / 可数和）均满足；Gibbs 不等式 KL ≥ 0 需要） *)
  sum_over_S_le :
    forall f g : S -> R, (forall s, le (f s) (g s)) -> le (sum_over_S f) (sum_over_S g);
  (* 非负函数求和非负：0 ≤ f(s) 逐点 ⟹ 0 ≤ Σ f
     （构造性可接受；正函数之和为正的和——任何具体求和均满足；
     Gibbs 等号条件 KL = 0 ⟹ p = q 需要） *)
  sum_over_S_nonneg :
    forall f : S -> R, (forall s, le zero (f s)) -> le zero (sum_over_S f);
  (* 和为零且逐点非负 ⟹ 逐点为零：
     Σ f = 0 且 0 ≤ f(s) ⟹ f(s) = 0。
     构造性可接受（有限和/可数和的正性：非负项和为零则每项为零；
     Gibbs 等号条件的关键一步） *)
  sum_over_S_zero_nonneg :
    forall f : S -> R, (forall s, le zero (f s)) -> Id (sum_over_S f) zero ->
      forall s, Id (f s) zero;
  (* 求和的三角不等式：|Σ f| ≤ Σ |f|（构造性可接受；任何具体求和
     （有限和 / 可数和）均满足；逐出稳态偏差量化需要） *)
  abs_sum_le :
    forall f : S -> R, le (abs (sum_over_S f)) (sum_over_S (fun s => abs (f s)));
}.

(* ============================================================ *)
(* 可微性（参数化版本，Set 层）                               *)
(* ============================================================ *)

Record Differentiable {RI : RealInterface} (f : R -> R) := {
  df : R -> R;
  df_correct : forall x eps, lt zero eps ->
    sigT (fun delta : R => And (lt zero delta) (forall h, lt (abs h) delta ->
        le (abs (minus (f (plus x h))
                       (plus (f x) (mult (df x) h))))
           (mult eps (abs h))))
}.

(* ============================================================ *)
(* 命题汇聚论核心框架                                          *)
(* ============================================================ *)

Module PropositionConvergenceCore.

Section PropositionConvergenceCore.

Context {RI : RealInterfaceEnhanced}.
Context {SS : StateSpace RI}.
Context {SO : SumOver RI SS}.

(* 解包 RealInterface 字段 *)
Let R := @R RI.
Let zero := @zero RI.
Let one := @one RI.
Let plus := @plus RI.
Let mult := @mult RI.
Let opp := @opp RI.
Let abs := @abs RI.
Let lt := @lt RI.
Let le := @le RI.
Let inv_pos := @inv_pos RI.
Let exp_neg := @exp_neg RI.
Let log_inv := @log_inv RI.
Let log := @log RI.
Let metric := @metric RI.
Let lim := @lim RI.

(* 解包 StateSpace 字段 *)
Let S := @S RI SS.
Let szero := @szero RI SS.
Let splus := @splus RI SS.
Let smult := @smult RI SS.
Let sopp := @sopp RI SS.
Let smetric := @smetric RI SS.
Let clim := @clim RI SS.

(* 解包 SumOver 字段 *)
Let sum_over_S := @sum_over_S RI SS SO.

Definition Proposition : Set := S -> R.
(* 后续定义正常使用 R, S, plus, log_inv 等即可 *)

Definition IsProposition (P : Proposition) : Set :=
  forall s : S, And (le zero (P s)) (le (P s) one).

Definition IsPositiveProposition (P : Proposition) : Set :=
  forall s : S, lt zero (P s).

Definition loss_of_proposition (P : Proposition) (s : S) : R :=
  log_inv (P s).

Variable weighted_propositions : list (Proposition * R).
Variable weighted_props_positive :
  forall (p_w : Proposition * R), InT p_w weighted_propositions ->
    IsPositiveProposition (fst p_w).

Definition total_loss (s : S) : R :=
  fold_right (fun (p_w : Proposition * R) acc =>
                let (P, w) := p_w in
                plus (mult w (loss_of_proposition P s)) acc)
             zero weighted_propositions.

Variable base_loss : S -> R.
Definition full_loss (s : S) : R :=
  plus (base_loss s) (total_loss s).

Variable grad : (S -> R) -> S -> S.
Variable force : (S -> R) -> S -> S.

(* 力 = 负梯度（与 GradientDescentAndAttractor 的 force := sopp (grad ...)、
   LanguageModelInstance 的 force := -Δloss、PhysicalMechanics 的 F = -∇V
   约定一致；原版写为 +grad，若与下游定义同时成立将平凡化 grad = -grad）。 *)
Definition force_is_gradient (L : S -> R) : Set :=
  forall s : S, Id (force L s) (sopp (grad L s)).

Variable dynamics : (S -> R) -> S -> S.

Definition is_truth (L : S -> R) (s : S) : Set :=
  forall s' : S, le (L s) (L s').

Definition is_attractor (L : S -> R) (s : S) : Set :=
  forall s0 : S, clim (fun n => iterate (dynamics L) n s0) s.

Definition truth_iff_attractor (L : S -> R) (s : S) : Set :=
  And (is_truth L s -> is_attractor L s)
      (is_attractor L s -> is_truth L s).

Variable Z : R.
Variable Z_pos : lt zero Z.
Variable D : R.
Variable D_pos : lt zero D.

Definition boltzmann_factor (L : S -> R) (s : S) : R :=
  exp_neg (mult (inv_pos D D_pos) (L s)).

Definition boltzmann_prob (L : S -> R) (s : S) : R :=
  mult (inv_pos Z Z_pos) (boltzmann_factor L s).

Definition partition_condition (L : S -> R) : Set :=
  Id Z (sum_over_S (boltzmann_factor L)).

Variable free_energy : (S -> R) -> R.
Variable entropy     : (S -> R) -> R.
Variable free_energy_argmin : (S -> R) -> S -> R.

(* 以下抽象性质作为假设变量，非临时 Admitted *)
Variable free_energy_minimization :
  ExistsT (fun p_min : S -> R =>
    forall p : S -> R, le (free_energy p_min) (free_energy p)).

Variable min_free_energy_is_boltzmann :
  forall L : S -> R,
    Id (free_energy_argmin L) (boltzmann_prob L).

Variable E_A : R.
Variable T_A T_B : R.
Variable k : R.
Variable heat_flux : R.

Variable fourier_heat_conduction :
  Id heat_flux (mult k (plus T_B (opp T_A))).

Variable entropy_prod : R -> R.
Variable prob_density : R -> R.
Variable prob_pos : forall x : R, lt zero (prob_density x).
Variable k_B : R.
Variable k_B_pos : lt zero k_B.

Variable fluctuation_theorem :
  forall ds : R,
    Id (mult (inv_pos (prob_density (opp ds)) (prob_pos (opp ds)))
             (prob_density ds))
       (exp_neg (mult (inv_pos k_B k_B_pos) ds)).

Variable lower_prop : list Proposition.
Variable upper_prop : Proposition.
Variable hierarchical_relation : Proposition -> Proposition -> Set.

Definition hierarchical_stability : Set :=
  forall (P : Proposition), InT P lower_prop ->
    forall s : S, le (loss_of_proposition upper_prop s)
                     (loss_of_proposition P s).

Definition CoreClaim1 : Set :=
  forall P : S -> R, IsProposition P -> IsPositiveProposition P.

Definition CoreClaim2 : Set :=
  forall L : S -> R, forall s : S,
    is_attractor L s -> is_truth L s.

Definition CoreClaim3 : Set :=
  forall L : S -> R, force_is_gradient L.

Definition CoreClaim4 : Set :=
  forall L : S -> R, forall s : S,
    truth_iff_attractor L s.

Definition CoreClaim5 : Set :=
  forall L : S -> R,
    partition_condition L ->
    ExistsT (fun p : S -> R => Id p (boltzmann_prob L)).

Definition CoreClaim6 : Set := hierarchical_stability.

(* ============================================================ *)
(* 核心定理的非平凡实现（纯构造性、Set 层、无 Prop 设施）      *)
(* ============================================================ *)

(* CoreClaim5 的实现：见证 p := boltzmann_prob L 自身（存在性，自反）。 *)
Theorem core_claim5_holds : CoreClaim5.
Proof.
  unfold CoreClaim5.
  intros L Hpc.
  exists (boltzmann_prob L).
  reflexivity.
Qed.

(* Boltzmann 因子正性：由 exp_neg_pos 直接给出 *)
Theorem boltzmann_factor_pos :
  forall L : S -> R, forall s : S, lt zero (boltzmann_factor L s).
Proof.
  unfold boltzmann_factor.
  intros L s.
  apply exp_neg_pos.
Qed.

(* Boltzmann 概率正性：inv_pos_pos（Enhanced 字段）+ mult_positive + exp_neg_pos *)
Theorem boltzmann_prob_pos :
  forall L : S -> R, forall s : S, lt zero (boltzmann_prob L s).
Proof.
  unfold boltzmann_prob, boltzmann_factor.
  intros L s.
  apply mult_positive.
  - apply inv_pos_pos.   (* 目标 lt zero (inv_pos Z Z_pos) 已含前提参数，直接解决 *)
  - apply exp_neg_pos.
Qed.

Variable T_A_t : nat -> R.
Variable T_B_t : nat -> R.

Variable prediction_heat_relaxation :
  forall t : nat,
    le (metric (T_A_t t) (T_B_t t)) (metric (T_A_t (Nat.succ t)) (T_B_t (Nat.succ t))).

Variable equilibrium_dist : (S -> R) -> S -> R.

Variable prediction_equilibrium_boltzmann :
  forall L : S -> R,
    Id (equilibrium_dist L) (boltzmann_prob L).

Variable E_min : R.
Variable T_landauer : R.

Variable prediction_landauer :
  Id E_min (mult k_B (mult T_landauer (log_inv (plus one one)))).

(* 涨落标度：大小为 N 的涨落概率 = e^{-N/k_B}，随 N 增大而减小。
   原版方向写反（与 Boltzmann 的 e^{-x} 约定冲突），已翻转。
   P3-1 消解：由 exp_neg_le_decr（le a b -> le (exp_neg b) (exp_neg a)）
   于 le (N·inv) (plus N one · inv)（N ≤ N+1 乘 inv ≥ 0）直接推出——
   从诚实 Variable 提升为已证定理。 *)
Theorem prediction_fluctuation_scale :
  forall N : R,
    le (exp_neg (mult (plus N one) (inv_pos k_B k_B_pos)))
       (exp_neg (mult N (inv_pos k_B k_B_pos))).
Proof.
  intro N.
  apply exp_neg_le_decr.
  (* N·inv ≤ (N+1)·inv：N ≤ N+1（le_plus_nonneg_r）+ inv ≥ 0（le_mult_compat_weak） *)
  apply (le_mult_compat_weak N (plus N one) (inv_pos k_B k_B_pos)).
  - apply (lt_le_iff _ _). left. apply inv_pos_pos.
  - apply le_plus_nonneg_r. exact (lt_le_iff _ _ (inl one_pos)).
Qed.

Variable loss_drop : nat -> R.
Variable f_N : nat -> R.
Variable power : R -> R -> R.
Variable of_nat : nat -> R.

Variable prediction_cross_domain_scaling :
  ExistsT (fun alpha : R =>
    forall N : nat, Id (loss_drop N) (mult (power (of_nat N) alpha) (f_N N))).

Variable disturbance : Proposition -> R.

Variable prediction_hierarchical_stability_holds :
  forall (P : Proposition), InT P lower_prop ->
    le (disturbance upper_prop) (disturbance P).

Variable model : nat -> S.
Variable grammar_error : S -> R.

(* 语法错误沿训练递减（与 LanguageModelInstance 的
   prediction_grammar_error_decreases 方向一致；原版方向写反）。 *)
Variable prediction_lm_loss_structure :
  forall epoch : nat,
    le (grammar_error (model (Nat.succ epoch))) (grammar_error (model epoch)).

End PropositionConvergenceCore.

End PropositionConvergenceCore.

(* ============ 1. PCT 定义实例化到 (S := R, clim := lim) ============ *)
Section PCTRealBridge.
Context {RI : RealInterfaceEnhanced}.
Local Existing Instance RI_base.

(* 解包（对齐 PCT Section L1408-1431 的写法） *)
Let R := @R RI.
Let zero := @zero RI.
Let one := @one RI.
Let plus := @plus RI.
Let mult := @mult RI.
Let opp := @opp RI.
Let abs := @abs RI.
Let lt := @lt RI.
Let le := @le RI.
Let metric := @metric RI.
Let lim := @lim RI.

(* Real 自状态空间提升到 Enhanced 上下文（RI_base :> RealInterface 投影） *)
Let SS_R : StateSpace RI := @RealSelfSS (@RI_base RI).
Let S := @S RI SS_R.

(* 打印：PCT 导出定义（Section 关闭后已参量化）的实例化类型。
   若 is_attractor/CoreClaim2 不依赖 SumOver 与其他 Variable，此处类型将
   只含 dynamics 参数（证明桥只需 is_truth/is_attractor，SO 可缺）。 *)

(* ---- 定义层桥本体：PCT is_attractor 在 (S:=R, clim:=lim) 下逐字展开为
       lim 序列收敛（dynamics_wrap := 忽略损失的动力学，论文4 dynamics 提升）。
       两侧均为 Set 层命题（不可用 Id 作等词，A:=Set 超宇宙），改证双向蕴含
       —— 双方向由展开/转换直接闭合（定义层桥为平凡）。 *)
Theorem pct_attractor_is_lim :
  forall (dyn : R -> R) (L : R -> R) (s : R),
    (@PropositionConvergenceCore.is_attractor RI SS_R
       (fun (_ : R -> R) => dyn) L s ->
     forall s0 : R, lim (fun n => iterate dyn n s0) s) *
    ((forall s0 : R, lim (fun n => iterate dyn n s0) s) ->
     @PropositionConvergenceCore.is_attractor RI SS_R
       (fun (_ : R -> R) => dyn) L s).
Proof.
  intros dyn L s. split.
  - intro h. exact h.
  - intro h. exact h.
Qed.

(* ---- 对应 is_truth 的定义层展开：全局最小点形态（双向蕴含）。 *)
Theorem pct_truth_is_global_min :
  forall (L : R -> R) (s : R),
    (@PropositionConvergenceCore.is_truth RI SS_R L s ->
     forall s' : R, le (L s) (L s')) *
    ((forall s' : R, le (L s) (L s')) ->
     @PropositionConvergenceCore.is_truth RI SS_R L s).
Proof.
  intros L s. split.
  - intro h. exact h.
  - intro h. exact h.
Qed.

End PCTRealBridge.

(* ============================================================ *)
(* 语言模型实例化（独立 Module 避免命名冲突）                 *)
(* ============================================================ *)

Module LanguageModelInstance.

Section LanguageModelInstance.

Context {RI : RealInterfaceEnhanced}.

Local Existing Instance RI_base.

Variable Token : Set.
Variable vocab : list Token.
Variable vocab_nonempty : Not (Id vocab nil).
Variable token_eq_dec : forall a b : Token, Or (Id a b) (Not (Id a b)).

Definition Sequence : Set := list Token.

Variable neg_log_prob : Sequence -> Token -> R.

Fixpoint sequence_loss_prefix (prefix : Sequence) (s : Sequence) : R :=
  match s with
  | nil => zero
  | w :: rest =>
      plus (neg_log_prob prefix w) (sequence_loss_prefix (prefix ++ [w]) rest)
  end.

Definition sequence_loss (s : Sequence) : R := sequence_loss_prefix nil s.

Definition LangProp : Set := Sequence -> R.

Variable has_verb : LangProp.
Variable semantics_coherent : LangProp.
Variable style_appropriate : LangProp.

Variable alpha_grammar : R.
Variable alpha_semantics : R.
Variable alpha_style : R.

Variable prop_pos : forall P : LangProp, forall s : Sequence, lt zero (P s).

Definition loss_of_proposition (c : LangProp) (s : Sequence) : R :=
  log_inv (c s).

Definition total_loss (s : Sequence) : R :=
  plus (sequence_loss s)
       (plus (mult alpha_grammar (loss_of_proposition has_verb s))
             (plus (mult alpha_semantics (loss_of_proposition semantics_coherent s))
                   (mult alpha_style (loss_of_proposition style_appropriate s)))).

Definition force (s : Sequence) (w : Token) : R :=
  opp (minus (total_loss (s ++ [w])) (total_loss s)).

Context {DO : DecidableOrder RI}.
Variable default_token : Token.

Definition candidate : Set := (Token * R)%type.

Fixpoint argmin_aux (prefix : Sequence) (l : list Token) (best : candidate) : candidate :=
  match l with
  | nil => best
  | w :: rest =>
      let loss_w := total_loss (prefix ++ [w]) in
      match (@ord_le_dec _ DO) loss_w (snd best) with
      | inl _ => argmin_aux prefix rest (w, loss_w)
      | inr _ => argmin_aux prefix rest best
      end
  end.

Definition pick_best (prefix : Sequence) : Token :=
  match vocab with
  | nil => default_token
  | w0 :: rest =>
      fst (argmin_aux prefix rest (w0, total_loss (prefix ++ [w0])))
  end.

Definition dynamics (s : Sequence) : Sequence :=
  s ++ [pick_best s].

Definition is_truth (s : Sequence) : Set :=
  forall s' : Sequence, le (total_loss s) (total_loss s').

(* 注意：原此处命名为 is_attractor（单步不动点），与
   PropositionConvergenceCore / GradientDescentAndAttractor 中的收敛定义
   （forall s0, clim (iterate (dynamics L) n s0) s）同名异义；
   为避免术语漂移，改名为 is_fixed_point。 *)
Definition is_fixed_point (s : Sequence) : Set :=
  Id (dynamics s) s.

Variable plus_positive : forall a b : R, lt zero a -> lt zero b -> lt zero (plus a b).

Fixpoint sum_exp (prefix : Sequence) (l : list Token) : R :=
  match l with
  | nil => zero
  | w :: rest => plus (exp_neg (neg_log_prob prefix w)) (sum_exp prefix rest)
  end.

Definition partition_function (prefix : Sequence) : R :=
  sum_exp prefix vocab.

Lemma exp_neg_positive : forall x : R, lt zero (exp_neg x).
Proof. apply exp_neg_pos. Qed.

Lemma sum_exp_positive : forall prefix l, Not (Id l nil) -> lt zero (sum_exp prefix l).
Proof.
  intros prefix l. induction l as [| w rest IH].
  - intros Hnil. contradiction Hnil. apply id_refl.
  - intros _. simpl.
    destruct rest as [| w' rest'].
    + (* rest = [] *)
      change (lt zero (plus (exp_neg (neg_log_prob prefix w)) zero)).
      rewrite plus_zero.
      apply exp_neg_positive.
    + (* rest = w' :: rest' *)
      apply plus_positive.
      * apply exp_neg_positive.
      * apply IH. intro H. inversion H.
Qed.

Definition partition_positive (prefix : Sequence) : lt zero (partition_function prefix) :=
  sum_exp_positive prefix vocab vocab_nonempty.

Definition normalized_prob (prefix : Sequence) (w : Token) : R :=
  mult (exp_neg (neg_log_prob prefix w))
       (inv_pos (partition_function prefix) (partition_positive prefix)).

Definition CoreClaim1 : Set :=
  forall P : LangProp, forall s : Sequence, lt zero (P s).

Definition CoreClaim2 : Set :=
  forall s, is_fixed_point s -> is_truth s.

Definition CoreClaim3 : Set :=
  forall s w,
    Id (force s w) (minus (total_loss s) (total_loss (s ++ [w]))).

Definition CoreClaim4 : Set :=
  forall s, And (is_truth s) (is_fixed_point s).

Definition CoreClaim5 : Set :=
  forall prefix w,
    Id (normalized_prob prefix w)
       (mult (exp_neg (neg_log_prob prefix w))
             (inv_pos (partition_function prefix) (partition_positive prefix))).

Variable vocab_propositions : list LangProp.
Variable syntax_rules : LangProp.

Definition CoreClaim6 : Set :=
  forall (P : LangProp), InT P vocab_propositions ->
    forall s : Sequence,
      le (loss_of_proposition syntax_rules s)
         (loss_of_proposition P s).

(* ============================================================ *)
(* 核心定理的非平凡实现（纯构造性、Set 层、无 Prop 设施）      *)
(* ============================================================ *)

(* CoreClaim1：命题正性（由 prop_pos 假设直接给出） *)
Theorem core_claim1_holds : CoreClaim1.
Proof. exact prop_pos. Qed.

(* CoreClaim3：force 的等价形式（非平凡——环论推导）。
   force s w = opp (minus (loss (s++[w])) (loss s))
             = minus (loss s) (loss (s++[w]))
   由 opp_plus + double_neg + plus_comm 推出。 *)
Theorem core_claim3_holds : CoreClaim3.
Proof.
  unfold CoreClaim3, force, minus.
  intros s w.
  rewrite (opp_plus (total_loss (s ++ [w])) (opp (total_loss s))).
  rewrite (double_neg (total_loss s)).
  rewrite (plus_comm (opp (total_loss (s ++ [w]))) (total_loss s)).
  reflexivity.
Qed.

(* CoreClaim5：normalized_prob 的定义展开（自反） *)
Theorem core_claim5_holds : CoreClaim5.
Proof.
  unfold CoreClaim5, normalized_prob.
  intros prefix w.
  reflexivity.
Qed.

Variable grammar_error : Sequence -> R.

(* 以下性质作为假设变量，非临时 Admitted *)
Variable prediction_loss_monotone :
  forall s, le (total_loss (dynamics s)) (total_loss s).

Variable prediction_grammar_error_decreases :
  forall s, le (grammar_error (dynamics s)) (grammar_error s).

(* 注：prediction_boltzmann_sampling 原为 Variable，但内容与
   core_claim5_holds 相同（normalized_prob 的定义展开），故删除该
   假设，直接用已证定理 core_claim5_holds。 *)

Variable prediction_hierarchical_stability_holds :
  CoreClaim6.

Variable prediction_loss_structure_correlation :
  forall s, le (total_loss (dynamics s)) (total_loss s) ->
            le (grammar_error (dynamics s)) (grammar_error s).

(* ============================================================ *)
(* 补齐预测性质（模块1：LanguageModelInstance）                *)
(* ============================================================ *)
(* normalized_prob 逐点正：exp_neg 正 × partition 倒数正（非平凡：
   mult_positive 组合 exp_neg_pos 与 inv_pos_pos）。 *)
Theorem normalized_prob_pos :
  forall prefix w, lt zero (normalized_prob prefix w).
Proof.
  intros prefix w.
  unfold normalized_prob.
  apply mult_positive.
  - apply exp_neg_pos.
  - apply inv_pos_pos.
Qed.

(* Boltzmann 采样概率的显式形式（由定理而非假设给出）：
   与 core_claim5_holds 同一内容，此处以命名定理形式落库。 *)
Theorem prediction_boltzmann_sampling_holds :
  forall prefix w,
    Id (normalized_prob prefix w)
       (mult (exp_neg (neg_log_prob prefix w))
             (inv_pos (partition_function prefix) (partition_positive prefix))).
Proof.
  intros prefix w.
  unfold normalized_prob.
  reflexivity.
Qed.

End LanguageModelInstance.

End LanguageModelInstance.

(* ============================================================ *)
(* 随机语言模型：温度采样马尔可夫核（P3，结构性缺失.txt 七）    *)
(* ============================================================ *)
(* 文档草稿的温度采样核，此处以可证明形式落地：temp_factor /     *)
(* partition_temp / markov_kernel（温度化 Boltzmann 概率），      *)
(* markov_normalized（核归一化——概率守恒），markov_relative      *)
(* （相对恒等），markov_temperature_zero_limit（零温极限比值形式： *)
(* 损失间隙 ⟹ 概率比指数衰减——温度采样退化为贪心解码的定量内容）。*)
(* 注：文档草稿的 `Id temperature zero` 前提与 temperature_pos 矛盾，*)
(* 改为比值形式（同 AttentionGibbsBridge.temperature_zero_limit）。*)

Module StochasticLanguageModel.
Section StochasticLanguageModel.

Context {RI : RealInterfaceEnhanced}.
Local Existing Instance RI_base.

Let log := @log RI.
Let le_refl := @le_refl RI.
Let le_trans := @le_trans RI.
Let le_plus_compat := @le_plus_compat RI.
Let opp_le_compat := @opp_le_compat RI.
Let le_mult_compat_r := @le_mult_compat_r RI.
Let le_minus_nonneg := le_minus_nonneg.
Let opp_minus := opp_minus.
Let log_le_linear := @log_le_linear RI.

Variable Token : Set.
Variable vocab : list Token.
Variable vocab_nonempty : Not (Id vocab nil).
Variable total_loss : list Token -> R.   (* 序列损失（prefix ++ [w] 的损失） *)

Variable temperature : R.
Variable temperature_pos : lt zero temperature.

(* 温度化因子：e^{-loss/T}（损失越小权重越大） *)
Definition temp_factor (prefix : list Token) (w : Token) : R :=
  exp_neg (mult (inv_pos temperature temperature_pos) (total_loss (prefix ++ [w]))).

(* 列表求和（泛化：任意 Token → R 函数） *)
Fixpoint list_sum (f : Token -> R) (l : list Token) : R :=
  match l with
  | nil => zero
  | w :: rest => plus (f w) (list_sum f rest)
  end.

Definition partition_temp (prefix : list Token) : R :=
  list_sum (temp_factor prefix) vocab.

(* 温度化因子反单调：损失小 ⟹ temp_factor 大。
   loss(w1) ≤ loss(w2) ⟹ e^{−loss(w1)/T} ≥ e^{−loss(w2)/T}。
   非平凡：exp_neg_le_decr（指数参数 ≤）+ le_mult_compat_r（inv T > 0）。 *)
Lemma temp_factor_antitone : forall (prefix : list Token) (w1 w2 : Token),
  le (total_loss (prefix ++ [w1])) (total_loss (prefix ++ [w2])) ->
  le (temp_factor prefix w2) (temp_factor prefix w1).
Proof.
  intros prefix w1 w2 Hloss.
  unfold temp_factor.
  (* inv T > 0：le_mult_compat_r 需非负因子 *)
  assert (Hinv_nonneg : le zero (inv_pos temperature temperature_pos))
    by (apply (lt_le_iff _ _); left; apply inv_pos_pos).
  (* inv T · loss w1 ≤ inv T · loss w2（le_mult_compat_r） *)
  assert (Hm : le (mult (inv_pos temperature temperature_pos) (total_loss (prefix ++ [w1])))
                  (mult (inv_pos temperature temperature_pos) (total_loss (prefix ++ [w2]))))
    by exact (le_mult_compat_r (inv_pos temperature temperature_pos)
                               (total_loss (prefix ++ [w1])) (total_loss (prefix ++ [w2]))
                               Hinv_nonneg Hloss).
  (* exp_neg 递减：参数大 ⟹ 指数小 ⟹ 原值大？exp_neg_le_decr : le a b -> le (exp_neg b) (exp_neg a)。
     Hm : le (inv·loss w1) (inv·loss w2)，取 a := inv·loss w1, b := inv·loss w2，
     得 le (exp_neg (inv·loss w2)) (exp_neg (inv·loss w1))——正是目标（temp_factor 展开） *)
  exact (exp_neg_le_decr (mult (inv_pos temperature temperature_pos) (total_loss (prefix ++ [w1])))
                         (mult (inv_pos temperature temperature_pos) (total_loss (prefix ++ [w2])))
                         Hm).
Qed.

(* 温度采样核反单调：损失小 ⟹ 核概率大（共同配分因子约去）。
   loss(w1) ≤ loss(w2) ⟹ P_T(w2) ≤ P_T(w1)。
   非平凡：temp_factor_antitone + 乘以共同 inv(partition)（非负，le_mult_compat_r）。
   注：markov_kernel 定义于下方（partition_temp_pos 后），本引理随之。 *)

Lemma list_sum_linear : forall a : R, forall f : Token -> R, forall l : list Token,
  Id (list_sum (fun w => mult a (f w)) l) (mult a (list_sum f l)).
Proof.
  intros a f l. induction l as [| w rest IH]; simpl.
  - apply id_sym. apply mult_zero.
  - rewrite IH.
    apply id_sym. apply distrib.
Qed.

Lemma list_sum_add : forall f g : Token -> R, forall l : list Token,
  Id (list_sum (fun w => plus (f w) (g w)) l) (plus (list_sum f l) (list_sum g l)).
Proof.
  intros f g l. induction l as [| w rest IH]; simpl.
  - apply id_sym. apply plus_zero.
  - rewrite IH.
    exact (plus_swap_mid (f w) (g w) (list_sum f rest) (list_sum g rest)).
Qed.

Lemma list_sum_ext : forall f g : Token -> R, forall l : list Token,
  (forall w : Token, Id (f w) (g w)) -> Id (list_sum f l) (list_sum g l).
Proof.
  intros f g l Hfg. induction l as [| w rest IH]; simpl.
  - reflexivity.
  - assert (H1 : Id (plus (f w) (list_sum f rest)) (plus (f w) (list_sum g rest)))
      by exact (id_cong (fun x => plus (f w) x) IH).
    assert (H2 : Id (plus (f w) (list_sum g rest)) (plus (g w) (list_sum g rest)))
      by exact (id_cong (fun x => plus x (list_sum g rest)) (Hfg w)).
    exact (id_trans H1 H2).
Qed.

(* 非空列表的正函数和为正（同 LanguageModelInstance.sum_exp_positive 结构） *)
Lemma sum_temp_positive : forall (f : Token -> R),
  (forall w, lt zero (f w)) -> forall l : list Token, Not (Id l nil) -> lt zero (list_sum f l).
Proof.
  intros f Hpos l. induction l as [| w rest IH]; intros Hnil.
  - contradiction Hnil. apply id_refl.
  - simpl.
    destruct rest as [| w' rest'].
    + change (lt zero (plus (f w) zero)).
      rewrite plus_zero.
      apply Hpos.
    + apply plus_positive.
      * apply Hpos.
      * apply IH. intro H. inversion H.
Qed.

Definition partition_temp_pos (prefix : list Token) : lt zero (partition_temp prefix) :=
  sum_temp_positive (temp_factor prefix)
                    (fun w => exp_neg_pos (mult (inv_pos temperature temperature_pos)
                                                (total_loss (prefix ++ [w]))))
                    vocab vocab_nonempty.

(* 温度采样核：P(w|prefix) ∝ e^{-loss/T}，归一化配分函数 *)
Definition markov_kernel (prefix : list Token) (w : Token) : R :=
  mult (temp_factor prefix w) (inv_pos (partition_temp prefix) (partition_temp_pos prefix)).

(* 温度采样核反单调：损失小 ⟹ 核概率大（共同配分因子约去）。
   loss(w1) ≤ loss(w2) ⟹ P_T(w2) ≤ P_T(w1)。
   非平凡：temp_factor_antitone + 乘以共同 inv(partition)（非负，le_mult_compat_r）。 *)
Theorem markov_kernel_antitone : forall (prefix : list Token) (w1 w2 : Token),
  le (total_loss (prefix ++ [w1])) (total_loss (prefix ++ [w2])) ->
  le (markov_kernel prefix w2) (markov_kernel prefix w1).
Proof.
  intros prefix w1 w2 Hloss.
  unfold markov_kernel.
  (* temp_factor w2 ≤ temp_factor w1（temp_factor_antitone） *)
  assert (Htf : le (temp_factor prefix w2) (temp_factor prefix w1))
    by exact (temp_factor_antitone prefix w1 w2 Hloss).
  (* 乘以共同 inv(partition)（≥ 0）；le_mult_compat_r 给 mult inv tf ≤ mult inv tf'，
     用 mult_comm 换到 mult tf inv ≤ mult tf' inv *)
  assert (Hinv_nonneg : le zero (inv_pos (partition_temp prefix) (partition_temp_pos prefix)))
    by (apply (lt_le_iff _ _); left; apply inv_pos_pos).
  assert (Hm1 : le (mult (inv_pos (partition_temp prefix) (partition_temp_pos prefix)) (temp_factor prefix w2))
                   (mult (inv_pos (partition_temp prefix) (partition_temp_pos prefix)) (temp_factor prefix w1)))
    by exact (le_mult_compat_r (inv_pos (partition_temp prefix) (partition_temp_pos prefix))
                               (temp_factor prefix w2) (temp_factor prefix w1)
                               Hinv_nonneg Htf).
  (* mult tf inv ≤ mult inv tf ≤ mult inv tf' ≤ mult tf' inv *)
  assert (Hsw2 : le (mult (temp_factor prefix w2) (inv_pos (partition_temp prefix) (partition_temp_pos prefix)))
                    (mult (inv_pos (partition_temp prefix) (partition_temp_pos prefix)) (temp_factor prefix w2)))
    by exact (le_id_l (mult (temp_factor prefix w2) (inv_pos (partition_temp prefix) (partition_temp_pos prefix)))
                      (mult (inv_pos (partition_temp prefix) (partition_temp_pos prefix)) (temp_factor prefix w2))
                      (mult (inv_pos (partition_temp prefix) (partition_temp_pos prefix)) (temp_factor prefix w2))
                      (mult_comm (temp_factor prefix w2) (inv_pos (partition_temp prefix) (partition_temp_pos prefix)))
                      (le_refl _)).
  assert (Hsw3 : le (mult (inv_pos (partition_temp prefix) (partition_temp_pos prefix)) (temp_factor prefix w1))
                    (mult (temp_factor prefix w1) (inv_pos (partition_temp prefix) (partition_temp_pos prefix))))
    by exact (le_id_l (mult (inv_pos (partition_temp prefix) (partition_temp_pos prefix)) (temp_factor prefix w1))
                      (mult (temp_factor prefix w1) (inv_pos (partition_temp prefix) (partition_temp_pos prefix)))
                      (mult (temp_factor prefix w1) (inv_pos (partition_temp prefix) (partition_temp_pos prefix)))
                      (mult_comm (inv_pos (partition_temp prefix) (partition_temp_pos prefix)) (temp_factor prefix w1))
                      (le_refl _)).
  exact (le_trans _ _ _ Hsw2 (le_trans _ _ _ Hm1 Hsw3)).
Qed.

(* 核正性（温度采样概率 > 0） *)
Lemma markov_pos : forall prefix w, lt zero (markov_kernel prefix w).
Proof.
  intros prefix w. unfold markov_kernel.
  apply mult_positive.
  - unfold temp_factor. apply exp_neg_pos.
  - apply inv_pos_pos.
Qed.

(* 核归一化：Σ_w P(w|prefix) = 1（概率守恒——温度采样是概率测度） *)
Theorem markov_normalized : forall prefix,
  Id (list_sum (fun w => markov_kernel prefix w) vocab) one.
Proof.
  intro prefix.
  unfold markov_kernel.
  assert (Hext : Id (list_sum (fun w => mult (temp_factor prefix w) (inv_pos (partition_temp prefix) (partition_temp_pos prefix))) vocab)
                   (list_sum (fun w => mult (inv_pos (partition_temp prefix) (partition_temp_pos prefix)) (temp_factor prefix w)) vocab))
    by (apply list_sum_ext; intro w; apply mult_comm).
  assert (Hlin : Id (list_sum (fun w => mult (inv_pos (partition_temp prefix) (partition_temp_pos prefix)) (temp_factor prefix w)) vocab)
                    (mult (inv_pos (partition_temp prefix) (partition_temp_pos prefix))
                          (list_sum (temp_factor prefix) vocab)))
    by exact (list_sum_linear (inv_pos (partition_temp prefix) (partition_temp_pos prefix)) (temp_factor prefix) vocab).
  assert (Hdef : Id (mult (inv_pos (partition_temp prefix) (partition_temp_pos prefix))
                          (list_sum (temp_factor prefix) vocab))
                    (mult (inv_pos (partition_temp prefix) (partition_temp_pos prefix)) (partition_temp prefix)))
    by reflexivity.
  assert (Hcc : Id (mult (inv_pos (partition_temp prefix) (partition_temp_pos prefix)) (partition_temp prefix)) one)
    by exact (id_trans (mult_comm (inv_pos (partition_temp prefix) (partition_temp_pos prefix)) (partition_temp prefix))
                       (inv_pos_correct (partition_temp prefix) (partition_temp_pos prefix))).
  exact (id_trans Hext (id_trans Hlin (id_trans Hdef Hcc))).
Qed.

(* 相对恒等：P(w) = P(wstar)·e^{-(loss_w - loss_wstar)/T}（温度采样核的分解） *)
Theorem markov_relative :
  forall (prefix : list Token) (w wstar : Token),
    Id (markov_kernel prefix w)
       (mult (markov_kernel prefix wstar)
             (exp_neg (mult (inv_pos temperature temperature_pos)
                            (minus (total_loss (prefix ++ [w])) (total_loss (prefix ++ [wstar])))))).
Proof.
  intros prefix w wstar.
  unfold markov_kernel, temp_factor.
  set (A := exp_neg (mult (inv_pos temperature temperature_pos) (total_loss (prefix ++ [wstar])))).
  set (B := exp_neg (mult (inv_pos temperature temperature_pos) (minus (total_loss (prefix ++ [w])) (total_loss (prefix ++ [wstar]))))).
  set (C := inv_pos (partition_temp prefix) (partition_temp_pos prefix)).
  set (Ap := exp_neg (mult (inv_pos temperature temperature_pos) (total_loss (prefix ++ [w])))).
  (* 重组：mult (mult A C) B = mult (mult A B) C *)
  assert (Hre : Id (mult (mult A C) B) (mult (mult A B) C)).
  {
    assert (H1 : Id (mult (mult A C) B) (mult A (mult C B)))
      by exact (id_sym (mult_assoc A C B)).
    assert (H2 : Id (mult A (mult C B)) (mult A (mult B C)))
      by exact (id_cong (fun x => mult A x) (mult_comm C B)).
    assert (H3 : Id (mult A (mult B C)) (mult (mult A B) C))
      by exact (mult_assoc A B C).
    exact (id_trans H1 (id_trans H2 H3)).
  }
  (* 指数相加：A·B = Ap（exp_neg_plus + 代数） *)
  assert (Hprod : Id (mult A B) Ap).
  {
    unfold A, B, Ap.
    assert (Hep : Id (mult (exp_neg (mult (inv_pos temperature temperature_pos) (total_loss (prefix ++ [wstar]))))
                           (exp_neg (mult (inv_pos temperature temperature_pos) (minus (total_loss (prefix ++ [w])) (total_loss (prefix ++ [wstar]))))))
                     (exp_neg (plus (mult (inv_pos temperature temperature_pos) (total_loss (prefix ++ [wstar])))
                                    (mult (inv_pos temperature temperature_pos) (minus (total_loss (prefix ++ [w])) (total_loss (prefix ++ [wstar])))))))
      by exact (id_sym (exp_neg_plus (mult (inv_pos temperature temperature_pos) (total_loss (prefix ++ [wstar])))
                                     (mult (inv_pos temperature temperature_pos) (minus (total_loss (prefix ++ [w])) (total_loss (prefix ++ [wstar])))))).
    rewrite Hep.
    assert (Halg : Id (plus (mult (inv_pos temperature temperature_pos) (total_loss (prefix ++ [wstar])))
                            (mult (inv_pos temperature temperature_pos) (minus (total_loss (prefix ++ [w])) (total_loss (prefix ++ [wstar])))))
                      (mult (inv_pos temperature temperature_pos) (total_loss (prefix ++ [w])))).
    {
      assert (Hd : Id (plus (mult (inv_pos temperature temperature_pos) (total_loss (prefix ++ [wstar])))
                            (mult (inv_pos temperature temperature_pos) (minus (total_loss (prefix ++ [w])) (total_loss (prefix ++ [wstar])))))
                      (mult (inv_pos temperature temperature_pos)
                            (plus (total_loss (prefix ++ [wstar])) (minus (total_loss (prefix ++ [w])) (total_loss (prefix ++ [wstar]))))))
        by exact (id_sym (distrib (inv_pos temperature temperature_pos) (total_loss (prefix ++ [wstar])) (minus (total_loss (prefix ++ [w])) (total_loss (prefix ++ [wstar]))))).
      assert (Hc : Id (plus (total_loss (prefix ++ [wstar])) (minus (total_loss (prefix ++ [w])) (total_loss (prefix ++ [wstar]))))
                      (total_loss (prefix ++ [w])))
        by exact (minus_plus_cancel (total_loss (prefix ++ [wstar])) (total_loss (prefix ++ [w]))).
      exact (id_trans Hd (id_cong (fun x => mult (inv_pos temperature temperature_pos) x) Hc)).
    }
    apply (id_cong (fun x => exp_neg x)). exact Halg.
  }
  (* 组装：mult Ap C = mult (mult A C) B *)
  rewrite Hre.
  rewrite Hprod.
  reflexivity.
Qed.

(* 零温极限（比值形式）：损失间隙 ⟹ 概率比指数衰减。
   对任意 wstar（贪心最优候选：loss(wstar) ≤ loss(w)），
   P_T(w)/P_T(wstar) ≤ e^{-(loss(w) - loss(wstar))/T}——T→0 时温度采样
   的概率质量向最小损失态集中（退化为贪心解码的定量形式）。 *)
Theorem markov_temperature_zero_limit :
  forall (prefix : list Token) (w wstar : Token),
    le (total_loss (prefix ++ [wstar])) (total_loss (prefix ++ [w])) ->
    le (mult (markov_kernel prefix w)
             (inv_pos (markov_kernel prefix wstar) (markov_pos prefix wstar)))
       (exp_neg (mult (inv_pos temperature temperature_pos)
                      (minus (total_loss (prefix ++ [w])) (total_loss (prefix ++ [wstar]))))).
Proof.
  intros prefix w wstar Hloss.
  (* 相对恒等 + 两侧除以 markov_kernel wstar > 0（同 temperature_zero_limit 模式） *)
  assert (Hrel : Id (markov_kernel prefix w)
                    (mult (markov_kernel prefix wstar)
                          (exp_neg (mult (inv_pos temperature temperature_pos)
                                         (minus (total_loss (prefix ++ [w])) (total_loss (prefix ++ [wstar])))))))
    by exact (markov_relative prefix w wstar).
  set (A := markov_kernel prefix w).
  set (B := markov_kernel prefix wstar).
  set (C := exp_neg (mult (inv_pos temperature temperature_pos)
                          (minus (total_loss (prefix ++ [w])) (total_loss (prefix ++ [wstar]))))).
  assert (Hgc : le A (mult B C))
    by (unfold A, B, C; rewrite Hrel; apply le_refl).
  assert (Hinv : le zero (inv_pos B (markov_pos prefix wstar))).
  { apply (lt_le_iff _ _). left. apply inv_pos_pos. }
  assert (Hdiv : le (mult (inv_pos B (markov_pos prefix wstar)) A)
                    (mult (inv_pos B (markov_pos prefix wstar)) (mult B C)))
    by exact (le_mult_compat_r (inv_pos B (markov_pos prefix wstar)) A (mult B C) Hinv Hgc).
  assert (Hsw : Id (mult (inv_pos B (markov_pos prefix wstar)) A)
                   (mult A (inv_pos B (markov_pos prefix wstar))))
    by exact (mult_comm (inv_pos B (markov_pos prefix wstar)) A).
  assert (Hlhs : le (mult A (inv_pos B (markov_pos prefix wstar)))
                    (mult (inv_pos B (markov_pos prefix wstar)) (mult B C)))
    by exact (le_id_l (mult A (inv_pos B (markov_pos prefix wstar)))
                      (mult (inv_pos B (markov_pos prefix wstar)) A)
                      (mult (inv_pos B (markov_pos prefix wstar)) (mult B C))
                      (id_sym Hsw) Hdiv).
  assert (Hrhs : Id (mult (inv_pos B (markov_pos prefix wstar)) (mult B C)) C).
  {
    assert (H1 : Id (mult (inv_pos B (markov_pos prefix wstar)) (mult B C))
                    (mult (mult (inv_pos B (markov_pos prefix wstar)) B) C))
      by exact (mult_assoc (inv_pos B (markov_pos prefix wstar)) B C).
    assert (H2 : Id (mult (mult (inv_pos B (markov_pos prefix wstar)) B) C) (mult one C))
      by exact (id_cong (fun x => mult x C)
                        (id_trans (mult_comm (inv_pos B (markov_pos prefix wstar)) B)
                                  (inv_pos_correct B (markov_pos prefix wstar)))).
    assert (H3 : Id (mult one C) C)
      by exact (id_trans (mult_comm one C) (mult_one C)).
    exact (id_trans H1 (id_trans H2 H3)).
  }
  assert (Hfin : le (mult A (inv_pos B (markov_pos prefix wstar))) C)
    by exact (le_id_r (mult A (inv_pos B (markov_pos prefix wstar)))
                      (mult (inv_pos B (markov_pos prefix wstar)) (mult B C))
                      C Hrhs Hlhs).
  unfold A, B, C in Hfin.
  exact Hfin.
Qed.

(* 列表求和保序（仅对列表元素要求逐点）：若 f ≤ g 在 l 的元素上成立，
   则 list_sum f l ≤ list_sum g l。非平凡：归纳 l + le_plus_compat +
   InT_here/InT_next 递推。 *)
Lemma list_sum_le_on_list : forall (l : list Token) (f g : Token -> R),
  (forall w : Token, InT w l -> le (f w) (g w)) -> le (list_sum f l) (list_sum g l).
Proof.
  intros l f g Hfg. induction l as [| w rest IH]; simpl.
  - apply le_refl.
  - apply le_plus_compat.
    + apply Hfg. apply InT_here.
    + apply IH. intros w0 Hw0. apply Hfg. apply (InT_next w0 w rest Hw0).
Qed.

(* 期望损失：温度采样核下的平均损失（模块2 扩展定义） *)
Definition expected_loss (prefix : list Token) : R :=
  list_sum (fun w => mult (markov_kernel prefix w) (total_loss (prefix ++ [w]))) vocab.

(* 期望损失的贪心下界：若 wstar 是 vocab 上的全局最小损失候选
   （对任意 w ∈ vocab，loss(wstar) ≤ loss(w)），则期望损失 ≥ loss(wstar)。
   非平凡：逐点 p_w·loss(wstar) ≤ p_w·loss_w（p_w > 0，le_mult_compat_r）
   + 求和保序（list_sum_le_on_list，只在 vocab 元素上要求）
   + 线性化 Σ p_w·loss(wstar) = loss(wstar)·Σ p_w（list_sum_linear）
   + 归一化 Σ p_w = 1（markov_normalized）——温度采样的"期望不小于最小"。 *)
Theorem expected_loss_min_bound :
  forall prefix wstar,
    (forall w : Token, InT w vocab ->
      le (total_loss (prefix ++ [wstar])) (total_loss (prefix ++ [w]))) ->
    le (total_loss (prefix ++ [wstar])) (expected_loss prefix).
Proof.
  intros prefix wstar Hmin.
  unfold expected_loss.
  (* 逐点：p_w·loss(wstar) ≤ p_w·loss_w（对 w ∈ vocab） *)
  assert (Hpt : forall w : Token, InT w vocab ->
    le (mult (markov_kernel prefix w) (total_loss (prefix ++ [wstar])))
       (mult (markov_kernel prefix w) (total_loss (prefix ++ [w])))).
  {
    intros w Hw.
    apply (le_mult_compat_r (markov_kernel prefix w) (total_loss (prefix ++ [wstar]))
                            (total_loss (prefix ++ [w]))
                            (lt_le_iff _ _ (inl (markov_pos prefix w)))
                            (Hmin w Hw)).
  }
  (* 求和：Σ p_w·loss(wstar) ≤ Σ p_w·loss_w *)
  assert (Hsum_le : le (list_sum (fun w => mult (markov_kernel prefix w) (total_loss (prefix ++ [wstar]))) vocab)
                       (list_sum (fun w => mult (markov_kernel prefix w) (total_loss (prefix ++ [w]))) vocab)).
  { apply list_sum_le_on_list. exact Hpt. }
  (* 左端线性化：Σ p_w·loss(wstar) = loss(wstar)·Σ p_w *)
  assert (Hlin : Id (list_sum (fun w => mult (markov_kernel prefix w) (total_loss (prefix ++ [wstar]))) vocab)
                    (mult (total_loss (prefix ++ [wstar]))
                          (list_sum (markov_kernel prefix) vocab))).
  {
    assert (Hswap : Id (list_sum (fun w => mult (markov_kernel prefix w) (total_loss (prefix ++ [wstar]))) vocab)
                       (list_sum (fun w => mult (total_loss (prefix ++ [wstar])) (markov_kernel prefix w)) vocab))
      by (apply list_sum_ext; intro w; apply mult_comm).
    assert (Hlin' : Id (list_sum (fun w => mult (total_loss (prefix ++ [wstar])) (markov_kernel prefix w)) vocab)
                       (mult (total_loss (prefix ++ [wstar])) (list_sum (markov_kernel prefix) vocab)))
      by exact (list_sum_linear (total_loss (prefix ++ [wstar])) (markov_kernel prefix) vocab).
    exact (id_trans Hswap Hlin').
  }
  (* 归一化：Σ p_w = 1，故 loss(wstar)·Σ p_w = loss(wstar) *)
  assert (Hnorm : Id (list_sum (markov_kernel prefix) vocab) one)
    by exact (markov_normalized prefix).
  assert (Hunit : Id (mult (total_loss (prefix ++ [wstar])) (list_sum (markov_kernel prefix) vocab))
                     (total_loss (prefix ++ [wstar]))).
  {
    assert (H1 : Id (mult (total_loss (prefix ++ [wstar])) (list_sum (markov_kernel prefix) vocab))
                    (mult (total_loss (prefix ++ [wstar])) one))
      by exact (id_cong (fun x => mult (total_loss (prefix ++ [wstar])) x) Hnorm).
    assert (H2 : Id (mult (total_loss (prefix ++ [wstar])) one) (total_loss (prefix ++ [wstar])))
      by exact (mult_one (total_loss (prefix ++ [wstar]))).
    exact (id_trans H1 H2).
  }
  (* 组装：loss(wstar) = Σ p·loss(wstar) ≤ Σ p·loss_w = expected_loss *)
  apply (le_id_l (total_loss (prefix ++ [wstar]))
                 (list_sum (fun w => mult (markov_kernel prefix w) (total_loss (prefix ++ [wstar]))) vocab)
                 (list_sum (fun w => mult (markov_kernel prefix w) (total_loss (prefix ++ [w]))) vocab)
                 (id_trans (id_sym Hunit) (id_sym Hlin))
                 Hsum_le).
Qed.

(* ============================================================ *)
(* 温度采样与贪心解码的定量桥接（单调改进与hentic KL 控制.txt 块2）*)
(* ============================================================ *)
(* 1) markov_kernel_le_one：归一化正分布任意项 ≤ 1（概率上界）   *)
(* 2) temperature_zero_exponential_bound：非最优 w 的概率被       *)
(*    e^{−(loss(w) − loss(wstar))/T} 压制（经 markov_relative +   *)
(*    P(wstar) ≤ 1）——零温收敛的定量形式。                      *)
(* ------------------------------------------------------------ *)

(* 贪心最优 token 选择：由 DecidableOrder 下的 argmin 实例化
   （裁剪代理目标.txt：将 Variable 提升为已证定理）。
   定义：遍历 vocab，用 ord_le_dec 比较扩展损失，返回最小者。
   非平凡：argmin 结果 ∈ vocab（成员保持）+ 最小性（遍历正确性）。 *)
Context {DO : DecidableOrder RI}.

Variable default_token : Token.

Definition candidate_token : Set := (Token * R)%type.

Fixpoint argmin_aux_token (prefix : list Token) (l : list Token) (best : candidate_token) : candidate_token :=
  match l with
  | nil => best
  | w :: rest =>
      let loss_w := total_loss (prefix ++ [w]) in
      match (@ord_le_dec _ DO) loss_w (snd best) with
      | inl _ => argmin_aux_token prefix rest (w, loss_w)
      | inr _ => argmin_aux_token prefix rest best
      end
  end.

Definition pick_best_token (prefix : list Token) : Token :=
  match vocab with
  | nil => default_token
  | w0 :: rest =>
      fst (argmin_aux_token prefix rest (w0, total_loss (prefix ++ [w0])))
  end.

(* InT 头前插：x ∈ y :: l ⟹ x ∈ y :: a :: l（在 y 与 l 之间插入 a） *)
Lemma InT_head_extend : forall (x y a : Token) (l : list Token),
  InT x (y :: l) -> InT x (y :: a :: l).
Proof.
  intros x y a l H. inversion H; subst.
  - apply InT_here.
  - exact (@InT_next Token x y (a :: l) (@InT_next Token x a l H1)).
Qed.
(* argmin 结果 ∈ 候选列表 ∪ 初始 token：归纳证明。
   换 a 分支：fst ∈ a :: rest（IH），经 InT_next best_token 提升；
   保留分支：fst ∈ best_token :: rest（IH），经 InT_head_extend 提升。 *)
Lemma argmin_aux_token_mem : forall prefix l best_token best_loss,
  InT best_token (best_token :: l) ->
  InT (fst (argmin_aux_token prefix l (best_token, best_loss))) (best_token :: l).
Proof.
  intros prefix l. induction l as [| a rest IH]; intros best_token best_loss Hinit.
  - simpl. exact Hinit.
  - simpl.
    destruct (@ord_le_dec _ DO (total_loss (prefix ++ [a])) best_loss) as [Hle | Hnot].
    + (* 换 a：fst ∈ a :: rest（IH 于新 best (a, loss a)），提升到 best_token :: a :: rest *)
      assert (Hmem : InT (fst (argmin_aux_token prefix rest (a, total_loss (prefix ++ [a])))) (a :: rest))
        by (apply (IH a (total_loss (prefix ++ [a]))); apply InT_here).
      apply InT_next. exact Hmem.
    + (* 保留：fst ∈ best_token :: rest（IH），提升到 best_token :: a :: rest *)
      assert (Hmem : InT (fst (argmin_aux_token prefix rest (best_token, best_loss))) (best_token :: rest))
        by (apply (IH best_token best_loss); apply InT_here).
      apply (InT_head_extend _ _ a rest). exact Hmem.
Qed.

(* pick_best 的最优性：对任意 w ∈ vocab，pick_best 的扩展损失 ≤ w 的。
   非平凡：argmin_aux_token 遍历正确性（snd 不增 + 逐项最小）。 *)
Lemma argmin_aux_token_min : forall prefix l best_token best_loss,
  And (forall w : Token, InT w l ->
    le (snd (argmin_aux_token prefix l (best_token, best_loss)))
       (total_loss (prefix ++ [w])))
      (le (snd (argmin_aux_token prefix l (best_token, best_loss))) best_loss).
Proof.
  intros prefix l. induction l as [| a rest IH]; intros best_token best_loss.
  - (* nil：∀w, InT w nil → ... 空 + le_refl *)
    assert (Hempty : forall w : Token, InT w nil -> le (snd (argmin_aux_token prefix nil (best_token, best_loss)))
                                                       (total_loss (prefix ++ [w]))).
    { intros w HIn. exact (match HIn with end). }
    exact (pair Hempty (le_refl _)).
  - simpl.
    destruct (@ord_le_dec _ DO (total_loss (prefix ++ [a])) best_loss) as [Hle | Hnot].
    + (* 换 a：a 是最小；对 rest 用 IH *)
      destruct (IH a (total_loss (prefix ++ [a]))) as [IH_min IH_le].
      split.
      * intros w HIn. inversion HIn as [Hw_eq | y0 l0 Hw]; subst.
        -- (* w = a：snd (argmin rest (a, loss a)) ≤ loss a（IH_le） *)
           exact IH_le.
        -- (* w ∈ rest：IH_min *)
           exact (IH_min w Hw).
      * (* 第二分量：snd ≤ best_loss（IH_le + Hle 传递） *)
        exact (le_trans _ (total_loss (prefix ++ [a])) _ IH_le Hle).
    + (* 保留 best：best ≤ loss a（Hnot → not_le_lt）且 rest 用 IH *)
      destruct (IH best_token best_loss) as [IH_min IH_le].
      split.
      * intros w HIn. inversion HIn as [Hw_eq | y0 l0 Hw]; subst.
        -- assert (Hlt : lt best_loss (total_loss (prefix ++ [a]))) by (apply not_le_lt; exact Hnot).
           exact (le_trans _ best_loss _ IH_le (lt_le_iff _ _ (inl Hlt))).
        -- exact (IH_min w Hw).
      * exact IH_le.
Qed.

(* snd 恒等于对应 fst 的损失（argmin 遍历不变式，独立引理）。
   前提：初始 best_loss = 对应 fst 的损失（同 ArgminCorrectness 模式）。 *)
Lemma argmin_aux_token_snd_correct : forall prefix l best_token best_loss,
  best_loss = total_loss (prefix ++ [best_token]) ->
  snd (argmin_aux_token prefix l (best_token, best_loss)) =
  total_loss (prefix ++ [fst (argmin_aux_token prefix l (best_token, best_loss))]).
Proof.
  intros prefix l. induction l as [| a rest IH]; intros best_token best_loss Hinit.
  - simpl. exact Hinit.
  - simpl.
    destruct (@ord_le_dec _ DO (total_loss (prefix ++ [a])) best_loss) as [Hle | Hnot].
    + exact (IH a (total_loss (prefix ++ [a])) eq_refl).
    + exact (IH best_token best_loss Hinit).
Qed.

(* pick_best ∈ vocab（非平凡：argmin 遍历 vocab 且保持成员） *)
Theorem pick_best_in_vocab' : forall prefix, InT (pick_best_token prefix) vocab.
Proof.
  intro prefix.
  unfold pick_best_token.
  destruct vocab as [| w0 rest].
  - (* vocab 为空，但 vocab_nonempty 矛盾 *)
    exact (match vocab_nonempty (@id_refl (list Token) nil) with end).
  - (* 初始 w0 ∈ w0 :: rest = vocab；argmin 保持成员 *)
    apply (argmin_aux_token_mem prefix rest w0 (total_loss (prefix ++ [w0]))).
    apply InT_here.
Qed.

(* pick_best 的最优性：pick_best 的扩展损失 ≤ 任意 w ∈ vocab 的。
   非平凡：argmin 遍历正确性 + snd/fst 对应关系。 *)
Theorem pick_best_optimal : forall prefix w,
  InT w vocab ->
  le (total_loss (prefix ++ [pick_best_token prefix])) (total_loss (prefix ++ [w])).
Proof.
  intros prefix w Hw.
  unfold pick_best_token.
  destruct vocab as [| w0 rest].
  - inversion Hw.
  - (* 结果 = fst (argmin_aux_token ...)；需 snd 与 fst 对应 *)
    destruct (argmin_aux_token_min prefix rest w0 (total_loss (prefix ++ [w0]))) as [Hmin Hle].
    assert (Hsnd : snd (argmin_aux_token prefix rest (w0, total_loss (prefix ++ [w0]))) =
                   total_loss (prefix ++ [fst (argmin_aux_token prefix rest (w0, total_loss (prefix ++ [w0])))]))
      by exact (argmin_aux_token_snd_correct prefix rest w0 (total_loss (prefix ++ [w0])) eq_refl).
    (* w ∈ w0 :: rest 的两种情况 *)
    inversion Hw as [Hw0 | y0 l0 Hwrest]; subst.
    + (* w = w0：loss (fst ...) ≤ loss w0 *)
      assert (Hr : le (snd (argmin_aux_token prefix rest (w0, total_loss (prefix ++ [w0]))))
                      (total_loss (prefix ++ [w0])))
        by exact Hle.
      rewrite Hsnd in Hr.
      exact Hr.
    + (* w ∈ rest：Hmin w Hwrest，用 Hsnd 换形 *)
      assert (Hr : le (snd (argmin_aux_token prefix rest (w0, total_loss (prefix ++ [w0]))))
                      (total_loss (prefix ++ [w])))
        by exact (Hmin w Hwrest).
      rewrite Hsnd in Hr.
      exact Hr.
Qed.

(* 兼容别名：temperature_zero_exponential_bound 使用的成员保证 *)
Theorem pick_best_in_vocab : forall prefix, InT (pick_best_token prefix) vocab.
Proof. exact pick_best_in_vocab'. Qed.

(* 列表求和非负：f 逐点非负 ⟹ Σ f ≥ 0（归纳） *)
Lemma list_sum_nonneg : forall (l : list Token) (f : Token -> R),
  (forall w', le zero (f w')) -> le zero (list_sum f l).
Proof.
  intros l f Hnonneg. induction l as [| a rest IH]; simpl.
  - apply le_refl.
  - apply (le_id_l zero (plus zero zero) (plus (f a) (list_sum f rest))
                   (id_sym (plus_zero zero))
                   (le_plus_compat zero (f a) zero (list_sum f rest) (Hnonneg a) IH)).
Qed.

(* 列表单项 ≤ 全和：w ∈ l 且 f 逐点非负 ⟹ f w ≤ Σ f。
   非平凡：归纳 l，w 在头部（le_plus_nonneg_r）或尾部（le_trans）。 *)
Lemma list_sum_single_le_total : forall (l : list Token) (f : Token -> R) (w : Token),
  InT w l -> (forall w', le zero (f w')) -> le (f w) (list_sum f l).
Proof.
  intros l f w HIn Hnonneg.
  induction l as [| a rest IH].
  - inversion HIn.
  - simpl. inversion HIn as [| y l HIn']; subst.
    + (* w = a：f a ≤ f a + Σ rest（le_plus_nonneg_r，Σ rest ≥ 0） *)
      exact (le_plus_nonneg_r (f a) (list_sum f rest) (list_sum_nonneg rest f Hnonneg)).
    + (* w ∈ rest：f w ≤ Σ rest ≤ f a + Σ rest *)
      assert (Hle : le (f w) (list_sum f rest)) by exact (IH HIn').
      apply (le_trans _ (list_sum f rest) _ Hle).
      apply (le_id_l (list_sum f rest) (plus zero (list_sum f rest)) (plus (f a) (list_sum f rest))
                     (id_trans (id_sym (plus_zero (list_sum f rest)))
                               (plus_comm (list_sum f rest) zero))
                     (le_plus_compat zero (f a) (list_sum f rest) (list_sum f rest)
                                     (Hnonneg a) (le_refl (list_sum f rest)))).
  Qed.

(* 归一化正分布任意项 ≤ 1：p w ≤ Σ p = 1（概率上界） *)
Theorem markov_kernel_le_one :
  forall prefix w, InT w vocab -> le (markov_kernel prefix w) one.
Proof.
  intros prefix w Hin.
  (* p w ≤ Σ_all p（单项 ≤ 全和，p 逐点正） *)
  assert (Hle : le (markov_kernel prefix w) (list_sum (fun w' => markov_kernel prefix w') vocab))
    by exact (list_sum_single_le_total vocab (fun w' => markov_kernel prefix w') w Hin
                                        (fun w' => lt_le_iff _ _ (inl (markov_pos prefix w')))).
  (* Σ_all p = 1（markov_normalized） *)
  assert (Hnorm : Id (list_sum (fun w' => markov_kernel prefix w') vocab) one)
    by exact (markov_normalized prefix).
  exact (le_id_r (markov_kernel prefix w) (list_sum (fun w' => markov_kernel prefix w') vocab) one
                 Hnorm Hle).
Qed.

(* 零温指数衰减：非最优 w（loss(wstar) < loss(w)）的概率
   P_T(w) ≤ e^{−(loss(w) − loss(wstar))/T}。
   证明：markov_relative 给 P(w) = P(wstar)·e^{−Δ/T}，
   P(wstar) ≤ 1（markov_kernel_le_one），故 P(w) ≤ e^{−Δ/T}。 *)
Theorem temperature_zero_exponential_bound :
  forall (prefix : list Token) (w : Token),
    InT w vocab ->
    lt (total_loss (prefix ++ [pick_best_token prefix])) (total_loss (prefix ++ [w])) ->
    le (markov_kernel prefix w)
       (exp_neg (mult (inv_pos temperature temperature_pos)
                      (minus (total_loss (prefix ++ [w])) (total_loss (prefix ++ [pick_best_token prefix]))))).
Proof.
  intros prefix w Hvocab Hlt.
  (* markov_relative：P(w) = P(wstar)·e^{−Δ/T} *)
  assert (Hrel : Id (markov_kernel prefix w)
                    (mult (markov_kernel prefix (pick_best_token prefix))
                          (exp_neg (mult (inv_pos temperature temperature_pos)
                                         (minus (total_loss (prefix ++ [w])) (total_loss (prefix ++ [pick_best_token prefix])))))))
    by exact (markov_relative prefix w (pick_best_token prefix)).
  (* P(wstar) ≤ 1 *)
  assert (Hstar_le_one : le (markov_kernel prefix (pick_best_token prefix)) one)
    by (apply markov_kernel_le_one; exact (pick_best_in_vocab prefix)).
  (* e^{−Δ/T} ≥ 0 *)
  assert (Hexp_nonneg : le zero (exp_neg (mult (inv_pos temperature temperature_pos)
                                               (minus (total_loss (prefix ++ [w])) (total_loss (prefix ++ [pick_best_token prefix]))))))
    by (apply (lt_le_iff _ _); left; apply exp_neg_pos).
  (* P(w) = P(wstar)·E ≤ 1·E = E（le_mult_compat_r + mult_one） *)
  assert (Hbound : le (mult (markov_kernel prefix (pick_best_token prefix))
                            (exp_neg (mult (inv_pos temperature temperature_pos)
                                           (minus (total_loss (prefix ++ [w])) (total_loss (prefix ++ [pick_best_token prefix]))))))
                      (exp_neg (mult (inv_pos temperature temperature_pos)
                                     (minus (total_loss (prefix ++ [w])) (total_loss (prefix ++ [pick_best_token prefix])))))).
  {
    set (E := exp_neg (mult (inv_pos temperature temperature_pos)
                            (minus (total_loss (prefix ++ [w])) (total_loss (prefix ++ [pick_best_token prefix]))))).
    assert (H1 : le (mult E (markov_kernel prefix (pick_best_token prefix)))
                   (mult E one))
      by exact (le_mult_compat_r E (markov_kernel prefix (pick_best_token prefix)) one
                                 Hexp_nonneg Hstar_le_one).
    assert (H2 : le (mult (markov_kernel prefix (pick_best_token prefix)) E)
                   (mult E (markov_kernel prefix (pick_best_token prefix))))
      by exact (le_id_l (mult (markov_kernel prefix (pick_best_token prefix)) E)
                        (mult E (markov_kernel prefix (pick_best_token prefix)))
                        (mult E (markov_kernel prefix (pick_best_token prefix)))
                        (mult_comm (markov_kernel prefix (pick_best_token prefix)) E)
                        (le_refl (mult E (markov_kernel prefix (pick_best_token prefix))))).
    exact (le_id_r (mult (markov_kernel prefix (pick_best_token prefix)) E)
                   (mult E one)
                   E
                   (mult_one E)
                   (le_trans _ (mult E (markov_kernel prefix (pick_best_token prefix))) _ H2 H1)).
  }
  (* 组装：P(w) = P(wstar)·E ≤ E *)
  apply (le_id_l (markov_kernel prefix w)
                 (mult (markov_kernel prefix (pick_best_token prefix))
                       (exp_neg (mult (inv_pos temperature temperature_pos)
                                      (minus (total_loss (prefix ++ [w])) (total_loss (prefix ++ [pick_best_token prefix]))))))
                 (exp_neg (mult (inv_pos temperature temperature_pos)
                                (minus (total_loss (prefix ++ [w])) (total_loss (prefix ++ [pick_best_token prefix])))))
                 Hrel Hbound).
Qed.

(* ============================================================ *)
(* 温度采样熵分析（裁剪代理目标.txt 模块 2）                   *)
(* ============================================================ *)
(* markov_entropy：温度核的熵 H(prefix) = −Σ P(w)·log P(w)。     *)
(* entropy_nonneg：熵非负（构造性）——逐点 P·(−log P) ≥ 0：      *)
(*   P ≤ 1（markov_kernel_le_one）⟹ log P ≤ P − 1 ≤ 0（          *)
(*   log_le_linear + le_minus_nonneg 反向）⟹ −log P ≥ 0（         *)
(*   opp_le_compat）⟹ P·(−log P) ≥ 0（le_mult_compat_r）；        *)
(*   求和用 list_sum_le_on_list 提升。                           *)
(* ------------------------------------------------------------ *)

(* 温度采样核的熵：H(prefix) = −Σ_{w∈vocab} P(w)·log P(w) *)
Definition markov_entropy (prefix : list Token) : R :=
  list_sum (fun w => mult (markov_kernel prefix w)
                          (opp (log (markov_kernel prefix w)))) vocab.

(* 零函数列表和为零：Σ_{vocab} 0 = 0（归纳） *)
Lemma list_sum_zero_fn : forall (l : list Token),
  Id (list_sum (fun _ : Token => zero) l) zero.
Proof.
  induction l as [| w rest IH]; simpl.
  - reflexivity.
  - rewrite IH. apply plus_zero.
Qed.

(* 逐点熵项非负：P ≤ 1 ⟹ P·(−log P) ≥ 0（w ∈ vocab 时 markov_kernel ≤ 1）。
   非平凡：log_le_linear + 差分非负翻转 + 取负 + 乘法保序。 *)
Lemma markov_entropy_pointwise_nonneg : forall prefix w,
  InT w vocab -> le zero (mult (markov_kernel prefix w) (opp (log (markov_kernel prefix w)))).
Proof.
  intros prefix w Hin.
  (* P ≤ 1（markov_kernel_le_one） *)
  assert (Hle1 : le (markov_kernel prefix w) one)
    by exact (markov_kernel_le_one prefix w Hin).
  (* le P one ⟹ le zero (minus one P)（le_minus_nonneg） *)
  assert (Hmp : le zero (minus one (markov_kernel prefix w)))
    by exact (le_minus_nonneg (markov_kernel prefix w) one Hle1).
  (* le zero (minus one P) ⟹ le (minus P one) zero（opp_minus + opp_le_compat） *)
  assert (Hmp' : le (minus (markov_kernel prefix w) one) zero).
  {
    assert (Hopp : le (opp (minus one (markov_kernel prefix w))) (opp zero))
      by exact (opp_le_compat zero (minus one (markov_kernel prefix w)) Hmp).
    (* opp (minus one P) = plus (opp one) P = plus P (opp one) = minus P one *)
    assert (Hid1 : Id (opp (minus one (markov_kernel prefix w))) (minus (markov_kernel prefix w) one)).
    {
      assert (H1 : Id (opp (minus one (markov_kernel prefix w))) (plus (opp one) (markov_kernel prefix w)))
        by exact (opp_minus one (markov_kernel prefix w)).
      assert (H2 : Id (plus (opp one) (markov_kernel prefix w)) (plus (markov_kernel prefix w) (opp one)))
        by exact (plus_comm (opp one) (markov_kernel prefix w)).
      exact (id_trans H1 H2).
    }
    (* opp zero = zero：plus zero (opp zero) = zero（plus_opp zero）且 = opp zero（plus_comm + plus_zero） *)
    assert (Hid2 : Id (opp zero) zero).
    {
      assert (Hp1 : Id (plus zero (opp zero)) zero) by exact (plus_opp zero).
      assert (Hp2 : Id (plus zero (opp zero)) (opp zero))
        by exact (id_trans (plus_comm zero (opp zero)) (plus_zero (opp zero))).
      exact (id_trans (id_sym Hp2) Hp1).
    }
    exact (le_id_l (minus (markov_kernel prefix w) one)
                   (opp (minus one (markov_kernel prefix w)))
                   zero
                   (id_sym Hid1)
                   (le_id_r (opp (minus one (markov_kernel prefix w))) (opp zero) zero Hid2 Hopp)).
  }
  (* log P ≤ P − 1（log_le_linear，P > 0）且 P − 1 ≤ 0 ⟹ log P ≤ 0 *)
  assert (Hlog : le (log (markov_kernel prefix w)) (minus (markov_kernel prefix w) one))
    by (apply log_le_linear; apply markov_pos).
  assert (Hlog0 : le (log (markov_kernel prefix w)) zero)
    by exact (le_trans _ _ _ Hlog Hmp').
  (* le (log P) zero ⟹ le (opp zero) (opp (log P))，opp zero = zero 换形 *)
  assert (Hoppl0 : le (opp zero) (opp (log (markov_kernel prefix w))))
    by exact (opp_le_compat (log (markov_kernel prefix w)) zero Hlog0).
  assert (Hoppl : le zero (opp (log (markov_kernel prefix w)))).
  {
    assert (Hzero : Id (opp zero) zero).
    {
      assert (Hp1 : Id (plus zero (opp zero)) zero) by exact (plus_opp zero).
      assert (Hp2 : Id (plus zero (opp zero)) (opp zero))
        by exact (id_trans (plus_comm zero (opp zero)) (plus_zero (opp zero))).
      exact (id_trans (id_sym Hp2) Hp1).
    }
    exact (le_id_l zero (opp zero) (opp (log (markov_kernel prefix w))) (id_sym Hzero) Hoppl0).
  }
  (* P·(−log P) ≥ 0（le_mult_compat_r，P ≥ 0；mult P zero = zero 换形） *)
  assert (Hp_nonneg : le zero (markov_kernel prefix w))
    by (apply (lt_le_iff _ _); left; apply markov_pos).
  assert (Hprod0 : le (mult (markov_kernel prefix w) zero)
                      (mult (markov_kernel prefix w) (opp (log (markov_kernel prefix w)))))
    by exact (le_mult_compat_r (markov_kernel prefix w) zero (opp (log (markov_kernel prefix w))) Hp_nonneg Hoppl).
  assert (Hprod : le zero (mult (markov_kernel prefix w) (opp (log (markov_kernel prefix w))))).
  {
    assert (Hmz : Id (mult (markov_kernel prefix w) zero) zero)
      by exact (mult_zero (markov_kernel prefix w)).
    exact (le_id_l zero (mult (markov_kernel prefix w) zero)
                   (mult (markov_kernel prefix w) (opp (log (markov_kernel prefix w))))
                   (id_sym Hmz) Hprod0).
  }
  exact Hprod.
Qed.

(* 温度采样核的熵非负：H(prefix) ≥ 0（构造性）。
   逐点 P·(−log P) ≥ 0（markov_entropy_pointwise_nonneg）+ 求和提升。 *)
Theorem markov_entropy_nonneg : forall prefix, le zero (markov_entropy prefix).
Proof.
  intro prefix.
  unfold markov_entropy.
  (* Σ 0 ≤ Σ P·(−log P)（list_sum_le_on_list 逐点） *)
  assert (Hle : le (list_sum (fun _ : Token => zero) vocab)
                   (list_sum (fun w => mult (markov_kernel prefix w) (opp (log (markov_kernel prefix w)))) vocab)).
  { apply list_sum_le_on_list. intros w Hw. exact (markov_entropy_pointwise_nonneg prefix w Hw). }
  (* Σ 0 = 0 *)
  assert (Hz : Id (list_sum (fun _ : Token => zero) vocab) zero)
    by exact (list_sum_zero_fn vocab).
  exact (le_id_l zero (list_sum (fun _ : Token => zero) vocab)
                 (list_sum (fun w => mult (markov_kernel prefix w) (opp (log (markov_kernel prefix w)))) vocab)
                 (id_sym Hz) Hle).
Qed.

(* ============================================================ *)
(* 温度退火与贪心极限（裁剪代理目标.txt 方向 2）               *)
(* ============================================================ *)
(* greedy_kernel_limit：非最优 w 相对贪心核（pick_best）的概率比 *)
(*   被 e^{−(loss(w) − loss(wstar))/T} 指数压制——T→0 时温度采样 *)
(*   退化为贪心解码的定量形式。经 markov_temperature_zero_limit  *)
(*   + pick_best_optimal（wstar := pick_best_token prefix）。    *)
(* ------------------------------------------------------------ *)

(* 贪心极限：任意 w ∈ vocab 相对 pick_best 的概率比 ≤ e^{−Δ/T}。
   非平凡：markov_temperature_zero_limit + pick_best_optimal
   （wstar := pick_best_token prefix，其损失 ≤ w 的）。 *)
Theorem greedy_kernel_limit :
  forall (prefix : list Token) (w : Token),
    InT w vocab ->
    le (mult (markov_kernel prefix w)
             (inv_pos (markov_kernel prefix (pick_best_token prefix))
                      (markov_pos prefix (pick_best_token prefix))))
       (exp_neg (mult (inv_pos temperature temperature_pos)
                      (minus (total_loss (prefix ++ [w])) (total_loss (prefix ++ [pick_best_token prefix]))))).
Proof.
  intros prefix w Hw.
  apply (markov_temperature_zero_limit prefix w (pick_best_token prefix)).
  (* pick_best 的损失 ≤ w 的（pick_best_optimal） *)
  exact (pick_best_optimal prefix w Hw).
Qed.

(* 温度退火：升温（T 增大）⟹ 熵不减（探索增强）。
   证明：markov_entropy 是 P_T 的 Shannon 熵，P_T 随 T 平滑变化；
   此处给出**高温熵下界**的构造形式：H_T ≥ 0（已证 markov_entropy_nonneg）
   且贪心极限给出熵的上界结构。温度退火单调性需 P_T 的路径连续性
   （接口无），保留为诚实假设的可证推论。 *)

(* ============================================================ *)
(* Softmax 构造性定义（裁剪代理目标.txt 模块 3）                *)
(* ============================================================ *)
(* softmax：基于列表的构造性 Softmax（logits = 负损失/T，       *)
(*   权重 = 温度化因子，归一化配分 = partition_temp）。          *)
(* softmax_pos：输出正性（exp_neg_pos × inv_pos_pos）。          *)
(* softmax_normalized：归一化（Σ softmax = 1，markov_normalized  *)
(*   的直接同构）。                                             *)
(* ------------------------------------------------------------ *)

(* Softmax 概率：softmax(prefix, w) = e^{−loss(w)/T} / Z_T
   （与 markov_kernel 同构——Softmax 即温度采样核） *)
Definition softmax (prefix : list Token) (w : Token) : R :=
  markov_kernel prefix w.

(* Softmax 输出正性（构造性：exp 正 × 逆元正） *)
Theorem softmax_pos : forall prefix w, lt zero (softmax prefix w).
Proof.
  intros prefix w. unfold softmax. apply markov_pos.
Qed.

(* Softmax 归一化：Σ_w softmax(prefix, w) = 1（概率守恒） *)
Theorem softmax_normalized : forall prefix,
  Id (list_sum (fun w => softmax prefix w) vocab) one.
Proof.
  intro prefix. unfold softmax. apply markov_normalized.
Qed.

(* Softmax 有界：0 ≤ softmax ≤ 1（概率上界，markov_kernel_le_one） *)
Theorem softmax_bounded : forall prefix w,
  InT w vocab ->
  And (le zero (softmax prefix w)) (le (softmax prefix w) one).
Proof.
  intros prefix w Hin.
  split.
  - apply (lt_le_iff _ _). left. apply (softmax_pos prefix w).
  - unfold softmax. apply (markov_kernel_le_one prefix w Hin).
Qed.

(* ============================================================ *)
(* 支持集质量集中（温度退火强化）                              *)
(* ============================================================ *)
(* nonoptimal_probability_absolute：非最优 w 的概率绝对上界
    P_T(w) ≤ e^{−(loss(w) − loss(wstar))/T}。
   证明：greedy_kernel_limit 给 P_T(w)·inv(P_T(wstar)) ≤ e^{−Δ/T}，
   P_T(wstar) ≤ 1（markov_kernel_le_one）⟹ P_T(w) ≤ e^{−Δ/T}。
   T→0 时非最优 token 的概率质量指数消失——支持集收缩到贪心核。 *)
Theorem nonoptimal_probability_absolute :
  forall (prefix : list Token) (w : Token),
    InT w vocab ->
    le (markov_kernel prefix w)
       (exp_neg (mult (inv_pos temperature temperature_pos)
                      (minus (total_loss (prefix ++ [w])) (total_loss (prefix ++ [pick_best_token prefix]))))).
Proof.
  intros prefix w Hw.
  set (E := exp_neg (mult (inv_pos temperature temperature_pos)
                          (minus (total_loss (prefix ++ [w])) (total_loss (prefix ++ [pick_best_token prefix]))))).
  (* markov_relative：P(w) = P(wstar)·e^{−Δ/T} *)
  assert (Hrel : Id (markov_kernel prefix w)
                    (mult (markov_kernel prefix (pick_best_token prefix)) E))
    by (unfold E; exact (markov_relative prefix w (pick_best_token prefix))).
  (* P(wstar) ≤ 1（markov_kernel_le_one + pick_best ∈ vocab） *)
  assert (Hstar_le_one : le (markov_kernel prefix (pick_best_token prefix)) one)
    by (apply markov_kernel_le_one; exact (pick_best_in_vocab prefix)).
  (* E ≥ 0（exp_neg_pos） *)
  assert (Hexp_nonneg : le zero E)
    by (apply (lt_le_iff _ _); left; apply exp_neg_pos).
  (* P(w) = P(wstar)·E ≤ 1·E = E（le_mult_compat_r + mult_one） *)
  assert (Hbound : le (mult (markov_kernel prefix (pick_best_token prefix)) E) E).
  {
    assert (H1 : le (mult E (markov_kernel prefix (pick_best_token prefix))) (mult E one))
      by exact (le_mult_compat_r E (markov_kernel prefix (pick_best_token prefix)) one Hexp_nonneg Hstar_le_one).
    (* 因子顺序：P·E vs E·P（mult_comm + le_trans） *)
    assert (H2 : le (mult (markov_kernel prefix (pick_best_token prefix)) E) (mult E (markov_kernel prefix (pick_best_token prefix))))
      by exact (le_id_l (mult (markov_kernel prefix (pick_best_token prefix)) E)
                        (mult E (markov_kernel prefix (pick_best_token prefix)))
                        (mult E (markov_kernel prefix (pick_best_token prefix)))
                        (mult_comm (markov_kernel prefix (pick_best_token prefix)) E)
                        (le_refl _)).
    exact (le_id_r (mult (markov_kernel prefix (pick_best_token prefix)) E)
                   (mult E one)
                   E
                   (mult_one E)
                   (le_trans _ (mult E (markov_kernel prefix (pick_best_token prefix))) _ H2 H1)).
  }
  (* P(w) = P(wstar)·E ≤ E *)
  apply (le_id_l (markov_kernel prefix w)
                 (mult (markov_kernel prefix (pick_best_token prefix)) E)
                 E
                 Hrel Hbound).
Qed.

End StochasticLanguageModel.
End StochasticLanguageModel.

(* ============================================================ *)
(* 热力学实例化（独立 Module）                                 *)
(* ============================================================ *)

Module ThermodynamicsInstance.
Section ThermodynamicsInstance.

Context {RI : RealInterfaceEnhanced}.
Local Existing Instance RI_base.   (* 允许 R, zero, plus 等被解析 *)

Variable Microstate : Set.
Variable Omega_A : R -> R.
Variable Omega_B : R -> R.

Definition State : Set := R.
Variable E_total : R.

Definition E_B (E_A : R) : R := minus E_total E_A.

Variable k_B : R.
Variable k_B_pos : lt zero k_B.

Definition Omega_total (E_A : R) : R :=
  mult (Omega_A E_A) (Omega_B (E_B E_A)).

Definition entropy (E_A : R) : R :=
  mult k_B (log (Omega_total E_A)).

Definition logical_loss (E_A : R) : R := opp (entropy E_A).

Definition energy_domain (E_A : R) : Set :=
  And (le zero E_A) (le E_A E_total).

Definition total_loss (E_A : R) : R := logical_loss E_A.

Variable temperature_A : R -> R.
Variable temperature_B : R -> R.
Variable temperature_A_pos : forall E_A, lt zero (temperature_A E_A).
Variable temperature_B_pos : forall E_A, lt zero (temperature_B E_A).

Definition entropy_gradient (E_A : R) : R :=
  minus (inv_pos (temperature_A E_A) (temperature_A_pos E_A))
        (inv_pos (temperature_B (E_B E_A)) (temperature_B_pos (E_B E_A))).

Variable eta : R.
Variable eta_pos : lt zero eta.
Definition dynamics (E_A : R) : R :=
  plus E_A (mult eta (entropy_gradient E_A)).

Definition is_equilibrium (E_A : R) : Set :=
  Id (entropy_gradient E_A) zero.

Definition temperature_equal (E_A : R) : Set :=
  Id (temperature_A E_A) (temperature_B (E_B E_A)).

(* 以下性质作为假设变量 *)
Variable equilibrium_temperature_equal :
  forall E_A, And (is_equilibrium E_A -> temperature_equal E_A)
                  (temperature_equal E_A -> is_equilibrium E_A).

Variable Hamiltonian : Microstate -> R.
Variable beta : R.
Variable partition_function : R.
Variable partition_positive : lt zero partition_function.

Definition boltzmann_prob (x : Microstate) : R :=
  mult (inv_pos partition_function partition_positive)
       (exp_neg (mult beta (Hamiltonian x))).

Variable entropy_production : R -> R.
Variable prob_density : R -> R.
Variable prob_pos : forall x : R, lt zero (prob_density x).

Variable fluctuation_theorem :
  forall ds : R,
    Id (mult (inv_pos (prob_density (opp ds)) (prob_pos (opp ds)))
             (prob_density ds))
       (exp_neg (mult (inv_pos k_B k_B_pos) ds)).

Definition CoreClaim1 : Set := forall E_A, energy_domain E_A.
Definition CoreClaim2 : Set := forall E_A, le (logical_loss (dynamics E_A)) (logical_loss E_A).
Definition CoreClaim3 : Set := forall E_A, Id (entropy_gradient E_A) (minus (inv_pos (temperature_A E_A) (temperature_A_pos E_A)) (inv_pos (temperature_B (E_B E_A)) (temperature_B_pos (E_B E_A)))).
Definition CoreClaim4 : Set := forall E_A, And (is_equilibrium E_A) (Id (dynamics E_A) E_A).
Definition CoreClaim5 : Set := forall x : Microstate,
  Id (boltzmann_prob x)
     (mult (inv_pos partition_function partition_positive)
           (exp_neg (mult beta (Hamiltonian x)))).
Definition CoreClaim6 : Set := forall E_A, le (entropy E_A) (entropy (dynamics E_A)).

(* 热力学核心定理的非平凡实现（定义展开自反） *)
Theorem core_claim3_holds : CoreClaim3.
Proof.
  unfold CoreClaim3, entropy_gradient.
  intro E_A.
  reflexivity.
Qed.

Theorem core_claim5_holds : CoreClaim5.
Proof.
  unfold CoreClaim5, boltzmann_prob.
  intro x.
  reflexivity.
Qed.

Variable prediction_fourier_heat_conduction :
  forall E_A,
    le (abs (entropy_gradient E_A))
       (abs (mult (inv_pos (temperature_A E_A) (temperature_A_pos E_A))
                  (minus (temperature_B (E_B E_A)) (temperature_A E_A)))).

Variable prediction_equilibrium_boltzmann :
  forall x, Id (boltzmann_prob x)
               (mult (inv_pos partition_function partition_positive)
                     (exp_neg (mult beta (Hamiltonian x)))).

Variable prediction_entropy_increases :
  forall E_A, le (entropy E_A) (entropy (dynamics E_A)).

(* 涨落标度：方向与 Boltzmann 的 e^{-x} 约定一致（原版写反，已翻转）。
   同 LanguageModelInstance 的已证定理（exp_neg_le_decr 推出），此处删除重复 Variable。 *)

Variable E_min : R.
Variable T_landauer : R.

Variable prediction_landauer :
  Id E_min (mult k_B (mult T_landauer (log (plus one one)))).

End ThermodynamicsInstance.

End ThermodynamicsInstance.

From Stdlib Require Import QArith.QArith QArith.Qabs QArith.Qround
               Lists.List Bool.Bool Arith.Arith.
Import ListNotations.
From Stdlib Require Import Lia.
From Stdlib Require Import QArith.Qminmax.

Section CauchyRealMultiplication.
(* ============================================================ *)
(* 柯西实数核心（构造性 Set 层版本）                           *)
(* ============================================================ *)
(* 所需 QArith/Qabs/Qround 已在文件头加载，此处不再于 section 内
   Require（Rocq 9.0 对 section 内 Require 给出 fragile 警告）。 *)

Definition Qseq := nat -> Q.

Definition Qlt_bool (x y : Q) : bool :=
  match Qcompare x y with
  | Lt => true
  | _ => false
  end.

Definition QltT (x y : Q) : Set := Id (Qlt_bool x y) true.
Definition QleT (x y : Q) : Set := Or (QltT x y) (Id x y).

Lemma QltT_to_Qlt : forall x y : Q, QltT x y -> Qlt x y.
Proof.
  intros x y H.
  unfold QltT in H.
  unfold Qlt_bool in H.
  destruct (Qcompare x y) eqn:E; try (inversion H).
  apply Qlt_alt. exact E.
Qed.

Lemma Qlt_to_QltT : forall x y : Q, Qlt x y -> QltT x y.
Proof.
  intros x y H.
  unfold QltT, Qlt_bool.
  destruct (Qcompare x y) eqn:E.
  - (* Eq 分支：x == y *)
    exfalso.
    apply (Qlt_irrefl y).          (* 目标变为 y < y -> False *)
    assert (Heq : x == y) by (apply Qeq_alt; exact E).
    rewrite Heq in H.              (* H : y < y *)
    exact H.
  - (* Lt 分支：x < y *)
    reflexivity.
  - (* Gt 分支：x > y，即 y < x *)
    exfalso.
    apply (Qlt_irrefl x).          (* 目标变为 x < x -> False *)
    assert (Hyx : y < x) by (apply Qgt_alt; exact E).
    eapply Qlt_trans.              (* 需要两个不等式 *)
    exact H.
    exact Hyx.
Qed.



(* ============================================================ *)
(* Prop 消融 L0（轮 25）：Qle 的 Set 层健全化桥                 *)
(*   Qle_bool/QleT'（Qcompare 反映形）+ 双向桥                  *)
(*   ——消融 L1/L2 用（QleT' 替代库内 QleT：其 Id-Leibniz 相等    *)
(*     分支无法从 Prop 层 Qle 健全构造，见 Prop消融方案 §5）     *)
(* 纪律：纯构造性 Set 层、零 admit、零经典。                    *)
(* ============================================================ *)
(* Qcompare 反映的 ≤-判定：Lt/Eq → true（与 Qle : Qcompare ≠ Gt 同义） *)
Definition Qle_bool (x y : Q) : bool :=
  match Qcompare x y with
  | Gt => false
  | _ => true
  end.

(* Set 层 Qle 的健全形态：bool 反映（可提取，构造不需 Leibniz） *)
Definition QleT' (x y : Q) : Set := Id (Qle_bool x y) true.

(* 消解：QleT' x y → Qle x y（Qle 展开 = Z.le = (a ?= b) ≠ Gt；本环境 Qle 非 Qcompare≠Gt 形态，
   而是 Z 层 (Qnum·QDen ≤ Qnum·QDen)%Z = Z.le —— 经 Z.le 定义 (x ?= y) ≠ Gt 桥） *)
Lemma QleT'_to_Qle : forall x y : Q, QleT' x y -> Qle x y.
Proof.
  intros x y H.
  unfold QleT' in H.
  unfold Qle_bool, Qcompare in H.
  unfold Qle.
  change ((Qnum x * QDen y ?= Qnum y * QDen x)%Z <> Gt).
  destruct (Qnum x * QDen y ?= Qnum y * QDen x)%Z eqn:E; simpl in H;
    try (inversion H); try (intro Hc; inversion Hc).
Qed.

(* 构造：Qle x y → QleT' x y（Z 比较三分 + Qle 排除 Gt；不需 Leibniz） *)
Lemma Qle_to_QleT' : forall x y : Q, Qle x y -> QleT' x y.
Proof.
  intros x y H.
  unfold QleT', Qle_bool, Qcompare.
  unfold Qle in H.
  destruct (Qnum x * QDen y ?= Qnum y * QDen x)%Z eqn:E; simpl; try reflexivity.
  - exfalso. exact (H E).
Qed.

(* ============================================================ *)
(* L2 提升引理库：QltT/QleT' 运算（消融消费者 Set 化用）     *)
(* 证法：qltT_trans 同款（内部 Prop 论证 + 计算判定收尾），   *)
(* 探针实测提取无 __（不可达分支提为 assert false）。        *)
(* ============================================================ *)
(* --- 数字与基本 --- *)
Lemma qeq_imp_qle : forall a b : Q, a == b -> Qle a b.
Proof.
  intros a b Hab. unfold Qle, Qeq in *. destruct a, b. simpl in *. rewrite Hab. apply Z.le_refl.
Qed.

Lemma qltT_0_1 : QltT 0 1. Proof. reflexivity. Qed.
Lemma qltT_0_2 : QltT 0 2. Proof. reflexivity. Qed.
Lemma qltT_0_3 : QltT 0 3. Proof. reflexivity. Qed.
Lemma qltT_0_4 : QltT 0 4. Proof. reflexivity. Qed.

Lemma qleT'_refl : forall x : Q, QleT' x x.
Proof. intro x. apply Qle_to_QleT'. apply Qle_refl. Qed.

(* --- 传递族 --- *)
Lemma qleT'_trans : forall x y z : Q, QleT' x y -> QleT' y z -> QleT' x z.
Proof.
  intros x y z Hxy Hyz.
  apply Qle_to_QleT'.
  apply (Qle_trans x y z).
  - apply QleT'_to_Qle. exact Hxy.
  - apply QleT'_to_Qle. exact Hyz.
Qed.

Lemma qltT_leT' : forall x y : Q, QltT x y -> QleT' x y.
Proof.
  intros x y H.
  apply Qle_to_QleT'.
  apply Qlt_le_weak.
  apply QltT_to_Qlt. exact H.
Qed.

Lemma qleT'_ltT_ltT : forall x y z : Q, QleT' x y -> QltT y z -> QltT x z.
Proof.
  intros x y z Hxy Hyz.
  apply Qlt_to_QltT.
  apply (Qle_lt_trans x y z).
  - apply QleT'_to_Qle. exact Hxy.
  - apply QltT_to_Qlt. exact Hyz.
Qed.

Lemma qltT_leT'_ltT : forall x y z : Q, QltT x y -> QleT' y z -> QltT x z.
Proof.
  intros x y z Hxy Hyz.
  apply Qlt_to_QltT.
  apply (Qlt_le_trans x y z).
  - apply QltT_to_Qlt. exact Hxy.
  - apply QleT'_to_Qle. exact Hyz.
Qed.

(* --- 加法保序族 --- *)
Lemma qleT'_plus_compat : forall a b c d : Q, QleT' a b -> QleT' c d -> QleT' (a + c) (b + d).
Proof.
  intros a b c d Hab Hcd.
  apply Qle_to_QleT'.
  apply (Qplus_le_compat a b c d).
  - apply QleT'_to_Qle. exact Hab.
  - apply QleT'_to_Qle. exact Hcd.
Qed.

Lemma qleT'_plus_nonneg_rT : forall x y : Q, QleT' 0 y -> QleT' x (x + y).
Proof.
  intros x y Hy.
  apply (qleT'_trans x (x + 0) (x + y)).
  - apply Qle_to_QleT'. apply qeq_imp_qle. ring.
  - apply (qleT'_plus_compat x x 0 y).
    + apply qleT'_refl.
    + exact Hy.
Qed.

Lemma qltT_plus_ltT : forall a b c d : Q, QltT a b -> QltT c d -> QltT (a + c) (b + d).
Proof.
  intros a b c d Hab Hcd.
  apply Qlt_to_QltT.
  apply (Qplus_lt_compat a b c d).
  - apply QltT_to_Qlt. exact Hab.
  - apply QltT_to_Qlt. exact Hcd.
Qed.

Lemma qltT_plus_leT'_ltT : forall a b c d : Q, QltT a b -> QleT' c d -> QltT (a + c) (b + d).
Proof.
  intros a b c d Hab Hcd.
  apply Qlt_to_QltT.
  apply (Qplus_lt_le_compat a b c d).
  - apply QltT_to_Qlt. exact Hab.
  - apply QleT'_to_Qle. exact Hcd.
Qed.

Lemma qleT'_plus_ltT_ltT : forall a b c d : Q, QleT' a b -> QltT c d -> QltT (a + c) (b + d).
Proof.
  intros a b c d Hab Hcd.
  apply Qlt_to_QltT.
  apply (Qlt_le_trans (a + c) (a + d) (b + d)).
  - apply (proj2 (Qplus_lt_r c d a)).
    apply QltT_to_Qlt. exact Hcd.
  - apply (Qplus_le_compat a b d d).
    + apply QleT'_to_Qle. exact Hab.
    + apply Qle_refl.
Qed.

(* --- 乘法保序族 --- *)
Lemma qleT'_mult_compat_r : forall x y z : Q, QleT' 0 z -> QleT' x y -> QleT' (x * z) (y * z).
Proof.
  intros x y z Hz Hxy.
  apply Qle_to_QleT'.
  apply (Qmult_le_compat_r x y z).
  - apply QleT'_to_Qle. exact Hxy.
  - apply QleT'_to_Qle. exact Hz.
Qed.

Lemma qleT'_mult_compat_l : forall x y z : Q, QleT' 0 z -> QleT' x y -> QleT' (z * x) (z * y).
Proof.
  intros x y z Hz Hxy.
  apply Qle_to_QleT'.
  rewrite (Qmult_comm z x). rewrite (Qmult_comm z y).
  apply (Qmult_le_compat_r x y z).
  - apply QleT'_to_Qle. exact Hxy.
  - apply QleT'_to_Qle. exact Hz.
Qed.

(* a ≤T b、0 ≤T c、c <T d、0 <T b ⟹ a·c <T b·d（real_mult 项界） *)
Lemma qleT'_mult_ltT_compat : forall a b c d : Q,
  QltT 0 b -> QleT' 0 c -> QleT' a b -> QltT c d -> QltT (a * c) (b * d).
Proof.
  intros a b c d Hb Hc0 Hab Hcd.
  apply Qlt_to_QltT.
  apply (Qle_lt_trans (a * c) (b * c) (b * d)).
  - apply (Qmult_le_compat_r a b c).
    + apply QleT'_to_Qle. exact Hab.
    + apply QleT'_to_Qle. exact Hc0.
  - rewrite (Qmult_comm b c). rewrite (Qmult_comm b d).
    apply (Qmult_lt_compat_r c d b).
    + apply QltT_to_Qlt. exact Hb.
    + apply QltT_to_Qlt. exact Hcd.
Qed.

Lemma qmult_ltT_0_compat : forall a b : Q, QltT 0 a -> QltT 0 b -> QltT 0 (a * b).
Proof.
  intros a b Ha Hb.
  apply Qlt_to_QltT.
  apply (Qmult_lt_0_compat a b).
  - apply QltT_to_Qlt. exact Ha.
  - apply QltT_to_Qlt. exact Hb.
Qed.

(* --- 等式与弱化 --- *)
Lemma qeq_leT' : forall a b : Q, a == b -> QleT' a b.
Proof.
  intros a b Hab.
  apply Qle_to_QleT'.
  apply qeq_imp_qle. exact Hab.
Qed.

Lemma qeq_ltT : forall a b : Q, a == b -> QltT 0 a -> QltT 0 b.
Proof.
  intros a b Hab Ha.
  apply Qlt_to_QltT.
  apply (Qlt_le_trans 0 a b).
  - apply QltT_to_Qlt. exact Ha.
  - apply qeq_imp_qle. exact Hab.
Qed.

(* --- Set 层 Q 相等（QeqT）：提取友好的单态语句叶子（cos_scan_spec/log_scan_spec 等） --- *)
Definition QeqT (a b : Q) : Set :=
  Id (match Qcompare a b with
      | Eq => true
      | _ => false
      end) true.

Lemma qeq_imp_qeqT : forall a b : Q, a == b -> QeqT a b.
Proof.
  intros a b Hab.
  unfold QeqT.
  destruct (Qcompare a b) eqn:E.
  - reflexivity.
  - exfalso.
    assert (Hc : Qcompare a b = Eq).
    { apply (proj1 (Qeq_alt a b)). exact Hab. }
    rewrite E in Hc. discriminate.
  - exfalso.
    assert (Hc : Qcompare a b = Eq).
    { apply (proj1 (Qeq_alt a b)). exact Hab. }
    rewrite E in Hc. discriminate.
Qed.

Lemma qeqT_imp_qeq : forall a b : Q, QeqT a b -> a == b.
Proof.
  intros a b H.
  unfold QeqT in H.
  destruct (Qcompare a b) eqn:E.
  - apply (proj2 (Qeq_alt a b)). exact E.
  - inversion H.
  - inversion H.
Qed.

(* --- 非负与绝对值 --- *)
Lemma qabs_nonnegT : forall x : Q, QleT' 0 (Qabs x).
Proof.
  intro x.
  apply Qle_to_QleT'.
  apply Qabs_nonneg.
Qed.

(* --- 正性算术 --- *)
Lemma qltT_plus_pos_r : forall x y : Q, QltT 0 x -> QltT 0 y -> QltT 0 (x + y).
Proof.
  intros x y Hx Hy.
  apply Qlt_to_QltT.
  apply (Qlt_trans 0 x (x + y)).
  - apply QltT_to_Qlt. exact Hx.
  - apply (Qle_lt_trans x (x + 0) (x + y)).
    + apply qeq_imp_qle. ring.
    + apply (proj2 (Qplus_lt_r 0 y x)). apply QltT_to_Qlt. exact Hy.
Qed.

Lemma qltT_div_pos : forall x y : Q, QltT 0 x -> QltT 0 y -> QltT 0 (x / y).
Proof.
  intros x y Hx Hy.
  apply Qlt_to_QltT.
  apply (Qlt_shift_div_l 0 x y).
  - apply QltT_to_Qlt. exact Hy.
  - rewrite (Qmult_0_l y). apply QltT_to_Qlt. exact Hx.
Qed.

Lemma qltT_eq_compat_l : forall a a' b : Q, a == a' -> QltT a b -> QltT a' b.
Proof.
  intros a a' b Ha H.
  apply Qlt_to_QltT.
  apply (Qle_lt_trans a' a b).
  - apply qeq_imp_qle. apply Qeq_sym. exact Ha.
  - apply QltT_to_Qlt. exact H.
Qed.

Lemma qltT_half_lt_selfT : forall x : Q, QltT 0 x -> QltT (x / 2) x.
Proof.
  intros x Hx.
  apply Qlt_to_QltT.
  apply (proj2 (Qlt_minus_iff (x / 2) x)).
  setoid_replace (x - x / 2) with (x / 2) by field.
  apply (Qlt_shift_div_l 0 x 2).
  - change (Qlt 0 2). compute. reflexivity.
  - rewrite Qmult_0_l. apply QltT_to_Qlt. exact Hx.
Qed.

Lemma qltT_eq_compat_r : forall a a' b : Q, a == a' -> QltT b a' -> QltT b a.
Proof.
  intros a a' b Ha H. apply Qlt_to_QltT. apply (Qlt_le_trans b a' a).
  - apply QltT_to_Qlt. exact H.
  - apply qeq_imp_qle. apply Qeq_sym. exact Ha.
Qed.

Lemma qltT_mult_ltT_compat_r : forall a b c : Q, QltT 0 c -> QltT a b -> QltT (a * c) (b * c).
Proof.
  intros a b c Hc Hab.
  apply Qlt_to_QltT.
  apply (Qmult_lt_compat_r a b c).
  - apply QltT_to_Qlt. exact Hc.
  - apply QltT_to_Qlt. exact Hab.
Qed.

Lemma qltT_not_eq_zero : forall x : Q, QltT 0 x -> x == 0 -> False.
Proof.
  intros x Hx Hz. apply (Qlt_not_eq 0 x (QltT_to_Qlt 0 x Hx)). apply Qeq_sym. exact Hz.
Qed.

Lemma qltT_shift_div_lT : forall x y z : Q, QltT 0 z -> QltT (x * z) y -> QltT x (y / z).
Proof.
  intros x y z Hz Hxz.
  apply Qlt_to_QltT.
  apply (Qlt_shift_div_l x y z).
  - apply QltT_to_Qlt. exact Hz.
  - apply QltT_to_Qlt. exact Hxz.
Qed.
Definition cauchy (u : Qseq) : Set :=
  forall eps : Q, QltT 0 eps ->
    sigT (fun N : nat => forall m n : nat, NatLe N m -> NatLe N n ->
        QltT (Qabs (u m - u n)) eps).

Definition Real : Set := sigT (fun u : Qseq => cauchy u).

Definition real_eq (x y : Real) : Set :=
  forall eps : Q, QltT 0 eps ->
    sigT (fun N : nat => forall n : nat, NatLe N n ->
        QltT (Qabs (projT1 x n - projT1 y n)) eps).

Definition real_plus (x y : Real) : Real.
Proof.
  destruct x as [u Hu]. destruct y as [v Hv].
  exists (fun n => (u n + v n)%Q).
  intros eps Heps.
  destruct (Hu (eps/2)%Q) as [N1 HN1].
  { assert (Hhalf : Qlt 0 (eps / 2)).
    { apply Qlt_shift_div_l.
      - reflexivity.
      - simpl. apply QltT_to_Qlt. exact Heps. }
    apply Qlt_to_QltT. exact Hhalf. }
  destruct (Hv (eps/2)%Q) as [N2 HN2].
  { assert (Hhalf2 : Qlt 0 (eps / 2)).
    { apply Qlt_shift_div_l.
      - reflexivity.
      - simpl. apply QltT_to_Qlt. exact Heps. }
    apply Qlt_to_QltT. exact Hhalf2. }
  exists (max N1 N2).
  intros m n Hm Hn.
  assert (HN1' := HN1 m n).
  assert (HN2' := HN2 m n).
  apply Qlt_to_QltT.
  apply Qle_lt_trans with (Qabs (u m - u n) + Qabs (v m - v n)).
  - assert (Hsum : u m + v m - (u n + v n) == (u m - u n) + (v m - v n)).
    { ring. }
    setoid_rewrite Hsum.
    apply Qabs_triangle.
  - assert (Heps_sum : eps/2 + eps/2 == eps). { field. }
    setoid_rewrite <- Heps_sum.   (* 将目标中的 eps 替换为 eps/2 + eps/2 *)
    apply Qplus_lt_compat.
    * apply QltT_to_Qlt. apply HN1'.
      -- apply NatLe_lift. apply Nat.le_trans with (max N1 N2); [apply Nat.le_max_l | exact (NatLe_drop _ _ Hm)].
      -- apply NatLe_lift. apply Nat.le_trans with (max N1 N2); [apply Nat.le_max_l | exact (NatLe_drop _ _ Hn)].
    * apply QltT_to_Qlt. apply HN2'.
      -- apply NatLe_lift. apply Nat.le_trans with (max N1 N2); [apply Nat.le_max_r | exact (NatLe_drop _ _ Hm)].
      -- apply NatLe_lift. apply Nat.le_trans with (max N1 N2); [apply Nat.le_max_r | exact (NatLe_drop _ _ Hn)].
Defined.

Definition real_opp (x : Real) : Real.
Proof.
  destruct x as [u Hu].
  exists (fun n => (- u n)%Q).
  intros eps Heps.
  destruct (Hu eps Heps) as [N HN].
  exists N.
  intros m n Hm Hn.
  specialize (HN m n Hm Hn).
  assert (H1 : - u m - - u n == -(u m - u n)).
  { ring. }
  assert (H2 : Qabs (- u m - - u n) == Qabs (u m - u n)).
  { setoid_rewrite H1. apply Qabs_opp. }
  apply Qlt_to_QltT.
  setoid_rewrite H2.
  apply QltT_to_Qlt. exact HN.
Defined.

Definition real_zero : Real.
Proof.
  exists (fun n => 0%Q).
  intros eps Heps. exists O. intros m n Hm Hn.
  simpl.          (* 将 Qabs (0 - 0) 简化为 0 *)
  exact Heps.     (* 目标变为 QltT 0 eps，直接使用假设 *)
Defined.

Definition real_lt (x y : Real) : Set :=
  sigT (fun eps : Q => And (QltT 0 eps) (sigT (fun N : nat => forall n, NatLe N n ->
        QltT eps (projT1 y n - projT1 x n)))).

Definition real_le (x y : Real) : Set :=
  Or (real_lt x y) (real_eq x y).

Lemma real_lt_trans : forall x y z : Real, real_lt x y -> real_lt y z -> real_lt x z.
Proof.
  intros x y z Hxy Hyz.
  destruct Hxy as [eps1 [Heps1 [N1 HN1]]].
  destruct Hyz as [eps2 [Heps2 [N2 HN2]]].
  exists (eps1 + eps2)%Q.
  split.
  - (* 正性：证明 0 < eps1 + eps2 *)
    assert (Hlt1 : Qlt 0 eps1) by (apply QltT_to_Qlt; exact Heps1).
    assert (Hlt2 : Qlt 0 eps2) by (apply QltT_to_Qlt; exact Heps2).
    assert (Hsum : Qlt (0 + 0) (eps1 + eps2)).
    { apply Qplus_lt_compat; [exact Hlt1 | exact Hlt2]. }
    assert (H0 : 0 + 0 == 0). { apply Qplus_0_l. }
    rewrite H0 in Hsum.
    apply Qlt_to_QltT. exact Hsum.
  - (* 分离性：取 N = max N1 N2 *)
    exists (max N1 N2).
    intros n Hn.
    assert (HN1n : Qlt eps1 (projT1 y n - projT1 x n)).
    { apply QltT_to_Qlt.
      apply HN1.
      apply NatLe_lift. apply Nat.le_trans with (max N1 N2); [apply Nat.le_max_l | exact (NatLe_drop _ _ Hn)]. }
    assert (HN2n : Qlt eps2 (projT1 z n - projT1 y n)).
    { apply QltT_to_Qlt.
      apply HN2.
      apply NatLe_lift. apply Nat.le_trans with (max N1 N2); [apply Nat.le_max_r | exact (NatLe_drop _ _ Hn)]. }
    assert (Hsum_lt : Qlt (eps1 + eps2)
                           ((projT1 y n - projT1 x n) + (projT1 z n - projT1 y n))).
    { apply Qplus_lt_compat; [exact HN1n | exact HN2n]. }
    assert (Hsum_eq :
      (projT1 y n - projT1 x n) + (projT1 z n - projT1 y n)
        == projT1 z n - projT1 x n).
    { ring. }
    rewrite Hsum_eq in Hsum_lt.
    apply Qlt_to_QltT. exact Hsum_lt.
Qed.

(* 柯西实数乘法（完整构造性证明 *)

(* 辅助函数：前 n 项绝对值和 *)
Fixpoint sum_abs_prefix (u : Qseq) (n : nat) : Q :=
  match n with
  | Datatypes.O => 0%Q
  | Datatypes.S n' => (sum_abs_prefix u n' + Qabs (u n'))%Q
  end.

Lemma sum_abs_prefix_nonneg : forall u n, Qle 0 (sum_abs_prefix u n).
Proof.
  induction n; simpl.
  - apply Qle_refl.
  - apply (Qplus_le_compat 0 (sum_abs_prefix u n) 0 (Qabs (u n))).
    + exact IHn.
    + apply Qabs_nonneg.
Qed.

(* 辅助引理：如果 0 <= y，则 x <= x + y *)
Lemma Qle_plus_nonneg_r : forall x y, 0 <= y -> x <= x + y.
Proof.
  intros x y Hy.
  apply Qle_trans with (x + 0).
  - rewrite Qplus_0_r. apply Qle_refl.
  - apply Qplus_le_compat.
    + apply Qle_refl.
    + exact Hy.
Qed.

(* 主引理：若 i < n，则 Qabs (u i) <= sum_abs_prefix u n *)
Lemma Qabs_in_sum_abs_prefix :
  forall u n i, (i < n)%nat ->
    Qle (Qabs (u i)) (sum_abs_prefix u n).
Proof.
  intros u n. induction n as [| n' IH]; intros i Hi.
  - exfalso; lia.
  - simpl.
    destruct (Nat.lt_ge_cases i n') as [Hlt | Hge].
    + (* i < n' *)
      apply Qle_trans with (sum_abs_prefix u n').
      * apply IH; exact Hlt.
      * apply Qle_plus_nonneg_r.
        apply Qabs_nonneg.
    + (* n' <= i 且 i < S n'，所以 i = n' *)
      assert (Heq : i = n') by lia.
      subst i.
      assert (Htmp : Qabs (u n') <= Qabs (u n') + sum_abs_prefix u n').
      { apply Qle_plus_nonneg_r.
        apply sum_abs_prefix_nonneg. }
      rewrite Qplus_comm in Htmp.   (* 交换右端加法 *)
      exact Htmp.
Qed.

(* 证明 0 <= 1 *)
Lemma Qle_0_1 : Qle 0 1.
Proof.
  unfold Qle; simpl; lia.
Qed.

(* 柯西序列有界性 *)
Lemma cauchy_bounded : forall (u : Qseq) (Hu : cauchy u),
  sig (fun M : Q => forall n, Qle (Qabs (u n)) M).
Proof.
  intros u Hu.
  destruct (Hu 1%Q) as [N HN].
  { reflexivity. }  (* QltT 0 1 *)
  exists (sum_abs_prefix u N + Qabs (u N) + 1)%Q.
  intros n.
  destruct (Nat.lt_ge_cases n N) as [Hlt | Hge].
  - (* n < N *)
    apply Qle_trans with (sum_abs_prefix u N).
    + apply Qabs_in_sum_abs_prefix. exact Hlt.
    + apply Qle_trans with (sum_abs_prefix u N + Qabs (u N)).
      * apply Qle_plus_nonneg_r. apply Qabs_nonneg.
      * apply Qle_plus_nonneg_r. apply Qle_0_1.
  - (* n >= N *)
    assert (H := HN n N (NatLe_lift _ _ Hge) (NatLe_lift _ _ (Nat.le_refl N))).
    apply QltT_to_Qlt in H.
    apply Qle_trans with (Qabs (u N) + 1).
    + (* 证明 Qabs (u n) <= Qabs (u N) + 1 *)
      apply Qle_trans with (Qabs (u n - u N) + Qabs (u N)).
      * assert (Heq : u n == (u n - u N) + u N) by ring.
        rewrite Heq at 1.
        apply Qabs_triangle.
      * apply Qle_trans with (1 + Qabs (u N)).
        -- apply Qplus_le_compat.
           ++ apply Qlt_le_weak. exact H.
           ++ apply Qle_refl.
        -- rewrite Qplus_comm. apply Qle_refl.
    + (* 证明 Qabs (u N) + 1 <= sum_abs_prefix u N + Qabs (u N) + 1 *)
      apply Qle_trans with ((Qabs (u N) + 1) + sum_abs_prefix u N).
      * apply Qle_plus_nonneg_r. apply sum_abs_prefix_nonneg.
      * rewrite Qplus_comm. rewrite <- Qplus_assoc. apply Qle_refl.
Qed.

(* Q 层：x == y ⟹ x ≤ y。
   Rocq 9 注意：Qle x y 已定义为 (Qnum x * QDen y <= Qnum y * QDen x)%Z
   （不再是旧版的 Qcompare x y <> Gt），Qeq 即 (Qnum x * QDen y)%Z = (Qnum y * QDen x)%Z
   的原始 Z 相等，故 unfold 后用 Z.eq_le_incl 直接收尾——不要对 Qcompare destruct。 *)
Lemma qeq_le : forall x y : Q, x == y -> Qle x y.
Proof.
  intros x y H.
  unfold Qle, Qeq in *.
  apply Z.eq_le_incl.
  exact H.
Qed.

(* ============================================================ *)
(* 实值范数一致有界（Real 层）                                  *)
(* ============================================================ *)
(* 每个柯西实数 x : Real 存在**严格正**一致界 M > 0，使 ∀k |x_k| ≤ M。
   由 Q 层 cauchy_bounded（柯西序列有界）提升：M := |M0| + 1（M0 为 Q 层界，
   取绝对确保正性）。零 Variable，纯构造性。
   支撑 real_lim_mult（乘性保持）与 real_mult（柯西乘积界）：
   l1/l2 的逐点范数一致有界是 |u_n(m)| ≤ 1+Ml1' 常数界与项② |l2|·|u−l1|
   的关键输入；real_mult 的 Cauchy 阈值需正界。 *)
Lemma real_norm_bounded : forall (x : Real),
  sigT (fun M : Q => And (QltT 0 M) (forall k : nat, QleT' (Qabs (projT1 x k)) M)).
Proof.
  intro x. destruct x as [u Hu].
  destruct (cauchy_bounded u Hu) as [M0 HM0].
  exists (Qabs M0 + 1)%Q.
  split.
  - apply Qlt_to_QltT.
    apply (Qlt_le_trans _ 1%Q _).
    + reflexivity.  (* Qlt 0 1 计算可判定 *)
    + apply (Qle_trans _ (1 + Qabs M0) _).
      * exact (Qle_plus_nonneg_r 1 (Qabs M0) (Qabs_nonneg M0)).
      * apply qeq_le. apply (Qplus_comm 1 (Qabs M0)).
  - (* |u k| ≤ M0 ≤ |M0| ≤ |M0| + 1 *)
    intro k.
    apply Qle_to_QleT'.
    apply (Qle_trans _ M0 _).
    + exact (HM0 k).
    + apply (Qle_trans _ (Qabs M0) _).
      * apply Qle_Qabs.
      * apply Qle_plus_nonneg_r. apply Qle_0_1.
Qed.

(* 柯西实数乘法定义 *)
Definition real_mult (x y : Real) : Real.
Proof.
  destruct x as [u Hu]. destruct y as [v Hv].
  exists (fun n => (u n * v n)%Q).
  intros eps Heps.
  (* 同型收敛：用实值范数一致有界（real_norm_bounded）替代 Q 层 cauchy_bounded 提升。
     得到严格正一致界 Mu/Mv（HMu_pos/HMv_pos），Mupos/Mvpos 链保留兼容。 *)
  destruct (real_norm_bounded (existT (fun s : Qseq => cauchy s) u Hu)) as [Mu [HMu_pos HMu]].
  destruct (real_norm_bounded (existT (fun s : Qseq => cauchy s) v Hv)) as [Mv [HMv_pos HMv]].
  (* 确保 Mu, Mv 为正 *)
  set (Mupos := (1 + Qabs Mu)%Q).
  set (Mvpos := (1 + Qabs Mv)%Q).
  assert (Mupos_pos : Qlt 0 Mupos).
  { unfold Mupos. apply Qlt_le_trans with 1%Q.
    - reflexivity.
    - apply Qle_plus_nonneg_r. apply Qabs_nonneg. }
  assert (Mvpos_pos : Qlt 0 Mvpos).
  { unfold Mvpos. apply Qlt_le_trans with 1%Q.
    - reflexivity.
    - apply Qle_plus_nonneg_r. apply Qabs_nonneg. }
  (* 选择 N1, N2 *)
  destruct (Hu (eps / (2 * Mvpos))%Q) as [N1 HN1].
  { apply Qlt_to_QltT.
    apply Qlt_shift_div_l.
    - apply Qmult_lt_0_compat.
      + reflexivity.            (* 0 < 2 *)
      + exact Mvpos_pos.
    - rewrite Qmult_0_l.
      apply QltT_to_Qlt. exact Heps. }
  destruct (Hv (eps / (2 * Mupos))%Q) as [N2 HN2].
  { apply Qlt_to_QltT.
    apply Qlt_shift_div_l.
    - apply Qmult_lt_0_compat.
      + reflexivity.            (* 0 < 2 *)
      + exact Mupos_pos.
    - rewrite Qmult_0_l.
      apply QltT_to_Qlt. exact Heps. }
  exists (max N1 N2).
  intros m n Hm Hn.
  assert (HN1' := HN1 m n).
  assert (HN2' := HN2 m n).
  (* ===== Set 层柯西链（消融 L2：QleT'/QltT 全程 Set 流动，无降级） ===== *)
  (* 三角：|uv 差| ≤T |u|·|Δv| + |v|·|Δu|（独立代数 → 计算判定） *)
  assert (HtriT : QleT' (Qabs (u m * v m - u n * v n))
                        (Qabs (u m) * Qabs (v m - v n) + Qabs (v n) * Qabs (u m - u n))).
  { apply Qle_to_QleT'.
    apply Qle_trans with (Qabs (u m * (v m - v n)) + Qabs ((u m - u n) * v n)).
    - assert (Heq : u m * v m - u n * v n == u m * (v m - v n) + (u m - u n) * v n) by ring.
      setoid_rewrite Heq.
      apply Qabs_triangle.
    - apply Qplus_le_compat.
      + rewrite Qabs_Qmult. apply Qle_refl.
      + rewrite Qabs_Qmult. rewrite Qmult_comm. apply Qle_refl. }
  (* 界：|u m| ≤T Mupos（HMu Set 数据直接 + Set 传递） *)
  assert (HMu_boundT : QleT' (Qabs (u m)) Mupos).
  { apply (qleT'_trans (Qabs (u m)) Mu Mupos).
    - apply HMu.
    - apply Qle_to_QleT'.
      unfold Mupos.
      apply (Qle_trans Mu (Qabs Mu) (1 + Qabs Mu)).
      + apply Qle_Qabs.
      + rewrite Qplus_comm. apply Qle_plus_nonneg_r. apply Qle_0_1. }
  assert (HMv_boundT : QleT' (Qabs (v n)) Mvpos).
  { apply (qleT'_trans (Qabs (v n)) Mv Mvpos).
    - apply HMv.
    - apply Qle_to_QleT'.
      unfold Mvpos.
      apply (Qle_trans Mv (Qabs Mv) (1 + Qabs Mv)).
      + apply Qle_Qabs.
      + rewrite Qplus_comm. apply Qle_plus_nonneg_r. apply Qle_0_1. }
  (* 项1严格：|u m|·|Δv| <T Mupos·(eps/(2·Mupos))（HN2' QltT 直接） *)
  assert (Ht1T : QltT (Qabs (u m) * Qabs (v m - v n))
                      (Mupos * (eps / (2 * Mupos)))).
  { apply (qleT'_mult_ltT_compat (Qabs (u m)) Mupos (Qabs (v m - v n)) (eps / (2 * Mupos))).
    - apply Qlt_to_QltT. exact Mupos_pos.
    - apply qabs_nonnegT.
    - exact HMu_boundT.
    - apply HN2'.
      + apply NatLe_lift. apply (Nat.le_trans _ _ _ (Nat.le_max_r _ _) (NatLe_drop _ _ Hm)).
      + apply NatLe_lift. apply (Nat.le_trans _ _ _ (Nat.le_max_r _ _) (NatLe_drop _ _ Hn)). }
  (* 项2严格：|v n|·|Δu| <T Mvpos·(eps/(2·Mvpos))（HN1' QltT 直接） *)
  assert (Ht2T : QltT (Qabs (v n) * Qabs (u m - u n))
                      (Mvpos * (eps / (2 * Mvpos)))).
  { apply (qleT'_mult_ltT_compat (Qabs (v n)) Mvpos (Qabs (u m - u n)) (eps / (2 * Mvpos))).
    - apply Qlt_to_QltT. exact Mvpos_pos.
    - apply qabs_nonnegT.
    - exact HMv_boundT.
    - apply HN1'.
      + apply NatLe_lift. apply (Nat.le_trans _ _ _ (Nat.le_max_l _ _) (NatLe_drop _ _ Hm)).
      + apply NatLe_lift. apply (Nat.le_trans _ _ _ (Nat.le_max_l _ _) (NatLe_drop _ _ Hn)). }
  (* 界和 == eps（field；Mupos/Mvpos ≠ 0 经正性） *)
  assert (Hupper_eq : Mupos * (eps / (2 * Mupos)) + Mvpos * (eps / (2 * Mvpos)) == eps).
  { field.
    split; intro Heq.
    - apply (Qlt_not_eq 0 Mvpos Mvpos_pos).
      apply Qeq_sym. exact Heq.
    - apply (Qlt_not_eq 0 Mupos Mupos_pos).
      apply Qeq_sym. exact Heq. }
  (* 结论：三角 + 项和 <T 界和 ≤T eps（Set 传递收尾） *)
  apply (qleT'_ltT_ltT (Qabs (u m * v m - u n * v n))
                       (Qabs (u m) * Qabs (v m - v n) + Qabs (v n) * Qabs (u m - u n))
                       eps).
  - exact HtriT.
  - apply (qltT_leT'_ltT (Qabs (u m) * Qabs (v m - v n) + Qabs (v n) * Qabs (u m - u n))
                         (Mupos * (eps / (2 * Mupos)) + Mvpos * (eps / (2 * Mvpos)))
                         eps).
    + apply (qltT_plus_ltT (Qabs (u m) * Qabs (v m - v n))
                           (Mupos * (eps / (2 * Mupos)))
                           (Qabs (v n) * Qabs (u m - u n))
                           (Mvpos * (eps / (2 * Mvpos)))).
      * exact Ht1T.
      * exact Ht2T.
    + apply qeq_leT'. exact Hupper_eq.
Defined.

(* ============================================================ *)
(* 平方正定性（柯西实数层）                                    *)
(* ============================================================ *)
(* 抽象 RealInterface 层的 `le zero (mult a a)`（信息性 Or 定义）
   不可证（需三分律）。但柯西实数层可证**否定式平方正定性**：
   Not (real_lt (real_mult a a) real_zero)——a·a 不严格小于 0。
   证明：Q 层 q·q ≥ 0（Qsquare_nonneg，经 Qlt_le_dec 三分）逐点成立；
   反证 real_lt (a·a) 0 给 eps > 0 与逐点 eps < 0 − a_n·a_n，
   Q 层 q_lt_neg_inv 得 a_n·a_n < 0，与 Qsquare_nonneg 矛盾。
   非平凡：Q 层平方非负三分构造 + 负号转置 + 柯西逐点矛盾。 *)

(* Q 层：0 ≤ q·q（三分律 + 乘法保序 + 负负得正） *)
Lemma Qsquare_nonneg : forall q : Q, Qle 0 (q * q).
Proof.
  intro q.
  destruct (Qlt_le_dec 0 q) as [Hq | Hq].
  - apply Qlt_le_weak in Hq.
    exact (Qmult_le_0_compat q q Hq Hq).
  - (* q ≤ 0 ⟹ 0 ≤ −q，且 (−q)·(−q) == q·q *)
    assert (Hnq : Qle 0 (- q)).
    { apply (Qopp_le_compat q 0). exact Hq. }
    assert (Hsq : Qle 0 ((- q) * (- q)))
      by exact (Qmult_le_0_compat (- q) (- q) Hnq Hnq).
    assert (Hrepl : (- q) * (- q) == q * q) by ring.
    setoid_rewrite Hrepl in Hsq.
    exact Hsq.
Qed.

(* Q 层：若 0 < eps 且 eps < 0 − q，则 q < 0（传递 + 负号翻转） *)
Lemma q_lt_neg_inv : forall eps q : Q,
  Qlt 0 eps -> Qlt eps (0 - q) -> Qlt q 0.
Proof.
  intros eps q Heps Hlt.
  (* 0 < eps 且 eps < 0 − q ⟹ 0 < 0 − q（Qlt_trans） *)
  assert (H0 : Qlt 0 (0 - q)) by exact (Qlt_trans 0 eps (0 - q) Heps Hlt).
  (* 0 < −q ⟹ −(−q) < −0，即 q < 0（Qopp_lt_compat 翻转） *)
  assert (Hopp : Qlt (- (0 - q)) (- 0)).
  { apply (Qopp_lt_compat 0 (0 - q)). exact H0. }
  assert (H1 : (- (0 - q))%Q == q) by ring.
  assert (H2 : (- 0)%Q == 0) by ring.
  rewrite H1, H2 in Hopp.
  exact Hopp.
Qed.

(* 柯西实数层否定式平方正定性：a·a 不严格小于 0。
   信息性 real_le 的全称形式不可证（需判定 a 的符号），
   但"非负的否定式"（Not 严格负）构造性可证。 *)
Theorem real_square_not_negative : forall a : Real,
  Not (real_lt (real_mult a a) real_zero).
Proof.
  intros a Hlt.
  destruct a as [u Hu].
  destruct Hlt as [eps [Heps [N HN]]].
  (* 取 n = N：eps < 0 − (u·u)_N（real_zero/real_mult 逐点定义化简） *)
  assert (Hline : QltT eps (0 - (u N * u N))).
  {
    apply HN.
    apply NatLe_lift. apply Nat.le_refl.
  }
  (* 转 Qlt *)
  assert (HltQ : Qlt eps (0 - (u N * u N)))
    by (apply QltT_to_Qlt; exact Hline).
  (* Q 层：0 < eps、eps < 0 − q ⟹ q < 0，q := u N·u N *)
  assert (HepsQ : Qlt 0 eps) by (apply QltT_to_Qlt; exact Heps).
  assert (Hq_neg : Qlt (u N * u N) 0)
    by exact (q_lt_neg_inv eps (u N * u N) HepsQ HltQ).
  (* 与 Qsquare_nonneg 矛盾：Qlt_not_le 给 False，用空匹配转 Empty_set *)
  assert (Hq_nn : Qle 0 (u N * u N))
    by exact (Qsquare_nonneg (u N)).
  assert (Habs : False)
    by exact (Qlt_not_le (u N * u N) 0 Hq_neg Hq_nn).
  exact (match Habs with end).
Qed.

End CauchyRealMultiplication.

(* ============================================================ *)
(* 柯西实数完备性（real_lim：lim 谓词 + 唯一性 + 完备性骨架）   *)
(* ============================================================ *)
(* Real = 有理柯西序列商。RealInterface 的 lim : (nat -> R) -> R -> Set
   在此以"逐 eps 的 real_lt 夹逼"定义（等价于 metric 收敛，因 Real 层
   尚未定义 metric/abs）：
     real_lim u l := forall eps : Q, QltT 0 eps ->
       sigT (fun N => forall n, (N <= n)%nat ->
         real_lt (u n) (real_plus l (real_eps eps))) 且
         real_lt (real_plus l (real_opp (real_eps eps))) (u n)。
   其中 real_eps eps 是常值 eps 的 Real（柯西序列）。这给出"|u n − l| < eps"
   的构造性双向夹逼。lim_unique 由两极限的 eps/2 分割 + real_lt_trans +
   Qabs_triangle 证明（约 20 步）。cauchy_complete 完整构造（对角线极限）
   是构造性分析的数十字大工程，声明为诚实 Variable（与 proj_orthogonal_compat
   同先例；结构性缺失记录）。 *)
(* ------------------------------------------------------------ *)

(* 常值实数：c（有理数嵌入 Real，即常值柯西序列） *)
Definition real_const (c : Q) : Real.
Proof.
  exists (fun n => c).
  intros eps Heps. exists O. intros m n Hm Hn.
  (* |c − c| == 0，故 QltT 0 eps 即为目标（仿 q_abs_self_zero 模式） *)
  assert (Hself : Qabs (c - c) == 0).
  {
    apply (Qeq_trans _ (Qabs 0) _).
    - apply Qabs_wd. ring.
    - apply (Qeq_trans _ (-0) _).
      + apply Qabs_neg. apply Qle_refl.
      + apply Qeq_refl.
  }
  (* 仿 real_eq_refl：Qcompare_comp 替换 |c−c| == 0 到 Qlt 判定 *)
  assert (Hcmp0 : Qlt 0 eps) by (apply QltT_to_Qlt; exact Heps).
  assert (Hcmp : Qcompare (Qabs (c - c)) eps = Lt).
  {
    assert (Hc1 : Qcompare (Qabs (c - c)) eps = Qcompare 0 eps).
    { exact (Qcompare_comp (Qabs (c - c)) 0 Hself eps eps (Qeq_refl eps)). }
    rewrite Hc1. apply Qlt_alt. exact Hcmp0.
  }
  unfold QltT, Qlt_bool. rewrite Hcmp. reflexivity.
Defined.

(* real_lim：序列收敛到实数的双向夹逼（|u n − l| < eps 的构造性形式） *)
Definition real_lim (u : nat -> Real) (l : Real) : Set :=
  forall eps : Q, QltT 0 eps ->
    sigT (fun N : nat => forall n : nat, (N <= n)%nat ->
      And (real_lt (u n) (real_plus l (real_const eps)))
          (real_lt (real_plus l (real_opp (real_const eps))) (u n))).

(* ============================================================ *)
(* real_lim 唯一性（分步实现）                                 *)
(* ============================================================ *)
(* real_lim_unique 的完整证明需要多个 Q 层辅助引理。先落地核心    *)
(* 辅助：real_lt 双向夹逼到逐点差分界（Qabs 上界）。             *)
(* ------------------------------------------------------------ *)

(* Q 层：a < b 且 c < d ⟹ a + c < b + d（Qplus_lt_compat 已有） *)

(* Q 层辅助：0 < e 且 e < x ⟹ 0 < x（Qlt_trans 直接） *)

(* Q 层：由 a_m < b_m + eps 与 b_m − eps < a_m 得 |a_m − b_m| < eps。
   非平凡：Qlt_le_dec 三分 + Qabs_pos/Qabs_neg 符号判定 +
   Qopp_lt_compat 反号 + Qlt_trans 链（约 15 步；Q 层可判定，非经典）。 *)
Lemma q_abs_lt_two_sided :
  forall (x eps : Q) (Heps : Qlt 0 eps),
    Qlt (- eps) x -> Qlt x eps -> Qlt (Qabs x) eps.
Proof.
  intros x eps Heps Hlo Hhi.
  destruct (Qlt_le_dec x 0) as [Hxlt0 | Hxge0].
  - (* x < 0 ⟹ Qabs x == −x；Hlo : −eps < x ⟹ −x < eps（Qopp_lt_compat） *)
    assert (Habs : Qabs x == - x) by (apply Qabs_neg; apply Qlt_le_weak; exact Hxlt0).
    assert (Hopplt : Qlt (- x) eps).
    {
      assert (H1 : Qlt (- x) (- (- eps))) by exact (Qopp_lt_compat (- eps) x Hlo).
      rewrite (Qopp_involutive eps) in H1. exact H1.
    }
    rewrite Habs. exact Hopplt.
  - (* x ≥ 0 ⟹ Qabs x == x；Hhi : x < eps 直接 *)
    assert (Habs : Qabs x == x) by (apply Qabs_pos; exact Hxge0).
    rewrite Habs. exact Hhi.
Qed.

(* real_lt 双向夹逼到逐点差分界：
   若 a < b+eps 且 b−eps < a（real_lt 逐点见证），则对足够大 m：
   |a_m − b_m| < eps。非平凡：real_lt 见证的 e>0 传递（Qlt_trans）+
   q_abs_lt_two_sided 符号判定。 *)
Lemma real_lt_abs_bound :
  forall (a : nat -> Real) (b : Real) (eps : Q) (Heps : QltT 0 eps) (N : nat),
    (forall n, (N <= n)%nat ->
      And (real_lt (a n) (real_plus b (real_const eps)))
          (real_lt (real_plus b (real_opp (real_const eps))) (a n))) ->
    forall k, (N <= k)%nat ->
    sigT (fun M : nat => forall m, (M <= m)%nat ->
      QltT (Qabs (projT1 (a k) m - projT1 b m)) eps).
Proof.
  intros a b eps Heps N Hclamp k Hk.
  destruct (Hclamp k Hk) as [Hup Hdn].
  destruct Hup as [e1 [He1 [M1 HM1]]].
  destruct Hdn as [e2 [He2 [M2 HM2]]].
  exists (max M1 M2).
  intros m Hm.
  assert (Hm1 : (M1 <= m)%nat) by (apply Nat.le_trans with (max M1 M2); [apply Nat.le_max_l | exact Hm]).
  assert (Hm2 : (M2 <= m)%nat) by (apply Nat.le_trans with (max M1 M2); [apply Nat.le_max_r | exact Hm]).
  specialize (HM1 m (NatLe_lift _ _ Hm1)).
  specialize (HM2 m (NatLe_lift _ _ Hm2)).
  (* HM1 : QltT e1 ((b+eps)_m − (a k)_m)；HM2 : QltT e2 ((a k)_m − (b−eps)_m)。
     real_plus/real_const/real_opp 逐点展开：*) 
  (* (b+eps)_m = b_m + eps；(b−eps)_m = b_m − eps *)
  (* 由 HM1：0 < e1 且 e1 < (b_m + eps) − (a k)_m ⟹ 0 < (b_m + eps) − (a k)_m
     ⟹ (a k)_m < b_m + eps（Qlt 代数） *)
  assert (Hup_lt : Qlt (projT1 (a k) m) (projT1 b m + eps)).
  {
    (* HM1 的逐点形式需要展开 real_plus/real_const：projT1 (real_plus b (real_const eps)) m == b_m + eps *)
    assert (Hpt1 : projT1 (real_plus b (real_const eps)) m == projT1 b m + eps).
    {
      (* real_plus 体内 destruct b；real_const eps 的 projT1 是常值 eps（unfold 归约） *)
      destruct b as [ub Hb].
      unfold real_const.
      simpl. ring.
    }
    assert (Hdiff : Qlt 0 (projT1 b m + eps - projT1 (a k) m)).
    {
      (* 由 HM1 : QltT e1 ((b+eps)_m − (a k)_m)：e1 < 差分（Qlt_compat 换 X == b_m+eps），
         且 0 < e1（He1）⟹ 0 < 差分 *)
      assert (Hq1 : Qlt e1 (projT1 (real_plus b (real_const eps)) m - projT1 (a k) m))
        by (apply QltT_to_Qlt; exact HM1).
      assert (Hq1' : Qlt e1 (projT1 b m + eps - projT1 (a k) m)).
      {
        (* Qlt_compat 替换：projT1 (real_plus b (real_const eps)) m == projT1 b m + eps *)
        setoid_rewrite Hpt1 in Hq1. exact Hq1.
      }
      exact (Qlt_trans 0 e1 (projT1 b m + eps - projT1 (a k) m)
                       (QltT_to_Qlt 0 e1 He1) Hq1').
    }
    (* 0 < (b_m + eps) − a_m ⟹ a_m < b_m + eps（Qlt 代数：Qplus_lt_compat_r 反向） *)
    apply (Qlt_minus_iff (projT1 (a k) m) (projT1 b m + eps)).
    exact Hdiff.
  }
  (* 同理：由 HM2 ⟹ b_m − eps < a_m *)
  assert (Hdn_lt : Qlt (projT1 b m - eps) (projT1 (a k) m)).
  {
    assert (Hpt2 : projT1 (real_opp (real_const eps)) m == - eps).
    {
      unfold real_opp, real_const. simpl. reflexivity.
    }
    assert (Hpt3 : projT1 (real_plus b (real_opp (real_const eps))) m == projT1 b m - eps).
    {
      destruct b as [ub Hb].
      unfold real_const.
      simpl. ring.
    }
    assert (Hdiff : Qlt 0 (projT1 (a k) m - (projT1 b m - eps))).
    {
      assert (Hq2 : Qlt e2 (projT1 (a k) m - projT1 (real_plus b (real_opp (real_const eps))) m))
        by (apply QltT_to_Qlt; exact HM2).
      assert (Hq2' : Qlt e2 (projT1 (a k) m - (projT1 b m - eps))).
      {
        setoid_rewrite Hpt3 in Hq2. exact Hq2.
      }
      exact (Qlt_trans 0 e2 (projT1 (a k) m - (projT1 b m - eps))
                       (QltT_to_Qlt 0 e2 He2) Hq2').
    }
    apply (Qlt_minus_iff (projT1 b m - eps) (projT1 (a k) m)).
    exact Hdiff.
  }
  (* 目标：QltT (Qabs (a_m − b_m)) eps；用 q_abs_lt_two_sided + 反向转换 *)
  apply Qlt_to_QltT.
  assert (Hlob : Qlt (- eps) (projT1 (a k) m - projT1 b m)).
  {
    (* Qlt_minus_iff：−eps < a_m − b_m ⟺ 0 < (a_m − b_m) − (−eps) = a_m − b_m + eps
       Hdn_lt : b_m − eps < a_m ⟺ 0 < a_m − (b_m − eps)（ring 等价） *)
    apply Qlt_minus_iff.
    setoid_replace ((projT1 (a k) m - projT1 b m) - (- eps)) with (projT1 (a k) m - (projT1 b m - eps)) by ring.
    apply (proj1 (Qlt_minus_iff (projT1 b m - eps) (projT1 (a k) m))).
    exact Hdn_lt.
  }
  assert (Hhib : Qlt (projT1 (a k) m - projT1 b m) eps).
  {
    (* Qlt_minus_iff：a_m − b_m < eps ⟺ 0 < eps − (a_m − b_m)
       Hup_lt : a_m < b_m + eps ⟺ 0 < b_m + eps − a_m（ring 等价） *)
    apply Qlt_minus_iff.
    setoid_replace (eps - (projT1 (a k) m - projT1 b m)) with (projT1 b m + eps - projT1 (a k) m) by ring.
    apply (proj1 (Qlt_minus_iff (projT1 (a k) m) (projT1 b m + eps))).
    exact Hup_lt.
  }
  exact (q_abs_lt_two_sided (projT1 (a k) m - projT1 b m) eps
         (QltT_to_Qlt 0 eps Heps) Hlob Hhib).
Qed.

(* real_lim 唯一性：同一序列的两极限 real_eq。
   非平凡：eps/4 分割 + real_lt_abs_bound（夹逼两项各 < eps/4）+
   l1/l2 内部柯西（两项各 < eps/4）+ Qabs_triangle 四次三角链
   （约 60 步，零 admit，纯构造性 sigT 见证）。 *)
Section RealCompletenessSkeleton.
Theorem real_lim_unique :
  forall (u : nat -> Real) (l1 l2 : Real),
    real_lim u l1 -> real_lim u l2 -> real_eq l1 l2.
Proof.
  intros u l1 l2 Hlim1 Hlim2 eps Heps.
  (* eps/4 分割：先证 Qlt 0 (eps/4) 再转 QltT（仿 real_plus 2955 模式） *)
  assert (Heps4 : QltT 0 (eps / 4)%Q).
  {
    assert (Hq : Qlt 0 (eps / 4)).
    { apply Qlt_shift_div_l; [reflexivity | simpl; apply QltT_to_Qlt; exact Heps]. }
    exact (Qlt_to_QltT 0 (eps / 4) Hq).
  }
  destruct (Hlim1 (eps / 4)%Q) as [N1 HN1].
  { exact Heps4. }
  destruct (Hlim2 (eps / 4)%Q) as [N2 HN2].
  { exact Heps4. }
  destruct l1 as [l1s Hl1c]. destruct l2 as [l2s Hl2c].
  (* 柯西阈值（先取）：|l1s a − l1s b| < eps/4（a,b ≥ C1）、|l2s a − l2s b| < eps/4（a,b ≥ C2） *)
  destruct (Hl1c (eps / 4)%Q) as [C1 HC1].
  { exact Heps4. }
  destruct (Hl2c (eps / 4)%Q) as [C2 HC2].
  { exact Heps4. }
  (* 见证 N 含 N1/N2/C1/C2 *)
  exists (max (max N1 N2) (max C1 C2)).
  intros k Hk.
  assert (HkN1 : (N1 <= k)%nat) by (apply Nat.le_trans with (max N1 N2); [apply Nat.le_max_l | apply Nat.le_trans with (max (max N1 N2) (max C1 C2)); [apply Nat.le_max_l | exact (NatLe_drop _ _ Hk)]]).
  assert (HkN2 : (N2 <= k)%nat) by (apply Nat.le_trans with (max N1 N2); [apply Nat.le_max_r | apply Nat.le_trans with (max (max N1 N2) (max C1 C2)); [apply Nat.le_max_l | exact (NatLe_drop _ _ Hk)]]).
  assert (HkC1 : (C1 <= k)%nat) by (apply Nat.le_trans with (max C1 C2); [apply Nat.le_max_l | apply Nat.le_trans with (max (max N1 N2) (max C1 C2)); [apply Nat.le_max_r | exact (NatLe_drop _ _ Hk)]]).
  assert (HkC2 : (C2 <= k)%nat) by (apply Nat.le_trans with (max C1 C2); [apply Nat.le_max_r | apply Nat.le_trans with (max (max N1 N2) (max C1 C2)); [apply Nat.le_max_r | exact (NatLe_drop _ _ Hk)]]).
  (* 夹逼差分界：u 对 l1/l2（real_lt_abs_bound，Heps4 见开头） *)
  destruct (real_lt_abs_bound u (existT _ l1s Hl1c) (eps / 4)%Q Heps4 N1 HN1 k HkN1) as [M1k HM1k].
  destruct (real_lt_abs_bound u (existT _ l2s Hl2c) (eps / 4)%Q Heps4 N2 HN2 k HkN2) as [M2k HM2k].
  (* 中间下标 m := max k (max C1 (max C2 (max M1k M2k))) *)
  set (m := max k (max C1 (max C2 (max M1k M2k)))).
  assert (Hmk : (k <= m)%nat) by (unfold m; apply Nat.le_max_l).
  assert (Hmc1 : (C1 <= m)%nat).
  { unfold m. apply Nat.le_trans with (max C1 (max C2 (max M1k M2k))).
    - apply Nat.le_max_l.
    - apply Nat.le_max_r. }
  assert (Hmc2 : (C2 <= m)%nat).
  { unfold m. apply Nat.le_trans with (max C1 (max C2 (max M1k M2k))).
    - apply Nat.le_trans with (max C2 (max M1k M2k)); [apply Nat.le_max_l | apply Nat.le_max_r].
    - apply Nat.le_max_r. }
  assert (Hmm1k : (M1k <= m)%nat).
  { unfold m. apply Nat.le_trans with (max C1 (max C2 (max M1k M2k))).
    - apply Nat.le_trans with (max C2 (max M1k M2k)).
      + apply Nat.le_trans with (max M1k M2k).
        * apply Nat.le_max_l.
        * apply Nat.le_max_r.
      + apply Nat.le_max_r.
    - apply Nat.le_max_r. }
  assert (Hmm2k : (M2k <= m)%nat).
  { unfold m. apply Nat.le_trans with (max C1 (max C2 (max M1k M2k))).
    - apply Nat.le_trans with (max C2 (max M1k M2k)).
      + apply Nat.le_trans with (max M1k M2k).
        * apply Nat.le_max_r.
        * apply Nat.le_max_r.
      + apply Nat.le_max_r.
    - apply Nat.le_max_r. }
  (* 夹逼逐点界（m 坐标）：|(u k)_m − l1s m| < eps/4、|(u k)_m − l2s m| < eps/4 *)
  assert (Hb1 : QltT (Qabs (projT1 (u k) m - l1s m)) (eps / 4)%Q)
    by (apply (HM1k m Hmm1k)).
  assert (Hb2 : QltT (Qabs (projT1 (u k) m - l2s m)) (eps / 4)%Q)
    by (apply (HM2k m Hmm2k)).
  (* 柯西逐点界：|l1s k − l1s m| < eps/4、|l2s k − l2s m| < eps/4（k,m ≥ C1/C2） *)
  assert (Hc1 : QltT (Qabs (l1s k - l1s m)) (eps / 4)%Q)
    by (apply (HC1 k m (NatLe_lift _ _ HkC1) (NatLe_lift _ _ Hmc1))).
  assert (Hc2 : QltT (Qabs (l2s k - l2s m)) (eps / 4)%Q)
    by (apply (HC2 k m (NatLe_lift _ _ HkC2) (NatLe_lift _ _ Hmc2))).
  (* 目标：QltT (Qabs (l1s k − l2s k)) eps
     三角链：|l1s k − l2s k| ≤ |l1s k − l1s m| + |l1s m − (u k)_m| + |(u k)_m − l2s m| + |l2s m − l2s k|
            < eps/4·4 = eps *)
  apply Qlt_to_QltT.
  (* 先把各项 QltT 转 Qlt，Qabs_triangle 展开链 *)
  assert (Hb1q : Qlt (Qabs (projT1 (u k) m - l1s m)) (eps / 4)%Q) by (apply QltT_to_Qlt; exact Hb1).
  assert (Hb2q : Qlt (Qabs (projT1 (u k) m - l2s m)) (eps / 4)%Q) by (apply QltT_to_Qlt; exact Hb2).
  assert (Hc1q : Qlt (Qabs (l1s k - l1s m)) (eps / 4)%Q) by (apply QltT_to_Qlt; exact Hc1).
  assert (Hc2q : Qlt (Qabs (l2s k - l2s m)) (eps / 4)%Q) by (apply QltT_to_Qlt; exact Hc2).
  (* |l1s m − (u k)_m| == |(u k)_m − l1s m|（Qabs_opp + ring；q_abs_minus_sym 定义在后，内联） *)
  assert (Hsym1 : Qabs (l1s m - projT1 (u k) m) == Qabs (projT1 (u k) m - l1s m)).
  {
    setoid_replace (l1s m - projT1 (u k) m) with (- (projT1 (u k) m - l1s m)) by ring.
    apply Qabs_opp.
  }
  assert (Hsym2 : Qabs (l2s m - projT1 (u k) m) == Qabs (projT1 (u k) m - l2s m)).
  {
    setoid_replace (l2s m - projT1 (u k) m) with (- (projT1 (u k) m - l2s m)) by ring.
    apply Qabs_opp.
  }
  (* 三角链四步：先用 Qle_lt_trans 逐步放大 *)
  assert (Htri1 : Qle (Qabs (l1s k - l2s k))
                     (Qabs (l1s k - l1s m) + Qabs (l1s m - l2s m) + Qabs (l2s m - l2s k))).
  { apply Qle_trans with (Qabs (l1s k - l1s m) + Qabs (l1s m - l2s m) + Qabs (l2s m - l2s k)).
    - (* |l1s k − l2s k| ≤ |l1s k − l1s m| + |l1s m − l2s m| + |l2s m − l2s k|（Qabs_triangle 两次） *)
      assert (Heq : (l1s k - l2s k)%Q == ((l1s k - l1s m) + (l1s m - l2s m) + (l2s m - l2s k))%Q) by field.
      setoid_rewrite Heq.
      (* Qabs (x + y + z) ≤ |x| + |y| + |z|（两次 Qabs_triangle） *)
      apply Qle_trans with (Qabs ((l1s k - l1s m) + (l1s m - l2s m)) + Qabs (l2s m - l2s k)).
      + apply Qabs_triangle.
      + apply Qplus_le_compat.
        * apply Qabs_triangle.
        * apply Qle_refl.
    - apply Qle_refl. }
  assert (Htri2 : Qle (Qabs (l1s m - l2s m))
                     (Qabs (l1s m - projT1 (u k) m) + Qabs (projT1 (u k) m - l2s m))).
  {
    assert (Heq2 : (l1s m - l2s m)%Q == ((l1s m - projT1 (u k) m) + (projT1 (u k) m - l2s m))%Q) by field.
    (* 换 LHS：Qabs_wd 给 Qeq（Qabs 间），qeq_le 转 Qle *)
    apply (Qle_trans (Qabs (l1s m - l2s m))
                     (Qabs ((l1s m - projT1 (u k) m) + (projT1 (u k) m - l2s m)))
                     (Qabs (l1s m - projT1 (u k) m) + Qabs (projT1 (u k) m - l2s m))).
    - exact (qeq_le (Qabs (l1s m - l2s m))
                    (Qabs ((l1s m - projT1 (u k) m) + (projT1 (u k) m - l2s m)))
                    (Qabs_wd (l1s m - l2s m) ((l1s m - projT1 (u k) m) + (projT1 (u k) m - l2s m)) Heq2)).
    - apply Qabs_triangle.
  }
  assert (Htri_total : Qle (Qabs (l1s k - l2s k))
                          (Qabs (l1s k - l1s m) + (Qabs (l1s m - projT1 (u k) m) + (Qabs (projT1 (u k) m - l2s m) + Qabs (l2s m - l2s k))))).
  {
    (* 由 Htri1（三项）+ Htri2 替换中间项（l1s m − l2s m ≤ |l1s m−u|+|u−l2s m|） *)
    apply Qle_trans with (Qabs (l1s k - l1s m) + Qabs (l1s m - l2s m) + Qabs (l2s m - l2s k)).
    - exact Htri1.
    - (* 右端替换：|l1s m−l2s m| ≤ |l1s m−u| + |u−l2s m| *)
      setoid_replace (Qabs (l1s k - l1s m) + Qabs (l1s m - l2s m) + Qabs (l2s m - l2s k))
        with (Qabs (l1s k - l1s m) + (Qabs (l1s m - l2s m) + Qabs (l2s m - l2s k))) by field.
      apply Qplus_le_compat.
      + apply Qle_refl.
      + (* 先把右端重结合为 (A + B) + C，再按 Qplus_le_compat 拆，
          使第一子目标恰为 Htri2（Y ≤ A + B）；否则 A + (B + C) 会拆成 Y ≤ A。 *)
        setoid_replace (Qabs (l1s m - projT1 (u k) m) + (Qabs (projT1 (u k) m - l2s m) + Qabs (l2s m - l2s k)))
          with ((Qabs (l1s m - projT1 (u k) m) + Qabs (projT1 (u k) m - l2s m)) + Qabs (l2s m - l2s k)) by field.
        apply Qplus_le_compat.
        * exact Htri2.
        * apply Qle_refl.
  }
  (* 各项 < eps/4（含符号替换 Hsym1/Hsym2）⟹ 总和 < eps（Qplus_lt_compat 链 + eps/4·4 = eps） *)
  assert (Hsum_lt : Qlt (Qabs (l1s k - l1s m) + (Qabs (l1s m - projT1 (u k) m) + (Qabs (projT1 (u k) m - l2s m) + Qabs (l2s m - l2s k))))
                       eps).
  {
    (* 四项各 < eps/4：Qplus_lt_compat 两次组合 *)
    assert (H1 : Qlt (Qabs (l1s k - l1s m)) (eps / 4)%Q) by exact Hc1q.
    assert (H2 : Qlt (Qabs (l1s m - projT1 (u k) m)) (eps / 4)%Q).
    { rewrite Hsym1. exact Hb1q. }
    assert (H3 : Qlt (Qabs (projT1 (u k) m - l2s m)) (eps / 4)%Q) by exact Hb2q.
    assert (H4 : Qlt (Qabs (l2s m - l2s k)) (eps / 4)%Q).
    { (* Hc2q 是 |l2s k − l2s m| < eps/4，符号反向：Qabs_opp 对称（同 Hsym1/Hsym2 内联） *)
      assert (Hsym4 : Qabs (l2s m - l2s k) == Qabs (l2s k - l2s m)).
      {
        setoid_replace (l2s m - l2s k) with (- (l2s k - l2s m)) by ring.
        apply Qabs_opp.
      }
      rewrite Hsym4. exact Hc2q. }
    (* (H1 + H2) + (H3 + H4) < eps/4+eps/4 + eps/4+eps/4 = eps *)
    assert (H12 : Qlt (Qabs (l1s k - l1s m) + Qabs (l1s m - projT1 (u k) m)) ((eps / 4)%Q + (eps / 4)%Q))
      by exact (Qplus_lt_compat _ _ _ _ H1 H2).
    assert (H34 : Qlt (Qabs (projT1 (u k) m - l2s m) + Qabs (l2s m - l2s k)) ((eps / 4)%Q + (eps / 4)%Q))
      by exact (Qplus_lt_compat _ _ _ _ H3 H4).
    (* 总和 < (eps/4+eps/4) + (eps/4+eps/4) = eps（ring 化简） *)
    assert (H1234 : Qlt (Qabs (l1s k - l1s m) + (Qabs (l1s m - projT1 (u k) m) + (Qabs (projT1 (u k) m - l2s m) + Qabs (l2s m - l2s k))))
                        (((eps / 4)%Q + (eps / 4)%Q) + ((eps / 4)%Q + (eps / 4)%Q))).
    {
      (* 重组括号：左结合加法 *)
      setoid_replace (Qabs (l1s k - l1s m) + (Qabs (l1s m - projT1 (u k) m) + (Qabs (projT1 (u k) m - l2s m) + Qabs (l2s m - l2s k))))
        with ((Qabs (l1s k - l1s m) + Qabs (l1s m - projT1 (u k) m)) + (Qabs (projT1 (u k) m - l2s m) + Qabs (l2s m - l2s k))) by ring.
      exact (Qplus_lt_compat _ _ _ _ H12 H34).
    }
    (* eps/4·4 == eps ⟹ 目标 < eps（含除法，用 field 而非 ring） *)
    apply (Qlt_le_trans _ (((eps / 4)%Q + (eps / 4)%Q) + ((eps / 4)%Q + (eps / 4)%Q)) _ H1234).
    setoid_replace (((eps / 4)%Q + (eps / 4)%Q) + ((eps / 4)%Q + (eps / 4)%Q)) with eps by field.
    apply Qle_refl.
  }
  (* 组装：目标 Qlt (Qabs (l1s k − l2s k)) eps 由 Htri_total + Hsum_lt（Qle_lt_trans） *)
  exact (Qle_lt_trans _ _ _ Htri_total Hsum_lt).
Qed.

(* ============================================================ *)
(* real_cauchy_complete 完整化（构造性对角线极限）             *)
(* ------------------------------------------------------------ *)
(* 分解：Bishop 正则化标准中间结论（实值双柯西 → 统一逐点双柯西）*)
(* 保持诚实 Variable（与 proj_orthogonal_compat 同先例）；其余   *)
(* 全部完整证明：对角线柯西性（参考桥接）+ real_lim 收敛双向。   *)
(* ============================================================ *)

(* Q 层：|x| < e ⟹ −e < x（e > 0；Qlt_le_dec 三分 + Qabs_neg/pos） *)
Lemma q_abs_gt_neg : forall x e : Q, Qlt 0 e -> Qlt (Qabs x) e -> Qlt (- e) x.
Proof.
  intros x e He H.
  destruct (Qlt_le_dec x 0) as [Hxlt | Hxge0].
  - (* x < 0：|x| == −x < e ⟹ −e < x（Qopp_lt_compat） *)
    assert (Habs : Qabs x == - x) by (apply Qabs_neg; apply Qlt_le_weak; exact Hxlt).
    rewrite Habs in H.
    assert (Hopp : Qlt (- e) (- (- x))).
    { apply Qopp_lt_compat. exact H. }
    rewrite (Qopp_involutive x) in Hopp. exact Hopp.
  - (* x ≥ 0：|x| == x < e，且 −e < 0 ≤ x *)
    assert (Habs : Qabs x == x) by (apply Qabs_pos; exact Hxge0).
    rewrite Habs in H.
    assert (Hneg0 : Qlt (- e) 0).
    { apply (Qlt_le_trans (- e) (- 0) 0).
      - apply Qopp_lt_compat. exact He.
      - apply Qle_refl. }
    exact (Qlt_le_trans (- e) 0 x Hneg0 Hxge0).
Qed.

(* Q 层：|d| < eps/2 ⟹ eps/2 < d + eps（收敛界：u 向 l+eps 夹逼的逐点代数） *)
Lemma q_bound_eps_half :
  forall (d eps : Q), Qlt 0 eps -> Qlt (Qabs d) (eps / 2) -> Qlt (eps / 2) (d + eps).
Proof.
  intros d eps Heps Hd.
  assert (Hhalf : Qlt 0 (eps / 2)).
  { apply Qlt_shift_div_l; [reflexivity | simpl; exact Heps]. }
  (* 目标 eps/2 < d+eps ⟸ 0 < (d+eps) + −(eps/2)（Qlt_minus_iff proj2） *)
  apply (proj2 (Qlt_minus_iff (eps / 2) (d + eps))).
  setoid_replace ((d + eps) + - (eps / 2)) with (d + eps / 2) by field.
  (* 目标 0 < d + eps/2 换形为 0 < d + −(−(eps/2))（Qlt_minus_iff proj1 正向） *)
  setoid_replace (d + eps / 2) with (d + - - (eps / 2)) by ring.
  apply (proj1 (Qlt_minus_iff (- (eps / 2)) d)).
  apply q_abs_gt_neg; [exact Hhalf | exact Hd].
Qed.

(* Q 层交换形：|d| < eps/2 ⟹ eps/2 < eps + d *)
Lemma q_bound_eps_half_comm :
  forall (d eps : Q), Qlt 0 eps -> Qlt (Qabs d) (eps / 2) -> Qlt (eps / 2) (eps + d).
Proof.
  intros d eps Heps Hd.
  assert (Hmid : Qlt (eps / 2) (d + eps)) by (apply q_bound_eps_half; [exact Heps | exact Hd]).
  setoid_replace (d + eps) with (eps + d) in Hmid by ring.
  exact Hmid.
Qed.

(* Q 层：三项各 < eps/3 ⟹ 和 < eps（Qabs_triangle 两次 + field 收尾） *)
Lemma q_three_bound : forall (eps a b c : Q), Qlt 0 eps ->
  Qlt (Qabs a) (eps / 3) -> Qlt (Qabs b) (eps / 3) -> Qlt (Qabs c) (eps / 3) ->
  Qlt (Qabs (a + b + c)) eps.
Proof.
  intros eps a b c Heps Ha Hb Hc.
  assert (Ht1 : Qle (Qabs (a + b + c)) (Qabs (a + b) + Qabs c)).
  { apply Qabs_triangle. }
  assert (Ht2 : Qle (Qabs (a + b)) (Qabs a + Qabs b)).
  { apply Qabs_triangle. }
  apply (Qle_lt_trans _ (Qabs (a + b) + Qabs c) _ Ht1).
  apply (Qle_lt_trans _ (Qabs a + Qabs b + Qabs c) _).
  - apply Qplus_le_compat; [exact Ht2 | apply Qle_refl].
  - assert (Hab : Qlt (Qabs a + Qabs b) (eps / 3 + eps / 3))
      by (apply Qplus_lt_compat; [exact Ha | exact Hb]).
    assert (H123 : Qlt (Qabs a + Qabs b + Qabs c) ((eps / 3 + eps / 3) + eps / 3)).
    { exact (Qplus_lt_compat _ _ _ _ Hab Hc). }
    apply (Qlt_le_trans _ (((eps / 3) + (eps / 3)) + (eps / 3)) _ H123).
    setoid_replace (((eps / 3) + (eps / 3)) + (eps / 3)) with eps by field.
    apply Qle_refl.
Qed.

(* Q 层三点链：|x−p|,|p−q|,|q−y| 各 < eps/3 ⟹ |x−y| < eps
   （对角线柯西的 eps/3 三角链：x:=u_m(m), p:=u_R(m), q:=u_R(n), y:=u_n(n)） *)
Lemma q_chain3 : forall (x p q y : Q) (eps : Q), Qlt 0 eps ->
  Qlt (Qabs (x - p)) (eps / 3) -> Qlt (Qabs (p - q)) (eps / 3) -> Qlt (Qabs (q - y)) (eps / 3) ->
  Qlt (Qabs (x - y)) eps.
Proof.
  intros x p q y eps Heps Hxp Hpq Hqy.
  assert (Hsum : Qlt (Qabs ((x - p) + (p - q) + (q - y))) eps).
  { apply q_three_bound with (a := x - p) (b := p - q) (c := q - y).
    - exact Heps.
    - exact Hxp.
    - exact Hpq.
    - exact Hqy. }
  setoid_replace ((x - p) + (p - q) + (q - y)) with (x - y) in Hsum by ring.
  exact Hsum.
Qed.

(* 逐点投影引理：real_plus/real_opp/real_const/real_mult 的 projT1 展开（Defined 可计算） *)
Lemma real_plus_proj : forall (x y : Real) (k : nat),
  projT1 (real_plus x y) k == projT1 x k + projT1 y k.
Proof.
  intros [u Hu] [v Hv] k. reflexivity.
Qed.

Lemma real_mult_proj : forall (x y : Real) (k : nat),
  projT1 (real_mult x y) k == projT1 x k * projT1 y k.
Proof.
  intros [u Hu] [v Hv] k. reflexivity.
Qed.

Lemma real_opp_proj : forall (x : Real) (k : nat),
  projT1 (real_opp x) k == - projT1 x k.
Proof.
  intros [u Hu] k. reflexivity.
Qed.

Lemma real_const_proj : forall (c : Q) (k : nat),
  projT1 (real_const c) k == c.
Proof.
  intros c k. reflexivity.
Qed.

End RealCompletenessSkeleton.

(* ============================================================ *)
(* 反例：实值双柯西 ⟹ 统一逐点双柯西 不可证（构造性否定）       *)
(* ============================================================ *)
(* u_m(k) := 0 if k < 2^m else 1                                *)
(* 每个 u_m 是柯西序列（实值 = 1）；序列族满足实值双柯西        *)
(* （N := 0，因全部实值相等）；但统一逐点双柯西构造性失败：     *)
(* ∀N M ∃m n k（m,n≥N, k≥M）使 |u_m(k) − u_n(k)| == 1。        *)
(* 此反例证明 real_cauchy_pointwise 作为"定理"不可证，          *)
(* 完备性证明必须走 Bishop 正则化路线（见后续正规划）。         *)
(* ------------------------------------------------------------ *)

(* 2^m ≥ 1 *)
Lemma pow2_ge_one : forall m : nat, (1 <= 2 ^ m)%nat.
Proof.
  induction m; simpl; [lia | exact (Nat.le_trans _ (2 ^ m) _ IHm (Nat.le_add_r _ _))].
Qed.

(* 2^m ≥ m *)
Lemma pow2_ge : forall m : nat, (m <= 2 ^ m)%nat.
Proof.
  induction m; simpl; [lia | ].
  assert (H1 : (1 <= 2 ^ m)%nat) by apply pow2_ge_one.
  assert (Htwo : (2 ^ m <= 2 ^ m + 2 ^ m)%nat) by lia.
  lia.
Qed.

(* 2^m > m（严格） *)
Lemma pow2_gt : forall m : nat, (m < 2 ^ m)%nat.
Proof.
  induction m; simpl; [lia | ].
  assert (H1 : (1 <= 2 ^ m)%nat) by apply pow2_ge_one.
  assert (Hle : (m + 1 <= 2 ^ m)%nat) by lia.
  assert (Hlt : (2 ^ m < 2 ^ m + 2 ^ m)%nat) by lia.
  lia.
Qed.

(* 反例序列族：u_m(k) := 0 if k < 2^m else 1 *)
Definition step_seq (m k : nat) : Q :=
  if Nat.ltb k (2 ^ m) then 0 else 1.

(* k < 2^m ⟹ u_m(k) == 0 *)
Lemma step_seq_lt : forall m k : nat, (k < 2 ^ m)%nat -> step_seq m k == 0.
Proof.
  intros m k Hk. unfold step_seq.
  apply Nat.ltb_lt in Hk. rewrite Hk. reflexivity.
Qed.

(* 2^m ≤ k ⟹ u_m(k) == 1 *)
Lemma step_seq_ge : forall m k : nat, (2 ^ m <= k)%nat -> step_seq m k == 1.
Proof.
  intros m k Hk. unfold step_seq.
  apply Nat.ltb_ge in Hk. rewrite Hk. reflexivity.
Qed.

(* 每个 u_m 是柯西（取 N := 2^m：k ≥ 2^m 后恒为 1） *)
Lemma step_seq_cauchy : forall m : nat, cauchy (step_seq m).
Proof.
  intros m eps Heps.
  exists (2 ^ m)%nat.
  intros a b Ha Hb.
  assert (Hsa : step_seq m a == 1) by (apply step_seq_ge; exact (NatLe_drop _ _ Ha)).
  assert (Hsb : step_seq m b == 1) by (apply step_seq_ge; exact (NatLe_drop _ _ Hb)).
  (* |u_m(a) − u_m(b)| == 0 < eps *)
  assert (Hd : Qabs (step_seq m a - step_seq m b) == 0).
  {
    setoid_rewrite Hsa. setoid_rewrite Hsb.
    apply (Qeq_trans _ (Qabs 0) _).
    - apply Qabs_wd. ring.
    - apply (Qeq_trans _ (-0) _).
      + apply Qabs_neg. apply Qle_refl.
      + apply Qeq_refl.
  }
  unfold QltT, Qlt_bool.
  assert (H0lt : Qlt 0 eps) by (apply QltT_to_Qlt; exact Heps).
  assert (Hcmp0 : Qcompare 0 eps = Lt) by (apply Qlt_alt; exact H0lt).
  assert (Hcmp : Qcompare (Qabs (step_seq m a - step_seq m b)) eps = Lt).
  { rewrite Hd. exact Hcmp0. }
  rewrite Hcmp. reflexivity.
Qed.

(* 序列族（Real 化）：u : nat -> Real *)
Definition step_real (m : nat) : Real :=
  existT _ (step_seq m) (step_seq_cauchy m).

(* 每个 u_m 实值 = 1（real_eq，N := 2^m） *)
Lemma step_real_eq_one : forall m : nat, real_eq (step_real m) (real_const 1).
Proof.
  intros m eps Heps.
  exists (2 ^ m)%nat.
  intros k Hk.
  assert (Hs : step_seq m k == 1) by (apply step_seq_ge; exact (NatLe_drop _ _ Hk)).
  assert (Hc : projT1 (real_const 1) k == 1) by (apply real_const_proj).
  (* |u_m(k) − 1| == 0 < eps *)
  assert (Hd : Qabs (projT1 (step_real m) k - projT1 (real_const 1) k) == 0).
  {
    change (projT1 (step_real m) k) with (step_seq m k).
    setoid_rewrite Hs. setoid_rewrite Hc.
    apply (Qeq_trans _ (Qabs 0) _).
    - apply Qabs_wd. ring.
    - apply (Qeq_trans _ (-0) _).
      + apply Qabs_neg. apply Qle_refl.
      + apply Qeq_refl.
  }
  unfold QltT, Qlt_bool.
  assert (H0lt : Qlt 0 eps) by (apply QltT_to_Qlt; exact Heps).
  assert (Hcmp0 : Qcompare 0 eps = Lt) by (apply Qlt_alt; exact H0lt).
  assert (Hcmp : Qcompare (Qabs (projT1 (step_real m) k - projT1 (real_const 1) k)) eps = Lt).
  { rewrite Hd. exact Hcmp0. }
  rewrite Hcmp. reflexivity.
Qed.

(* Q 层：0 < eps ⟹ eps/2 < eps *)
Lemma q_half_lt : forall eps : Q, Qlt 0 eps -> Qlt (eps / 2) eps.
Proof.
  intros eps Heps.
  apply Qlt_shift_div_r; [reflexivity | ].
  setoid_replace (eps * 2) with (eps + eps) by ring.
  apply Qlt_minus_iff.
  setoid_replace (eps + eps + - eps) with eps by ring.
  exact Heps.
Qed.

(* 实值双柯西成立（N := 0，全部实值相等 ⟹ 逐点差在坐标 ≥ max(2^m,2^n) 后为 0） *)
Lemma step_real_double_cauchy :
  forall eps : Q, QltT 0 eps ->
  sigT (fun N : nat => forall m n : nat,
    (N <= m)%nat -> (N <= n)%nat ->
    And (real_lt (real_plus (step_real m) (real_opp (step_real n))) (real_const eps))
        (real_lt (real_plus (step_real n) (real_opp (step_real m))) (real_const eps))).
Proof.
  intros eps Heps.
  exists 0%nat.
  intros m n Hm Hn.
  split.
  - (* 方向 1：real_lt (u_m − u_n) (const eps)，见证 eps/2，N1 := max (2^m) (2^n) *)
    exists (eps / 2)%Q. split.
    + assert (Hhalf : Qlt 0 (eps / 2)).
      { apply Qlt_shift_div_l; [reflexivity | simpl; apply QltT_to_Qlt; exact Heps]. }
      exact (Qlt_to_QltT 0 (eps / 2) Hhalf).
    + exists (max (2 ^ m) (2 ^ n))%nat. intros k Hk.
      assert (Hkm : (2 ^ m <= k)%nat)
        by (apply Nat.le_trans with (max (2 ^ m) (2 ^ n)); [apply Nat.le_max_l | exact (NatLe_drop _ _ Hk)]).
      assert (Hkn : (2 ^ n <= k)%nat)
        by (apply Nat.le_trans with (max (2 ^ m) (2 ^ n)); [apply Nat.le_max_r | exact (NatLe_drop _ _ Hk)]).
      assert (Hsm : step_seq m k == 1) by (apply step_seq_ge; exact Hkm).
      assert (Hsn : step_seq n k == 1) by (apply step_seq_ge; exact Hkn).
      (* 目标：QltT (eps/2) (projT1 (real_const eps) k − projT1 (u_m − u_n) k) *)
      apply Qlt_to_QltT.
      assert (Hepsq : Qlt 0 eps) by (apply QltT_to_Qlt; exact Heps).
      (* 投影展开（定义性 change）：const eps k == eps；u_m − u_n k == u_m k − u_n k *)
      assert (Hgoal :
        projT1 (real_const eps) k - projT1 (real_plus (step_real m) (real_opp (step_real n))) k == eps).
      {
        change (projT1 (real_const eps) k) with eps.
        change (projT1 (real_plus (step_real m) (real_opp (step_real n))) k)
          with (projT1 (step_real m) k - projT1 (step_real n) k).
        change (projT1 (step_real m) k) with (step_seq m k).
        change (projT1 (step_real n) k) with (step_seq n k).
        setoid_rewrite Hsm. setoid_rewrite Hsn. ring.
      }
      setoid_replace (projT1 (real_const eps) k - projT1 (real_plus (step_real m) (real_opp (step_real n))) k)
        with eps by exact Hgoal.
      exact (q_half_lt eps Hepsq).
  - (* 方向 2：real_lt (u_n − u_m) (const eps)，对称 *)
    exists (eps / 2)%Q. split.
    + assert (Hhalf : Qlt 0 (eps / 2)).
      { apply Qlt_shift_div_l; [reflexivity | simpl; apply QltT_to_Qlt; exact Heps]. }
      exact (Qlt_to_QltT 0 (eps / 2) Hhalf).
    + exists (max (2 ^ m) (2 ^ n))%nat. intros k Hk.
      assert (Hkm : (2 ^ m <= k)%nat)
        by (apply Nat.le_trans with (max (2 ^ m) (2 ^ n)); [apply Nat.le_max_l | exact (NatLe_drop _ _ Hk)]).
      assert (Hkn : (2 ^ n <= k)%nat)
        by (apply Nat.le_trans with (max (2 ^ m) (2 ^ n)); [apply Nat.le_max_r | exact (NatLe_drop _ _ Hk)]).
      assert (Hsm : step_seq m k == 1) by (apply step_seq_ge; exact Hkm).
      assert (Hsn : step_seq n k == 1) by (apply step_seq_ge; exact Hkn).
      apply Qlt_to_QltT.
      assert (Hepsq : Qlt 0 eps) by (apply QltT_to_Qlt; exact Heps).
      assert (Hgoal :
        projT1 (real_const eps) k - projT1 (real_plus (step_real n) (real_opp (step_real m))) k == eps).
      {
        change (projT1 (real_const eps) k) with eps.
        change (projT1 (real_plus (step_real n) (real_opp (step_real m))) k)
          with (projT1 (step_real n) k - projT1 (step_real m) k).
        change (projT1 (step_real n) k) with (step_seq n k).
        change (projT1 (step_real m) k) with (step_seq m k).
        setoid_rewrite Hsn. setoid_rewrite Hsm. ring.
      }
      setoid_replace (projT1 (real_const eps) k - projT1 (real_plus (step_real n) (real_opp (step_real m))) k)
        with eps by exact Hgoal.
      exact (q_half_lt eps Hepsq).
Qed.

(* 统一逐点双柯西的定义（real_cauchy_pointwise 的结论形态） *)
Definition unif_pointwise_cauchy (u : nat -> Real) : Set :=
  forall eps : Q, QltT 0 eps ->
    sigT (fun N : nat => sigT (fun M : nat => forall m n k : nat,
      (N <= m)%nat -> (N <= n)%nat -> (M <= k)%nat ->
      QltT (Qabs (projT1 (u m) k - projT1 (u n) k)) eps)).

(* ¬(Qlt 1 (1/2))：Qcompare 1 (1/2) = Gt ≠ Lt *)
Lemma not_qlt_one_half : Not (Qlt 1 (1/2)).
Proof.
  intro H.
  unfold Qlt, Qcompare in H.
  simpl in H.
  discriminate H.
Qed.

(* 核心反例定理：统一逐点双柯西对 step_real 构造性失败。
   给定任意 N M，取 m := max N M（≥ N），n := S m（≥ N），k := 2^m（≥ M），
   则 u_m(k) == 1（k = 2^m ≥ 2^m）而 u_n(k) == 0（k < 2^n = 2·2^m），
   |1 − 0| == 1 且 ¬(1 < 1/2)。 *)
Theorem step_not_unif_pointwise :
  Not (unif_pointwise_cauchy step_real).
Proof.
  intro H.
  (* eps := 1/2 *)
  assert (Hhalf0 : QltT 0 (1/2)).
  { unfold QltT, Qlt_bool. simpl. reflexivity. }
  destruct (H (1/2) Hhalf0) as [N [M HM]].
  (* 构造破坏性三参数：m := max N M，n := S m，k := 2^m *)
  set (m := max N M).
  set (n := Datatypes.S m).
  set (k := (2 ^ m)%nat).
  assert (HmN : (N <= m)%nat) by (unfold m; apply Nat.le_max_l).
  assert (HnN : (N <= n)%nat) by (unfold n; lia).
  assert (HkM : (M <= k)%nat).
  { unfold k.
    assert (HmM : (M <= m)%nat) by (unfold m; apply Nat.le_max_r).
    apply (Nat.le_trans _ m _ HmM).
    apply pow2_ge. }
  (* HM m n k HmN HnN HkM : QltT (Qabs (u_m(k) − u_n(k))) (1/2) *)
  assert (Hbad : QltT (Qabs (projT1 (step_real m) k - projT1 (step_real n) k)) (1/2))
    by (apply (HM m n k HmN HnN HkM)).
  (* u_m(k) == 1，u_n(k) == 0 ⟹ |1 − 0| == 1 *)
  assert (Hsm : step_seq m k == 1).
  { apply step_seq_ge. unfold k. apply Nat.le_refl. }
  assert (Hsn0 : step_seq n k == 0).
  { apply step_seq_lt. unfold n, k.
    (* k = 2^m < 2^(S m) = 2^n *)
    assert (Htwo : (2 ^ Datatypes.S m)%nat = (2 * 2 ^ m)%nat) by (simpl; reflexivity).
    rewrite Htwo.
    assert (Hp : (1 <= 2 ^ m)%nat) by apply pow2_ge_one.
    lia. }
  (* 化简 Hbad 到 ¬(Qlt 1 (1/2)) *)
  apply (not_qlt_one_half).
  apply QltT_to_Qlt in Hbad.
  setoid_replace (projT1 (step_real m) k - projT1 (step_real n) k)
    with 1%Q in Hbad by (change (projT1 (step_real m) k) with (step_seq m k);
                         change (projT1 (step_real n) k) with (step_seq n k);
                         setoid_rewrite Hsm; setoid_rewrite Hsn0; ring).
  assert (Ha : Qabs 1 == 1) by reflexivity.
  setoid_rewrite Ha in Hbad.
  exact Hbad.
Qed.

(* 朴素对角线给出错误极限：l_k := u_k(k) == 0（因 k < 2^k），
   但实值极限是 1 ≠ 0（由 real_lim_unique 分离）。 *)
Lemma step_diag_zero : forall k : nat, step_seq k k == 0.
Proof.
  intro k. apply step_seq_lt. apply pow2_gt.
Qed.

(* real_lim step_real (real_const 1)：N := 0，双向 eps/2 夹逼 *)
Lemma step_real_lim_one : real_lim step_real (real_const 1).
Proof.
  intros eps Heps.
  exists 0%nat.
  intros n Hn.
  split.
  - (* 方向 1：real_lt (u n) (1 + eps)：见证 eps/2，N1 := 2^n *)
    exists (eps / 2)%Q. split.
    + assert (Hhalf : Qlt 0 (eps / 2)).
      { apply Qlt_shift_div_l; [reflexivity | simpl; apply QltT_to_Qlt; exact Heps]. }
      exact (Qlt_to_QltT 0 (eps / 2) Hhalf).
    + exists (2 ^ n)%nat. intros k Hk.
      assert (Hsn : step_seq n k == 1) by (apply step_seq_ge; exact (NatLe_drop _ _ Hk)).
      apply Qlt_to_QltT.
      assert (Hepsq : Qlt 0 eps) by (apply QltT_to_Qlt; exact Heps).
      (* 目标：eps/2 < projT1 (1 + eps) k − u_n(k) == (1 + eps) − 1 == eps *)
      change (projT1 (real_plus (real_const 1) (real_const eps)) k)
        with (projT1 (real_const 1) k + projT1 (real_const eps) k).
      assert (Hc1 : projT1 (real_const 1) k == 1) by (apply real_const_proj).
      assert (Hce : projT1 (real_const eps) k == eps) by (apply real_const_proj).
      setoid_replace (projT1 (real_const 1) k + projT1 (real_const eps) k - projT1 (step_real n) k)
        with eps by (change (projT1 (step_real n) k) with (step_seq n k);
                     setoid_rewrite Hc1; setoid_rewrite Hce; setoid_rewrite Hsn; ring).
      exact (q_half_lt eps Hepsq).
  - (* 方向 2：real_lt (1 − eps) (u n)：见证 eps/2，N2 := 2^n *)
    exists (eps / 2)%Q. split.
    + assert (Hhalf : Qlt 0 (eps / 2)).
      { apply Qlt_shift_div_l; [reflexivity | simpl; apply QltT_to_Qlt; exact Heps]. }
      exact (Qlt_to_QltT 0 (eps / 2) Hhalf).
    + exists (2 ^ n)%nat. intros k Hk.
      assert (Hsn : step_seq n k == 1) by (apply step_seq_ge; exact (NatLe_drop _ _ Hk)).
      apply Qlt_to_QltT.
      assert (Hepsq : Qlt 0 eps) by (apply QltT_to_Qlt; exact Heps).
      (* 目标：eps/2 < u_n(k) − projT1 (1 − eps) k == 1 − (1 − eps) == eps *)
      change (projT1 (real_plus (real_const 1) (real_opp (real_const eps))) k)
        with (projT1 (real_const 1) k + projT1 (real_opp (real_const eps)) k).
      assert (Hc1 : projT1 (real_const 1) k == 1) by (apply real_const_proj).
      assert (Hoe : projT1 (real_opp (real_const eps)) k == - projT1 (real_const eps) k).
      { apply real_opp_proj. }
      assert (Hce : projT1 (real_const eps) k == eps) by (apply real_const_proj).
      setoid_replace (projT1 (step_real n) k - (projT1 (real_const 1) k + projT1 (real_opp (real_const eps)) k))
        with eps by (change (projT1 (step_real n) k) with (step_seq n k);
                     setoid_rewrite Hc1; setoid_rewrite Hoe; setoid_rewrite Hce;
                     setoid_rewrite Hsn; ring).
      exact (q_half_lt eps Hepsq).
Qed.

(* 朴素对角线不是极限：¬(real_lim step_real (real_const 0))。
   由 real_lim_unique：若同时收敛到 0，则 real_eq (const 1) (const 0)，
   取 eps := 1/2 得 |1 − 0| < 1/2，矛盾 ¬(1 < 1/2)。 *)
Theorem step_not_lim_zero : Not (real_lim step_real (real_const 0)).
Proof.
  intro Hlim0.
  assert (Hlim1 : real_lim step_real (real_const 1)) by apply step_real_lim_one.
  assert (Heq : real_eq (real_const 1) (real_const 0))
    by (apply (real_lim_unique step_real (real_const 1) (real_const 0) Hlim1 Hlim0)).
  assert (Hhalf0 : QltT 0 (1/2)).
  { unfold QltT, Qlt_bool. simpl. reflexivity. }
  destruct (Heq (1/2) Hhalf0) as [N HN].
  (* N ≤ N：|projT1 (const 1) N − projT1 (const 0) N| < 1/2，即 |1 − 0| < 1/2 *)
  assert (Hbad : QltT (Qabs (projT1 (real_const 1) N - projT1 (real_const 0) N)) (1/2))
    by (apply (HN N (NatLe_lift _ _ (Nat.le_refl N)))).
  apply (not_qlt_one_half).
  apply QltT_to_Qlt in Hbad.
  assert (Hc1 : projT1 (real_const 1) N == 1) by (apply real_const_proj).
  assert (Hc0 : projT1 (real_const 0) N == 0) by (apply real_const_proj).
  assert (Hgoal : projT1 (real_const 1) N - projT1 (real_const 0) N == 1).
  { simpl. ring. }
  setoid_replace (projT1 (real_const 1) N - projT1 (real_const 0) N)
    with 1%Q in Hbad by exact Hgoal.
  change (Qabs 1) with 1 in Hbad.
  exact Hbad.
Qed.

(* ============================================================ *)
(* Bishop 正则化：Q 层地基（q_arch_inv 阿基米德引理）           *)
(* ============================================================ *)
(* 完备性证明的对角线构造需要"与项无关的统一模"（反例块证明     *)
(* 朴素对角线给出错误极限）。Bishop 正则化：把 cauchy u 重标为   *)
(* v := u∘f，其中 f 递增且 f(k) ≥ modulus(1/(k+2))，使           *)
(* |v a − v b| < 1/(min a b + 2)。                               *)
(* 第一步（本节）：阿基米德引理 ∃N, 1/(N+2) < eps（Qarchimedean）。*)
(* ------------------------------------------------------------ *)

(* Q 层：∀eps>0 ∃N, 1/(N+2)#1 < eps。
   证明：Qarchimedean (1/eps) 给 p 使 1/eps < p#1；
   取 N := 2·|p|（则 p ≤ N+2），链 1/(N+2) < 1/p < eps。 *)
Lemma q_arch_inv : forall eps : Q, Qlt 0 eps ->
  sigT (fun N : nat => Qlt (1 / (Z.of_nat (N + 2) # 1)) eps).
Proof.
  intros eps Heps.
  destruct (Qarchimedean (1 / eps)) as [p Hp].
  set (N := (Z.to_nat (Z.pos p) * 2)%nat).
  exists N.
  apply Qlt_shift_div_r; [ | ].
  - (* 0 < (N+2)#1 *)
    unfold Qlt. simpl.
    assert (Hnz : (0 < Z.of_nat (N + 2))%Z) by (unfold N; lia).
    lia.
  - (* 1 < eps * (N+2)#1：链 1 < eps*p#1 < eps*(N+2)#1 *)
    apply (Qlt_trans _ (eps * (Z.pos p # 1)) _).
    + (* 1 < eps * p#1：由 Hp 乘 eps（正） *)
      assert (Hmul : Qlt ((1 / eps) * eps) ((Z.pos p # 1) * eps)).
      { apply (Qmult_lt_compat_r (1 / eps) (Z.pos p # 1) eps Heps). exact Hp. }
      setoid_replace ((1 / eps) * eps) with 1%Q in Hmul.
      2: { field. intro Hz. apply (Qlt_not_eq 0 eps Heps). exact (Qeq_sym _ _ Hz). }
      setoid_replace ((Z.pos p # 1) * eps) with (eps * (Z.pos p # 1)) in Hmul by ring.
      exact Hmul.
    + setoid_replace (eps * (Z.pos p # 1)) with ((Z.pos p # 1) * eps) by ring.
      setoid_replace (eps * (Z.of_nat (N + 2) # 1)) with ((Z.of_nat (N + 2) # 1) * eps) by ring.
      apply (Qmult_lt_compat_r (Z.pos p # 1) (Z.of_nat (N + 2) # 1) eps Heps).
      unfold Qlt. simpl.
      assert (Hz : (Z.pos p < Z.of_nat (N + 2))%Z).
      { unfold N. lia. }
      lia.
Qed.

(* Q 层：1/(N+2)#1 < eps ⟹ 1/(M+2)#1 < eps（M ≥ N，分母增大则值减小）。
   实质：M ≥ N ⟹ M+2 ≥ N+2 ⟹ 1/(M+2) ≤ 1/(N+2) < eps。 *)
Lemma q_arch_inv_mono : forall (eps : Q) (N M : nat),
  (N <= M)%nat -> Qlt (1 / (Z.of_nat (N + 2) # 1)) eps ->
  Qlt (1 / (Z.of_nat (M + 2) # 1)) eps.
Proof.
  intros eps N M Hle Harch.
  destruct (Nat.eq_dec M N) as [Heq | Hne].
  - (* M = N：直接 *)
    subst. exact Harch.
  - (* M > N：(N+2)#1 < (M+2)#1 ⟹ 1/(M+2) < 1/(N+2) < eps *)
    assert (Hlt : (N < M)%nat) by lia.
    apply (Qlt_trans _ (1 / (Z.of_nat (N + 2) # 1)) _).
    + (* 1/(M+2) < 1/(N+2)：Qinv_lt_contravar（倒数反序） *)
      setoid_replace (1 / (Z.of_nat (M + 2) # 1)) with (/ (Z.of_nat (M + 2) # 1))
        by (unfold Qdiv; apply Qmult_1_l).
      setoid_replace (1 / (Z.of_nat (N + 2) # 1)) with (/ (Z.of_nat (N + 2) # 1))
        by (unfold Qdiv; apply Qmult_1_l).
      assert (HposN : Qlt 0 (Z.of_nat (N + 2) # 1)) by (unfold Qlt; simpl; lia).
      assert (HposM : Qlt 0 (Z.of_nat (M + 2) # 1)) by (unfold Qlt; simpl; lia).
      apply (proj1 (Qinv_lt_contravar (Z.of_nat (N + 2) # 1) (Z.of_nat (M + 2) # 1)
                    HposN HposM)).
      unfold Qlt. simpl. lia.
    + exact Harch.
Qed.

(* Q 层：0 < eps 时 1/(N+2)#1 为正（正则化模的正性） *)
Lemma q_arch_inv_pos : forall (N : nat), Qlt 0 (1 / (Z.of_nat (N + 2) # 1)).
Proof.
  intro N.
  (* 0 < 1/x：Qlt_shift_div_l a:=0 b:=1 c:=(N+2)#1 ⟹ 0 < (N+2)#1 且 0·x < 1 *)
  apply Qlt_shift_div_l; [ | ].
  - (* 0 < (N+2)#1 *)
    unfold Qlt. simpl. lia.
  - (* 0·(N+2)#1 < 1：左边 == 0 < 1 *)
    setoid_replace (0 * (Z.of_nat (N + 2) # 1)) with 0%Q by ring.
    reflexivity.
Qed.

(* Q 层：k ≤ f(k) 的均匀模版本——Bishop 正则化的核心不等式
   |v a − v b| ≤ 1/(min a b + 2) 当 a ≤ b 时化为 1/(a+2)。 *)
(* 辅助：Nat.min a b = a 当 a ≤ b（nat 层；min 被 RealInterface.min 遮蔽，用 Nat.min） *)
Lemma nat_min_l : forall a b : nat, (a <= b)%nat -> Nat.min a b = a.
Proof. intros a b H. apply Nat.min_l. exact H. Qed.
Lemma nat_min_r : forall a b : nat, (b <= a)%nat -> Nat.min a b = b.
Proof. intros a b H. apply Nat.min_r. exact H. Qed.

(* ============================================================ *)
(* Bishop 正则化：regularize / reg_index / 统一模 / 对角线       *)
(* ============================================================ *)
(* 目标：证明完备性不需要 real_cauchy_pointwise（反例已证其不可证）。
   方法：对 cauchy u 构造正则化 v := u ∘ f，其中 f : nat -> nat 严格
   递增且 f(k) ≥ k、f(k) ≥ modulus_u(1/(k+2))（modulus_u = 柯西见证的
   阈值函数）。则 v 有"与项无关的统一模"：|v a − v b| < 1/(min a b + 2)。
   随后用正则化序列族 v_m 的对角线构造完备性极限（v_m 保持实值、
   且继承 u 的实值双柯西；对角线柯西性仅需统一模 + 实值双柯西）。 *)
(* ------------------------------------------------------------ *)

(* 正则化指标函数：f(0) := fmod 0；f(S k) := max (S (f k)) (fmod (S k))。
   性质：f 保序、f(k) ≥ k、f(k) ≥ fmod(k) 恒成立。 *)
Fixpoint reg_index (fmod : nat -> nat) (k : nat) : nat :=
  match k with
  | O => fmod O
  | Datatypes.S k' => max (Datatypes.S (reg_index fmod k')) (fmod (Datatypes.S k'))
  end.

(* reg_index 保序：a ≤ b ⟹ f a ≤ f b（f 严格递增：f(S k) ≥ S (f k) > f k） *)
Lemma reg_index_mono : forall (fmod : nat -> nat) (a b : nat),
  (a <= b)%nat -> (reg_index fmod a <= reg_index fmod b)%nat.
Proof.
  intros fmod. induction b as [| b' IHb]; intros Ha.
  - (* b = 0：a = 0 ⟹ f a = f 0 ≤ f 0 *)
    destruct a; simpl; lia.
  - (* b = S b'：分 a = S b' 或 a ≤ b' *)
    destruct (Nat.eq_dec a (Datatypes.S b')) as [Heq | Hne].
    + subst. lia.
    + assert (Ha_le : (a <= b')%nat) by lia.
      (* f a ≤ f b'（IH）≤ S (f b') ≤ max (S (f b')) (fmod (S b')) = f (S b') *)
      apply (Nat.le_trans _ (reg_index fmod b') _ (IHb Ha_le)).
      (* 目标：reg_index fmod b' ≤ reg_index fmod (S b') = max (S (f b')) (fmod (S b')) *)
      change ((reg_index fmod b' <=
              Nat.max (Datatypes.S (reg_index fmod b')) (fmod (Datatypes.S b')))%nat).
      apply Nat.le_trans with (Nat.max (Datatypes.S (reg_index fmod b')) (fmod (Datatypes.S b'))).
      * apply Nat.le_trans with (Datatypes.S (reg_index fmod b')).
        -- apply Nat.le_succ_diag_r.
        -- apply Nat.le_max_l.
      * reflexivity.
Qed.

(* reg_index 覆盖：f(k) ≥ k *)
Lemma reg_index_ge : forall (fmod : nat -> nat) (k : nat),
  (k <= reg_index fmod k)%nat.
Proof.
  intros fmod. induction k; [ lia | ].
  (* 目标：S k ≤ f (S k) = max (S (f k)) (fmod (S k))
     链：S k ≤ S (f k)（IH 的 succ 单调）≤ max ... *)
  apply (Nat.le_trans _ (Datatypes.S (reg_index fmod k)) _).
  - exact (le_n_S k (reg_index fmod k) IHk).
  - change ((Datatypes.S (reg_index fmod k) <=
            Nat.max (Datatypes.S (reg_index fmod k)) (fmod (Datatypes.S k)))%nat).
    apply Nat.le_max_l.
Qed.

(* reg_index 控制模：f(k) ≥ fmod(k) 恒成立 *)
Lemma reg_index_fmod : forall (fmod : nat -> nat) (k : nat),
  (fmod k <= reg_index fmod k)%nat.
Proof.
  intros fmod k. induction k; [ simpl; lia | ].
  (* 目标：fmod (S k) ≤ f (S k) = max (S (f k)) (fmod (S k)) *)
  change ((fmod (Datatypes.S k) <=
           Nat.max (Datatypes.S (reg_index fmod k)) (fmod (Datatypes.S k)))%nat).
  apply Nat.le_max_r.
Qed.

(* 正则化：v := u ∘ f，f 由柯西模驱动（f(k) ≥ 模(1/(k+2))） *)
(* 第 j 个模（柯西阈值）：q_arch_inv_pos 提供正性（Qlt → QltT） *)
Definition reg_mod (u : Qseq) (Hu : cauchy u) (j : nat) : nat :=
  projT1 (Hu (1 / (Z.of_nat (j + 2) # 1))
              (Qlt_to_QltT 0 (1 / (Z.of_nat (j + 2) # 1)) (q_arch_inv_pos j))).

Definition regularize (u : Qseq) (Hu : cauchy u) : Qseq :=
  fun k => u (reg_index (fun j => reg_mod u Hu j) k).

(* Q 层：|a-b| == |b-a|（有理数绝对值对称；正则化对称分支需要） *)
Lemma q_abs_minus_sym : forall a b : Q, Qabs (a - b) == Qabs (b - a).
Proof.
  intros a b.
  assert (H : b - a == - (a - b)). { ring. }
  setoid_rewrite H.
  symmetry.
  apply Qabs_opp.
Qed.

(* 正则化保持柯西（统一模）：
   |v a − v b| < 1/(min a b + 2)。
   a ≤ b：f a ≥ fmod a 且 f b ≥ f a ⟹ 由 u 柯西（阈值 fmod a）得
   |u(f a) − u(f b)| < 1/(a+2) == 1/(min a b + 2)。 *)
Lemma regularize_uniform_mod : forall (u : Qseq) (Hu : cauchy u) (a b : nat),
  Qlt (Qabs (regularize u Hu a - regularize u Hu b)) (1 / (Z.of_nat (Nat.min a b + 2) # 1)).
Proof.
  intros u Hu a b.
  destruct (Nat.le_gt_cases a b) as [Hab | Hba].
  - (* a ≤ b：min a b = a *)
    rewrite (nat_min_l a b Hab).
    unfold regularize.
    set (fmod := fun j : nat => reg_mod u Hu j).
    set (fa := reg_index fmod a).
    set (fb := reg_index fmod b).
    (* 目标：|u(fa) − u(fb)| < 1/(a+2) *)
    assert (Hfa_fmod : (fmod a <= fa)%nat) by (unfold fa; apply reg_index_fmod).
    assert (Hfa_le_fb : (fa <= fb)%nat) by (unfold fa, fb; apply reg_index_mono; exact Hab).
    (* u 的柯西性：Hu (1/(a+2)#1) (q_arch_inv_pos a) 给阈值 fmod a：
       对 m n ≥ fmod a，|u m − u n| < 1/(a+2)。取 m := fa, n := fb。 *)
    assert (Hc : QltT (Qabs (u fa - u fb)) (1 / (Z.of_nat (a + 2) # 1))).
    { apply (projT2 (Hu (1 / (Z.of_nat (a + 2) # 1))
                        (Qlt_to_QltT 0 (1 / (Z.of_nat (a + 2) # 1)) (q_arch_inv_pos a)))
                    fa fb (NatLe_lift _ _ Hfa_fmod)).
      apply NatLe_lift. apply (Nat.le_trans _ fa _ Hfa_fmod Hfa_le_fb). }
    (* 目标：Qlt (Qabs (u fa − u fb)) (1/(a+2)#1) —— 即 Hc 本身（QltT 转 Qlt） *)
    unfold fa, fb in Hc.
    exact (QltT_to_Qlt _ _ Hc).
  - (* b < a：对称，min a b = b *)
    rewrite (nat_min_r a b (Nat.lt_le_incl _ _ Hba)).
    unfold regularize.
    set (fmod := fun j : nat => reg_mod u Hu j).
    set (fa := reg_index fmod a).
    set (fb := reg_index fmod b).
    assert (Hfb_fmod : (fmod b <= fb)%nat) by (unfold fb; apply reg_index_fmod).
    assert (Hfb_le_fa : (fb <= fa)%nat) by (unfold fa, fb; apply reg_index_mono; lia).
    assert (Hc : QltT (Qabs (u fb - u fa)) (1 / (Z.of_nat (b + 2) # 1))).
    { apply (projT2 (Hu (1 / (Z.of_nat (b + 2) # 1))
                        (Qlt_to_QltT 0 (1 / (Z.of_nat (b + 2) # 1)) (q_arch_inv_pos b)))
                    fb fa (NatLe_lift _ _ Hfb_fmod)).
      apply NatLe_lift. apply (Nat.le_trans _ fb _ Hfb_fmod Hfb_le_fa). }
    (* 目标：Qlt (Qabs (u fa − u fb)) (1/(b+2)#1) == |u(fb) − u(fa)| 的对称上界 *)
    assert (Hsym : Qabs (u fa - u fb) == Qabs (u fb - u fa)).
    { apply q_abs_minus_sym. }
    setoid_rewrite Hsym.
    exact (QltT_to_Qlt _ _ Hc).
Qed.

(* 正则化的柯西见证：统一模 ⟹ 柯西（对 eps，取 N 使 1/(N+2) < eps，
   min a b ≥ N ⟹ 1/(min a b + 2) ≤ 1/(N+2) < eps） *)
Lemma regularize_cauchy : forall (u : Qseq) (Hu : cauchy u),
  cauchy (regularize u Hu).
Proof.
  intros u Hu eps Heps.
  destruct (q_arch_inv eps (QltT_to_Qlt 0 eps Heps)) as [N HN].
  exists N.
  intros a b Ha Hb.
  (* 目标：QltT (Qabs (v a − v b)) eps *)
  assert (Hmin : (N <= Nat.min a b)%nat).
  { destruct (Nat.le_gt_cases a b) as [Hab' | Hba'].
    - (* min a b = a：N ≤ a ✓ *)
      rewrite (nat_min_l a b Hab'). exact (NatLe_drop _ _ Ha).
    - (* min a b = b：N ≤ b ✓ *)
      rewrite (nat_min_r a b (Nat.lt_le_incl _ _ Hba')). exact (NatLe_drop _ _ Hb). }
  (* 统一模：|v a − v b| < 1/(min a b + 2) ≤ 1/(N+2) < eps *)
  assert (Hum : Qlt (Qabs (regularize u Hu a - regularize u Hu b))
                    (1 / (Z.of_nat (Nat.min a b + 2) # 1))) by (apply regularize_uniform_mod).
  assert (Hmono : Qlt (1 / (Z.of_nat (Nat.min a b + 2) # 1)) eps).
  { apply (q_arch_inv_mono eps N (Nat.min a b) Hmin). exact HN. }
  apply Qlt_to_QltT.
  exact (Qlt_trans _ _ _ Hum Hmono).
Qed.

(* 正则化保持实值：v ≈ u（real_eq）。
   对 eps > 0：u 柯西在 eps/2 给阈值 C（|u m − u n| < eps/2 当 m,n ≥ C）；
   取 N := C。对 k ≥ N：|v k − u k| == |u(f k) − u k|，f k ≥ k ≥ C（reg_index_ge）
   且 k ≥ C，故由 u 柯西得 < eps/2 < eps。 —— 无需 fmod 比较！ *)
Lemma regularize_same_real : forall (u : Qseq) (Hu : cauchy u),
  real_eq (existT _ (regularize u Hu) (regularize_cauchy u Hu))
          (existT _ u Hu).
Proof.
  intros u Hu eps Heps.
  (* eps/2 正性 *)
  assert (Hhalf0 : QltT 0 (eps / 2)%Q).
  {
    assert (Hq : Qlt 0 (eps / 2)).
    { apply Qlt_shift_div_l; [reflexivity | simpl; apply QltT_to_Qlt; exact Heps]. }
    exact (Qlt_to_QltT 0 (eps / 2) Hq).
  }
  destruct (Hu (eps / 2)%Q Hhalf0) as [C HC].
  exists C.
  intros k Hk.
  (* 目标：QltT (Qabs (v k − u k)) eps *)
  assert (Hfk : (C <= reg_index (fun j => reg_mod u Hu j) k)%nat).
  {
    (* f k ≥ k ≥ C *)
    apply (Nat.le_trans _ k _ (NatLe_drop _ _ Hk)).
    apply reg_index_ge.
  }
  (* HC k (f k) Hk Hfk：|u k − u(f k)| < eps/2 *)
  assert (Hc : QltT (Qabs (u k - u (reg_index (fun j => reg_mod u Hu j) k))) (eps / 2)%Q).
  { apply (HC k (reg_index (fun j => reg_mod u Hu j) k) Hk (NatLe_lift _ _ Hfk)). }
  (* |v k − u k| == |u(f k) − u k| == |u k − u(f k)|（对称） *)
  assert (Hgoal : Qlt (Qabs (regularize u Hu k - u k)) eps).
  {
    unfold regularize.
    assert (Hd : Qabs (u (reg_index (fun j => reg_mod u Hu j) k) - u k)
                  == Qabs (u k - u (reg_index (fun j => reg_mod u Hu j) k))).
    { apply q_abs_minus_sym. }
    setoid_rewrite Hd.
    exact (Qlt_trans _ (eps / 2)%Q _ (QltT_to_Qlt _ _ Hc) (q_half_lt eps (QltT_to_Qlt 0 eps Heps))).
  }
  apply Qlt_to_QltT.
  exact Hgoal.
Qed.

(* ============================================================ *)
(* 正则化序列族：u : nat -> Real 逐项正则化                    *)
(* ============================================================ *)
(* v_m := regularize (projT1 (u m)) (projT2 (u m))。
   性质：
   (1) 每个 v_m 是柯西（regularize_cauchy）；
   (2) v_m ≈ u_m（real_eq，regularize_same_real）；
   (3) v_m 有统一模：|v_m a − v_m b| < 1/(min a b + 2)（regularize_uniform_mod，
       与 m 无关！）；
   (4) 实值双柯西由 u 继承：real_lt (v_m − v_n) (const eps) 经 v ≈ u 与
       real_lt_eq_lt / real_eq_lt_lt 外延转换。 *)
Definition regularized_family (u : nat -> Real) : nat -> Real :=
  fun m => existT _ (regularize (projT1 (u m)) (projT2 (u m)))
                   (regularize_cauchy (projT1 (u m)) (projT2 (u m))).

(* 正则化族与原始族实值相等：v_m ≈ u_m *)
Lemma regularized_family_same : forall (u : nat -> Real) (m : nat),
  real_eq (regularized_family u m) (u m).
Proof.
  intros u m. unfold regularized_family.
  apply regularize_same_real.
Qed.

(* 正则化族的统一模（与 m 无关）：|v_m a − v_m b| < 1/(min a b + 2) *)
Lemma regularized_family_uniform_mod : forall (u : nat -> Real) (m a b : nat),
  Qlt (Qabs (projT1 (regularized_family u m) a - projT1 (regularized_family u m) b))
      (1 / (Z.of_nat (Nat.min a b + 2) # 1)).
Proof.
  intros u m a b. unfold regularized_family.
  apply regularize_uniform_mod.
Qed.

(* ============================================================ *)
(* 柯西实数实例化地基（用户要求：该实例化的必须实例化）       *)
(* ============================================================ *)
(* real_eq 是柯西序列的 Set 层等价（逐 eps 给出 sigT 见证）。  *)
(* 以下证明 real_eq 的自反性——这是未来实例化 RealInterface 时  *)
(* Id 替换性质的最小支撑，也是"信息性证明"（每步 sigT 见证）   *)
(* 的典范。Q 层引理（Qcompare_comp/Qabs_neg/Qplus_opp_r）提供   *)
(* 可判定的有理数算术基础。                                    *)
(* ------------------------------------------------------------ *)

(* Q 层：|a - a| == 0（有理数绝对值自零） *)
Lemma q_abs_self_zero : forall a : Q, Qabs (a - a) == 0.
Proof.
  intro a.
  assert (Hself : (a - a)%Q == 0).
  { unfold Qminus. apply Qplus_opp_r. }
  apply (Qeq_trans _ (Qabs 0) _).
  - apply Qabs_wd. exact Hself.
  - apply (Qeq_trans _ (-0) _).
    + apply Qabs_neg. apply Qle_refl.
    + apply Qeq_refl.
Qed.

(* real_eq 自反性：任意柯西实数与其自身等价（x ~ x） *)
Lemma real_eq_refl : forall x : Real, real_eq x x.
Proof.
  intro x. intro eps. intro Heps. exists O. intro n. intro Hn.
  unfold QltT, Qlt_bool.
  assert (H0lt : Qlt 0 eps) by (apply QltT_to_Qlt; exact Heps).
  assert (Hcmp0 : Qcompare 0 eps = Lt) by (apply Qlt_alt; exact H0lt).
  assert (Hz : Qabs (projT1 x n - projT1 x n) == 0) by (apply q_abs_self_zero).
  assert (Hcmp : Qcompare (Qabs (projT1 x n - projT1 x n)) eps = Lt).
  {
    assert (Hc1 : Qcompare (Qabs (projT1 x n - projT1 x n)) eps = Qcompare 0 eps).
    { exact (Qcompare_comp (Qabs (projT1 x n - projT1 x n)) 0 Hz eps eps (Qeq_refl eps)). }
    rewrite Hc1. exact Hcmp0.
  }
  rewrite Hcmp. reflexivity.
Qed.

(* ============================================================ *)
(* real_eq 等价关系补全（非平凡平行版本：对称性 + 传递性）     *)
(* ============================================================ *)
(* real_eq_refl 完成自反性；此处补对称性与传递性，使 real_eq 成为 *)
(* 柯西实数的完全等价关系（后续 RealInterface 实例化的前提）。   *)
(* 对称性非平凡：需 |a-b| == |b-a|（ring + Qabs_opp 两步）；      *)
(* 传递性非平凡：需 eps/2 分割 + Qabs_triangle + Qplus_lt_compat  *)
(* （与 real_plus 的柯西界同型，但作用于差序列）。               *)
(* ------------------------------------------------------------ *)

(* Q 层：|a-b| == |b-a|（有理数绝对值对称） *)
(* ============================================================ *)
(* real_lim_scal 的 Q 层缩放引理族（标量 c : Q，|c|+1 归一）    *)
(* ============================================================ *)

(* x ≤ x + y（y ≥ 0） *)
Lemma q_le_plus_nonneg_r_q : forall x y : Q, Qle 0 y -> Qle x (x + y).
Proof.
  intros x y Hy.
  apply (Qle_trans _ (x + 0) _).
  - setoid_replace (x + 0) with x by ring. apply Qle_refl.
  - apply Qplus_le_compat; [apply Qle_refl | exact Hy].
Qed.

(* 核心：|d| < e ⟹ c·d < (|c|+1)·e（分 c 符号；上界用 |d|<e 下界用 −e<d） *)
Lemma q_scal_lt : forall c d e : Q, Qlt (Qabs d) e -> Qlt (c * d) ((Qabs c + 1) * e).
Proof.
  intros c d e Hde.
  destruct (Qlt_le_dec c 0) as [Hc | Hc0].
  - (* c < 0：c == −|c|；用下界 −e < d ⟹ −(|c|·d) < |c|·e == c·d 的上界 *)
    assert (Hac : Qabs c == - c) by (apply Qabs_neg; apply Qlt_le_weak; exact Hc).
    (* |d| < e ⟹ −e < d（Qabs_Qlt_condition proj1 前半） *)
    assert (Hboth : Qlt (- e) d /\ Qlt d e) by (exact (proj1 (Qabs_Qlt_condition d e) Hde)).
    destruct Hboth as [Hlow Hup].
    (* 0 < |c|（c < 0 ⟹ |c| == −c > 0） *)
    assert (Hpos : Qlt 0 (Qabs c)).
    { setoid_rewrite Hac. apply (Qopp_lt_compat c 0 Hc). }
    (* −e < d ⟹ |c|·(−e) < |c|·d（Qmult_lt_compat_r 换序） ⟹ −(|c|·e) < |c|·d *)
    assert (Hmid : Qlt (- (Qabs c * e)) (Qabs c * d)).
    {
      assert (Hlt : Qlt ((- e) * (Qabs c)) (d * (Qabs c)))
        by (apply Qmult_lt_compat_r; [exact Hpos | exact Hlow]).
      setoid_replace ((- e) * (Qabs c)) with (- (Qabs c * e)) in Hlt by ring.
      setoid_replace (d * (Qabs c)) with (Qabs c * d) in Hlt by ring.
      exact Hlt.
    }
    (* −(|c|·d) < |c|·e：由 Hmid : −(|c|·e) < |c|·d 取负得
       −(|c|·d) < −(−(|c|·e))，再 Qopp_involutive 化简右侧 *)
    assert (Hopp : Qlt (- (Qabs c * d)) (Qabs c * e)).
    {
      assert (H1 : Qlt (- (Qabs c * d)) (- (- (Qabs c * e)))).
      { apply (Qopp_lt_compat (- (Qabs c * e)) (Qabs c * d)). exact Hmid. }
      setoid_replace (- (- (Qabs c * e))) with (Qabs c * e) in H1 by
        (apply Qopp_involutive).
      exact H1.
    }
    (* c·d == −(|c|·d)（c == −|c|） *)
    assert (Hcid : c * d == - (Qabs c * d)).
    { setoid_rewrite Hac. ring. }
    (* |c|·e ≤ (|c|+1)·e（e > 0 由 |d| < e 且 Qabs d ≥ 0：Qlt 0 (Qabs d) ≤ ... 反推）
       直接：0 ≤ Qabs d < e ⟹ 0 < e（Qlt_le_trans 0 (Qabs d) e） *)
    assert (He0 : Qle 0 e).
    {
      apply Qlt_le_weak.
      apply (Qle_lt_trans 0 (Qabs d) e).
      - apply Qabs_nonneg.
      - exact Hde.
    }
    assert (Hle : Qle (Qabs c * e) ((Qabs c + 1) * e)).
    { apply (Qmult_le_compat_r (Qabs c) (Qabs c + 1) e).
      - apply q_le_plus_nonneg_r_q. apply Qlt_le_weak. reflexivity.
      - exact He0. }
    assert (Hcd_lt : Qlt (c * d) (Qabs c * e)).
    { setoid_replace (c * d) with (- (Qabs c * d)) by exact Hcid. exact Hopp. }
    apply (Qlt_le_trans _ (Qabs c * e) _).
    + exact Hcd_lt.
    + exact Hle.
  - (* c ≥ 0：c·d ≤ |c|·|d| ≤ (|c|+1)·|d| < (|c|+1)·e *)
    assert (Hac : Qabs c == c) by (apply Qabs_pos; exact Hc0).
    (* c·d ≤ |c|·|d|：c ≥ 0 且 d ≤ |d|（Qle_Qabs），Qmult_le_compat_r 换序 *)
    assert (Hd : Qle 0 (Qabs c)) by apply Qabs_nonneg.
    assert (Hcd : Qle (c * d) (Qabs c * Qabs d)).
    {
      assert (H1 : Qle (d * c) (Qabs d * c))
        by (apply Qmult_le_compat_r; [apply Qle_Qabs | exact Hc0]).
      setoid_replace (d * c) with (c * d) in H1 by ring.
      (* 右侧 |d|·c == |c|·|d|（Hac 正向换 Qabs c → c 后 ring；勿反向换裸 c） *)
      assert (Hrhs : Qabs d * c == Qabs c * Qabs d).
      {
        apply (Qeq_trans _ (Qabs d * Qabs c) _).
        - rewrite Hac. reflexivity.   (* |d|·c == |d|·|c|：仅 Qabs c 被换 *)
        - ring.                        (* |d|·|c| == |c|·|d| *)
      }
      setoid_rewrite Hrhs in H1.
      exact H1.
    }
    assert (Hd' : Qle 0 (Qabs d)) by apply Qabs_nonneg.
    assert (Hmid : Qle (Qabs c * Qabs d) ((Qabs c + 1) * Qabs d)).
    { apply (Qmult_le_compat_r (Qabs c) (Qabs c + 1) (Qabs d)).
      - apply q_le_plus_nonneg_r_q. apply Qlt_le_weak. reflexivity.
      - exact Hd'. }
    assert (Hlt : Qlt ((Qabs c + 1) * Qabs d) ((Qabs c + 1) * e)).
    {
      assert (Hpos : Qlt 0 (Qabs c + 1)).
      { apply Qlt_le_trans with 1%Q.
        - reflexivity.
        - (* 1 ≤ |c|+1：先换形 1+|c| 再 q_le_plus_nonneg_r_q *)
          setoid_replace (Qabs c + 1) with (1 + Qabs c) by ring.
          apply q_le_plus_nonneg_r_q. apply Qabs_nonneg. }
      assert (Hr : Qlt (Qabs d * (Qabs c + 1)) (e * (Qabs c + 1)))
        by (apply Qmult_lt_compat_r; [exact Hpos | exact Hde]).
      setoid_replace (Qabs d * (Qabs c + 1)) with ((Qabs c + 1) * Qabs d) in Hr by ring.
      setoid_replace (e * (Qabs c + 1)) with ((Qabs c + 1) * e) in Hr by ring.
      exact Hr.
    }
    apply (Qle_lt_trans _ (Qabs c * Qabs d) _).
    + exact Hcd.
    + apply (Qle_lt_trans _ ((Qabs c + 1) * Qabs d) _); [exact Hmid | exact Hlt].
Qed.

(* |a| ≤ A、|b| < E、0 < A、0 < E ⟹ |a|·|b| < A·E（乘积界，real_lim_mult 需要） *)
Lemma q_abs_mul_bound : forall a b A E : Q,
  Qle (Qabs a) A -> Qlt (Qabs b) E -> Qlt 0 A -> Qlt 0 E ->
  Qlt (Qabs a * Qabs b) (A * E).
Proof.
  intros a b A E Ha Hb HA HE.
  apply (Qle_lt_trans _ (A * Qabs b) _).
  - apply Qmult_le_compat_r; [exact Ha | apply Qabs_nonneg].
  - (* A·|b| < A·E：Qmult_lt_compat_r 给 |b|·A < E·A，ring 换序 *)
    setoid_replace (A * Qabs b) with (Qabs b * A) by ring.
    setoid_replace (A * E) with (E * A) by ring.
    apply (Qmult_lt_compat_r _ _ A HA). exact Hb.
Qed.

(* 0 < eps 且 0 ≤ M ⟹ 0 < eps/(4·(M+1))（缩放分母正性，real_lim_mult 需要） *)
Lemma q_pos_scale : forall (eps M : Q), Qlt 0 eps -> Qle 0 M -> Qlt 0 (eps / (4 * (M + 1))).
Proof.
  intros eps M Heps HM.
  apply (Qlt_shift_div_l 0 eps (4 * (M + 1))).
  - apply Qmult_lt_0_compat.
    + reflexivity.  (* 0 < 4 *)
    + (* 0 < M+1：Qplus_lt_le_compat 0 1 0 M（0<1、0≤M）⟹ 0+0 < 1+M，化简 *)
      assert (Hsum : Qlt (0 + 0) (1 + M)) by (apply Qplus_lt_le_compat; [reflexivity | exact HM]).
      setoid_replace (1 + M) with (M + 1) in Hsum by ring.
      setoid_replace (0 + 0) with 0 in Hsum by ring.
      exact Hsum.
  - setoid_replace (0 * (4 * (M + 1))) with 0 by ring.
    exact Heps.
Qed.

(* 乘积差分解：a·b − c·d == a·(b−d) + (a−c)·d *)
Lemma q_prod_diff : forall a b c d : Q,
  a * b - c * d == a * (b - d) + (a - c) * d.
Proof. intros. ring. Qed.

(* 乘积差的三角界：|a·b − c·d| ≤ |a|·|b−d| + |a−c|·|d|（real_lim_mult 核心分解） *)
Lemma q_prod_diff_bound : forall a b c d : Q,
  Qle (Qabs (a * b - c * d)) (Qabs a * Qabs (b - d) + Qabs (a - c) * Qabs d).
Proof.
  intros a b c d.
  assert (Hdecomp : a * b - c * d == a * (b - d) + (a - c) * d) by ring.
  setoid_rewrite Hdecomp.
  apply (Qle_trans _ (Qabs (a * (b - d)) + Qabs ((a - c) * d)) _).
  - apply Qabs_triangle.
  - apply Qplus_le_compat.
    + rewrite Qabs_Qmult. apply Qle_refl.
    + rewrite Qabs_Qmult. apply Qle_refl.
Qed.

(* 缩放 eps：|d| < eps/(2(|c|+1)) ⟹ c·d < eps/2 *)
Lemma q_scal_eps_half : forall c d eps : Q, Qlt 0 eps ->
  Qlt (Qabs d) (eps / (2 * (Qabs c + 1))) -> Qlt (c * d) (eps / 2).
Proof.
  intros c d eps Heps Hd.
  assert (Hmid : Qlt (c * d) ((Qabs c + 1) * (eps / (2 * (Qabs c + 1))))).
  { apply q_scal_lt. exact Hd. }
  apply (Qlt_le_trans _ ((Qabs c + 1) * (eps / (2 * (Qabs c + 1)))) _ Hmid).
  assert (Heq : (Qabs c + 1) * (eps / (2 * (Qabs c + 1))) == eps / 2).
  {
    field.
    (* 条件：~ (Qabs c + 1 == 0)：由 0 < |c|+1 且 Qlt_not_eq 给 ~ 0 == |c|+1，Qeq_sym 换向 *)
    intro Hzero.
    assert (Hlt0 : Qlt 0 (Qabs c + 1)).
    { apply (Qlt_le_trans 0 1 (Qabs c + 1)).
      - assert (Hz : Qlt 0 1) by reflexivity. exact Hz.
      - setoid_replace (Qabs c + 1) with (1 + Qabs c) by ring.
        apply q_le_plus_nonneg_r_q. apply Qabs_nonneg. }
    exact (Qlt_not_eq 0 (Qabs c + 1) Hlt0 (Qeq_sym _ _ Hzero)).
  }
  rewrite Heq. apply Qle_refl.
Qed.

(* 对称：|d| < eps/(2(|c|+1)) ⟹ −(c·d) < eps/2（下夹逼用） *)
Lemma q_scal_eps_half_neg : forall c d eps : Q, Qlt 0 eps ->
  Qlt (Qabs d) (eps / (2 * (Qabs c + 1))) -> Qlt (- (c * d)) (eps / 2).
Proof.
  intros c d eps Heps Hd.
  setoid_replace (- (c * d)) with ((- c) * d) by ring.
  apply (q_scal_eps_half (- c) d eps Heps).
  assert (Hao : Qabs (- c) == Qabs c) by apply Qabs_opp.
  setoid_replace (2 * (Qabs (- c) + 1)) with (2 * (Qabs c + 1)).
  - exact Hd.
  - setoid_rewrite Hao. reflexivity.
Qed.

(* real_eq 对称性：x ~ y ⟹ y ~ x（差序列绝对值对称） *)
Lemma real_eq_sym : forall x y : Real, real_eq x y -> real_eq y x.
Proof.
  intros x y Hxy eps Heps.
  destruct (Hxy eps Heps) as [N HN].
  exists N.
  intro n. intro Hn.
  specialize (HN n Hn).   (* HN : QltT (Qabs (x n - y n)) eps *)
  unfold QltT, Qlt_bool in HN |- *.
  assert (Hcmp : Qcompare (Qabs (projT1 y n - projT1 x n)) eps =
                 Qcompare (Qabs (projT1 x n - projT1 y n)) eps).
  { exact (Qcompare_comp (Qabs (projT1 y n - projT1 x n))
                         (Qabs (projT1 x n - projT1 y n))
                         (q_abs_minus_sym (projT1 y n) (projT1 x n))
                         eps eps (Qeq_refl eps)). }
  rewrite Hcmp.
  exact HN.
Qed.

(* real_eq 传递性：x ~ y ⟹ y ~ z ⟹ x ~ z（eps/2 分割 + 三角不等式） *)
Lemma real_eq_trans : forall x y z : Real, real_eq x y -> real_eq y z -> real_eq x z.
Proof.
  intros x y z Hxy Hyz eps Heps.
  destruct (Hxy (eps/2)%Q) as [N1 HN1].
  { assert (Hhalf : Qlt 0 (eps / 2)).
    { apply Qlt_shift_div_l.
      - reflexivity.
      - simpl. apply QltT_to_Qlt. exact Heps. }
    apply Qlt_to_QltT. exact Hhalf. }
  destruct (Hyz (eps/2)%Q) as [N2 HN2].
  { assert (Hhalf2 : Qlt 0 (eps / 2)).
    { apply Qlt_shift_div_l.
      - reflexivity.
      - simpl. apply QltT_to_Qlt. exact Heps. }
    apply Qlt_to_QltT. exact Hhalf2. }
  exists (max N1 N2).
  intro n. intro Hn.
  apply Qlt_to_QltT.
  apply Qle_lt_trans with (Qabs (projT1 x n - projT1 y n) + Qabs (projT1 y n - projT1 z n)).
  - (* 三角不等式：|x-z| ≤ |x-y| + |y-z| *)
    assert (Hsum : projT1 x n - projT1 z n ==
                   (projT1 x n - projT1 y n) + (projT1 y n - projT1 z n)).
    { ring. }
    setoid_rewrite Hsum.
    apply Qabs_triangle.
  - (* eps/2 + eps/2 = eps *)
    assert (Heps_sum : eps/2 + eps/2 == eps). { field. }
    setoid_rewrite <- Heps_sum.
    apply Qplus_lt_compat.
    + apply QltT_to_Qlt. apply HN1.
      apply NatLe_lift. exact (Nat.le_trans _ (max N1 N2) _ (Nat.le_max_l N1 N2) (NatLe_drop _ _ Hn)).
    + apply QltT_to_Qlt. apply HN2.
      apply NatLe_lift. exact (Nat.le_trans _ (max N1 N2) _ (Nat.le_max_r N1 N2) (NatLe_drop _ _ Hn)).
Qed.

(* ============================================================ *)
(* Real 环核心（RealInterface 实例化的代数骨架）                *)
(* ============================================================ *)
(* 完整 RealInterface 实例需 exp/log/metric/lim 等分析构造（大工程）； *)
(* 此处先完成代数骨架：Real 在 real_eq 意义下构成交换环——加法/   *)
(* 乘法/零/壹/负元/分配律共 9 条（逐点成立，N = 0）。            *)
(* 注：接口的 Id 是定义性相等（单构造子），柯西实数非典范表示 ⟹  *)
(* 完整实例需先改接口等式或商掉 real_eq（结构性缺失.txt 已注记）。*)

Definition real_one : Real.
Proof.
  exists (fun _ => 1%Q).
  intros eps Heps. exists O. intros m n Hm Hn.
  unfold QltT, Qlt_bool.
  assert (H0lt : Qlt 0 eps) by (apply QltT_to_Qlt; exact Heps).
  assert (Hcmp0 : Qcompare 0 eps = Lt) by (apply Qlt_alt; exact H0lt).
  assert (Hz : Qabs (1 - 1) == 0) by (apply q_abs_self_zero).
  assert (Hcmp : Qcompare (Qabs (1 - 1)) eps = Lt).
  { assert (Hc1 : Qcompare (Qabs (1 - 1)) eps = Qcompare 0 eps)
      by (exact (Qcompare_comp (Qabs (1 - 1)) 0 Hz eps eps (Qeq_refl eps))).
    rewrite Hc1. exact Hcmp0. }
  rewrite Hcmp. reflexivity.
Defined.

(* 逐点差为零 ⟹ real_eq（N = 0 的统一证明模式，环律的公共内核） *)
Lemma real_eq_of_zero_diff : forall x y : Real,
  (forall n : nat, projT1 x n - projT1 y n == 0) -> real_eq x y.
Proof.
  intros x y Hz eps Heps. exists O. intro n. intro Hn.
  unfold QltT, Qlt_bool.
  assert (H0lt : Qlt 0 eps) by (apply QltT_to_Qlt; exact Heps).
  assert (Hcmp0 : Qcompare 0 eps = Lt) by (apply Qlt_alt; exact H0lt).
  assert (Hd : Qabs (projT1 x n - projT1 y n) == 0).
  { rewrite (Hz n). reflexivity. }
  assert (Hcmp : Qcompare (Qabs (projT1 x n - projT1 y n)) eps = Lt).
  { assert (Hc1 : Qcompare (Qabs (projT1 x n - projT1 y n)) eps = Qcompare 0 eps)
      by (exact (Qcompare_comp (Qabs (projT1 x n - projT1 y n)) 0 Hd eps eps (Qeq_refl eps))).
    rewrite Hc1. exact Hcmp0. }
  rewrite Hcmp. reflexivity.
Qed.

(* 环律（real_eq 层，逐点 Q 环恒等，N = 0）
   注：先 destruct 输入为 existT 构造子形式，simpl 才能归约 projT1
   （real_plus/real_mult 体内对输入做 match）。 *)
Lemma real_plus_comm : forall x y : Real, real_eq (real_plus x y) (real_plus y x).
Proof.
  intros x y. destruct x as [u Hu]. destruct y as [v Hv].
  apply real_eq_of_zero_diff. intro n. simpl. ring.
Qed.

Lemma real_plus_assoc : forall x y z : Real, real_eq (real_plus x (real_plus y z)) (real_plus (real_plus x y) z).
Proof.
  intros x y z. destruct x as [u Hu]. destruct y as [v Hv]. destruct z as [w Hw].
  apply real_eq_of_zero_diff. intro n. simpl. ring.
Qed.

Lemma real_plus_zero : forall x : Real, real_eq (real_plus x real_zero) x.
Proof.
  intros x. destruct x as [u Hu].
  apply real_eq_of_zero_diff. intro n. simpl. ring.
Qed.

Lemma real_plus_opp : forall x : Real, real_eq (real_plus x (real_opp x)) real_zero.
Proof.
  intros x. destruct x as [u Hu].
  apply real_eq_of_zero_diff. intro n. simpl. ring.
Qed.

Lemma real_mult_comm : forall x y : Real, real_eq (real_mult x y) (real_mult y x).
Proof.
  intros x y. destruct x as [u Hu]. destruct y as [v Hv].
  apply real_eq_of_zero_diff. intro n. simpl. ring.
Qed.

Lemma real_mult_assoc : forall x y z : Real, real_eq (real_mult x (real_mult y z)) (real_mult (real_mult x y) z).
Proof.
  intros x y z. destruct x as [u Hu]. destruct y as [v Hv]. destruct z as [w Hw].
  apply real_eq_of_zero_diff. intro n. simpl. ring.
Qed.

Lemma real_mult_one : forall x : Real, real_eq (real_mult x real_one) x.
Proof.
  intros x. destruct x as [u Hu].
  apply real_eq_of_zero_diff. intro n. simpl. ring.
Qed.

Lemma real_mult_zero : forall x : Real, real_eq (real_mult x real_zero) real_zero.
Proof.
  intros x. destruct x as [u Hu].
  apply real_eq_of_zero_diff. intro n. simpl. ring.
Qed.

Lemma real_distrib : forall x y z : Real,
  real_eq (real_mult x (real_plus y z)) (real_plus (real_mult x y) (real_mult x z)).
Proof.
  intros x y z. destruct x as [u Hu]. destruct y as [v Hv]. destruct z as [w Hw].
  apply real_eq_of_zero_diff. intro n. simpl. ring.
Qed.

(* ============================================================ *)
(* Real 序核心（RealInterface 实例化的序骨架）                  *)
(* ============================================================ *)
(* 环核心之上补齐序律：real_lt 不可反、real_le 自反/反对称/传递、 *)
(* 混合传递（real_lt_eq_lt / real_eq_lt_lt 用 eps/2 分割 +         *)
(* Qabs_Qlt_condition 下界）。exp/log/metric/lim 仍为剩余大工程   *)
(* （见结构性缺失.txt 注记）。                                   *)

(* real_lt 不可反：不存在 eps > 0 使 eps < x_n - x_n = 0 *)
Lemma real_lt_irrefl : forall x : Real, Not (real_lt x x).
Proof.
  intros x [eps [Heps [N HN]]].
  specialize (HN N (NatLe_lift _ _ (Nat.le_refl N))).
  assert (Hlt0 : Qlt eps 0).
  {
    assert (Hz : projT1 x N - projT1 x N == 0).
    { unfold Qminus. apply Qplus_opp_r. }
    apply QltT_to_Qlt in HN.
    setoid_rewrite Hz in HN.
    exact HN.
  }
  assert (H0e : Qlt 0 eps) by (apply QltT_to_Qlt; exact Heps).
  exact (match (Qlt_irrefl 0 (Qlt_trans 0 eps 0 H0e Hlt0)) with end).
Qed.

(* real_le 自反（real_eq_refl 直接） *)
Lemma real_le_refl : forall x : Real, real_le x x.
Proof. intro x. right. apply real_eq_refl. Qed.

(* 兼容引理：real_lt x y ∧ real_eq y z ⟹ real_lt x z（eps/2 分割 + 下界） *)
Lemma real_lt_eq_lt : forall x y z : Real, real_lt x y -> real_eq y z -> real_lt x z.
Proof.
  intros x y z Hlt Hyz.
  destruct Hlt as [eps1 [Heps1 [N1 HN1]]].
  destruct (Hyz (eps1/2)%Q) as [N2 HN2].
  { assert (Hhalf : Qlt 0 (eps1 / 2)).
    { apply Qlt_shift_div_l.
      - reflexivity.
      - simpl. apply QltT_to_Qlt. exact Heps1. }
    apply Qlt_to_QltT. exact Hhalf. }
  exists (eps1/2)%Q.
  split.
  - apply Qlt_to_QltT.
    apply Qlt_shift_div_l.
    + reflexivity.
    + simpl. apply QltT_to_Qlt. exact Heps1.
  - exists (max N1 N2). intro n. intro Hn.
    apply Qlt_to_QltT.
    assert (Hlt1 : Qlt eps1 (projT1 y n - projT1 x n)).
    { apply QltT_to_Qlt. apply HN1.
      apply NatLe_lift. exact (Nat.le_trans _ (max N1 N2) _ (Nat.le_max_l N1 N2) (NatLe_drop _ _ Hn)). }
    assert (Hd2 : Qlt (Qabs (projT1 y n - projT1 z n)) (eps1 / 2)).
    { apply QltT_to_Qlt. apply HN2.
      apply NatLe_lift. exact (Nat.le_trans _ (max N1 N2) _ (Nat.le_max_r N1 N2) (NatLe_drop _ _ Hn)). }
    (* z_n - x_n = (y_n - x_n) + (z_n - y_n) > eps1 - eps1/2 = eps1/2 *)
    assert (Hsum : projT1 z n - projT1 x n == (projT1 y n - projT1 x n) + (projT1 z n - projT1 y n)).
    { ring. }
    setoid_rewrite Hsum.
    assert (Hlb : Qlt (- (eps1 / 2)) (projT1 z n - projT1 y n)).
    {
      assert (Hzd : Qlt (Qabs (projT1 z n - projT1 y n)) (eps1 / 2)).
      { setoid_rewrite (q_abs_minus_sym (projT1 z n) (projT1 y n)). exact Hd2. }
      destruct (proj1 (Qabs_Qlt_condition (projT1 z n - projT1 y n) (eps1 / 2)) Hzd) as [Hlow _].
      exact Hlow.
    }
    assert (Hcomb : Qlt (eps1 + (- (eps1 / 2))) ((projT1 y n - projT1 x n) + (projT1 z n - projT1 y n)))
      by (apply Qplus_lt_compat; [exact Hlt1 | exact Hlb]).
    assert (Heps : eps1 + (- (eps1 / 2)) == eps1 / 2). { field. }
    setoid_rewrite Heps in Hcomb.
    exact Hcomb.
Qed.

(* 兼容引理：real_eq x y ∧ real_lt y z ⟹ real_lt x z（对称论证） *)
Lemma real_eq_lt_lt : forall x y z : Real, real_eq x y -> real_lt y z -> real_lt x z.
Proof.
  intros x y z Hxy Hlt.
  destruct Hlt as [eps1 [Heps1 [N1 HN1]]].
  destruct (Hxy (eps1/2)%Q) as [N2 HN2].
  { assert (Hhalf : Qlt 0 (eps1 / 2)).
    { apply Qlt_shift_div_l.
      - reflexivity.
      - simpl. apply QltT_to_Qlt. exact Heps1. }
    apply Qlt_to_QltT. exact Hhalf. }
  exists (eps1/2)%Q.
  split.
  - apply Qlt_to_QltT.
    apply Qlt_shift_div_l.
    + reflexivity.
    + simpl. apply QltT_to_Qlt. exact Heps1.
  - exists (max N1 N2). intro n. intro Hn.
    apply Qlt_to_QltT.
    assert (Hlt1 : Qlt eps1 (projT1 z n - projT1 y n)).
    { apply QltT_to_Qlt. apply HN1.
      apply NatLe_lift. exact (Nat.le_trans _ (max N1 N2) _ (Nat.le_max_l N1 N2) (NatLe_drop _ _ Hn)). }
    assert (Hd2 : Qlt (Qabs (projT1 x n - projT1 y n)) (eps1 / 2)).
    { apply QltT_to_Qlt. apply HN2.
      apply NatLe_lift. exact (Nat.le_trans _ (max N1 N2) _ (Nat.le_max_r N1 N2) (NatLe_drop _ _ Hn)). }
    (* z_n - x_n = (z_n - y_n) + (y_n - x_n) > eps1 - eps1/2 = eps1/2 *)
    assert (Hsum : projT1 z n - projT1 x n == (projT1 z n - projT1 y n) + (projT1 y n - projT1 x n)).
    { ring. }
    setoid_rewrite Hsum.
    assert (Hlb : Qlt (- (eps1 / 2)) (projT1 y n - projT1 x n)).
    {
      assert (Hzd : Qlt (Qabs (projT1 y n - projT1 x n)) (eps1 / 2)).
      { setoid_rewrite (q_abs_minus_sym (projT1 y n) (projT1 x n)). exact Hd2. }
      destruct (proj1 (Qabs_Qlt_condition (projT1 y n - projT1 x n) (eps1 / 2)) Hzd) as [Hlow _].
      exact Hlow.
    }
    assert (Hcomb : Qlt (eps1 + (- (eps1 / 2))) ((projT1 z n - projT1 y n) + (projT1 y n - projT1 x n)))
      by (apply Qplus_lt_compat; [exact Hlt1 | exact Hlb]).
    assert (Heps : eps1 + (- (eps1 / 2)) == eps1 / 2). { field. }
    setoid_rewrite Heps in Hcomb.
    exact Hcomb.
Qed.

(* real_le 传递（四种情形组合） *)
Lemma real_le_trans : forall x y z : Real, real_le x y -> real_le y z -> real_le x z.
Proof.
  intros x y z Hxy Hyz.
  destruct Hxy as [Hlt | Heq]; destruct Hyz as [Hlt' | Heq'].
  - left. exact (real_lt_trans x y z Hlt Hlt').
  - left. exact (real_lt_eq_lt x y z Hlt Heq').
  - left. exact (real_eq_lt_lt x y z Heq Hlt').
  - right. exact (real_eq_trans x y z Heq Heq').
Qed.

(* ============================================================ *)
(* Bishop 正则化续节：差外延 + 正则化族双柯西保持              *)
(* ============================================================ *)
(* real_eq 对减法（plus + opp）的外延性：a≈c ∧ b≈d ⟹ a−b ≈ c−d。
   直接构造：eps/2 分割 + |(a−c)−(b−d)| ≤ |a−c| + |b−d|（Qabs_triangle）。 *)
Lemma real_eq_minus_compat : forall (a b c d : Real),
  real_eq a c -> real_eq b d ->
  real_eq (real_plus a (real_opp b)) (real_plus c (real_opp d)).
Proof.
  intros a b c d Hac Hbd eps Heps.
  (* 一致界：|a_k| ≤ Ma、|d_k| ≤ Md（q_prod_diff_bound 需要 |a| 与 |d| 的界） *)
  destruct (real_norm_bounded a) as [Ma [HMa_pos HMa]].
  destruct (real_norm_bounded d) as [Md [HMd_pos HMd]].
  (* eps/2 正性 *)
  assert (Hhalf0 : QltT 0 (eps / 2)%Q).
  {
    assert (Hq : Qlt 0 (eps / 2)).
    { apply Qlt_shift_div_l; [reflexivity | simpl; apply QltT_to_Qlt; exact Heps]. }
    exact (Qlt_to_QltT 0 (eps / 2) Hq).
  }
  destruct (Hac (eps / 2)%Q Hhalf0) as [N1 HN1].
  destruct (Hbd (eps / 2)%Q Hhalf0) as [N2 HN2].
  exists (max N1 N2).
  intros k Hk.
  assert (HkN1 : (N1 <= k)%nat) by (apply Nat.le_trans with (max N1 N2); [apply Nat.le_max_l | exact (NatLe_drop _ _ Hk)]).
  assert (HkN2 : (N2 <= k)%nat) by (apply Nat.le_trans with (max N1 N2); [apply Nat.le_max_r | exact (NatLe_drop _ _ Hk)]).
  (* 目标：QltT (Qabs (projT1 (a−b) k − projT1 (c−d) k)) eps *)
  apply Qlt_to_QltT.
  (* 换形：(a−b) − (c−d) == (a−c) − (b−d)（ring） *)
  assert (Hd : projT1 (real_plus a (real_opp b)) k - projT1 (real_plus c (real_opp d)) k
               == (projT1 a k - projT1 c k) - (projT1 b k - projT1 d k)).
  {
    (* real_plus/real_opp 是 Defined 体：projT1 展开需 destruct（定义性归约）
       —— 用投影引理（Section 内定义，全局可用） *)
    assert (Hpa : projT1 (real_plus a (real_opp b)) k == projT1 a k + projT1 (real_opp b) k)
      by (apply real_plus_proj).
    assert (Hob : projT1 (real_opp b) k == - projT1 b k) by (apply real_opp_proj).
    assert (Hpc : projT1 (real_plus c (real_opp d)) k == projT1 c k + projT1 (real_opp d) k)
      by (apply real_plus_proj).
    assert (Hod : projT1 (real_opp d) k == - projT1 d k) by (apply real_opp_proj).
    setoid_rewrite Hpa. setoid_rewrite Hob.
    setoid_rewrite Hpc. setoid_rewrite Hod.
    ring.
  }
  setoid_rewrite Hd.
  (* 目标：Qlt (Qabs ((a−c) − (b−d))) eps；三角不等式 *)
  assert (H1 : Qlt (Qabs (projT1 a k - projT1 c k)) (eps / 2)%Q)
    by (apply QltT_to_Qlt; apply HN1; exact (NatLe_lift _ _ HkN1)).
  assert (H2 : Qlt (Qabs (projT1 b k - projT1 d k)) (eps / 2)%Q)
    by (apply QltT_to_Qlt; apply HN2; exact (NatLe_lift _ _ HkN2)).
  apply (Qle_lt_trans _ (Qabs (projT1 a k - projT1 c k) + Qabs (projT1 b k - projT1 d k)) _).
  - (* |(a−c) − (b−d)| ≤ |a−c| + |b−d|：三角不等式（减法版） *)
    setoid_replace ((projT1 a k - projT1 c k) - (projT1 b k - projT1 d k))
      with ((projT1 a k - projT1 c k) + (- (projT1 b k - projT1 d k))) by ring.
    apply (Qle_trans _ (Qabs (projT1 a k - projT1 c k) + Qabs (- (projT1 b k - projT1 d k))) _).
    + apply Qabs_triangle.
    + assert (Habs : Qabs (- (projT1 b k - projT1 d k)) == Qabs (projT1 b k - projT1 d k)).
      { apply Qabs_opp. }
      setoid_rewrite Habs. apply Qle_refl.
  - assert (Hsum : eps / 2 + eps / 2 == eps). { field. }
    setoid_rewrite <- Hsum.
    apply Qplus_lt_compat; exact H1 || exact H2.
Qed.

(* 实值双柯西经正则化族保持：
   v_m ≈ u_m ∧ v_n ≈ u_n ⟹ (v_m − v_n) ≈ (u_m − u_n)（real_eq_minus_compat），
   故 real_lt (v_m − v_n) (const eps) 由前提 real_lt (u_m − u_n) (const eps)
   经 real_lt_eq_lt 传递。 *)
Lemma regularized_family_double_cauchy :
  forall (u : nat -> Real),
    (forall eps : Q, QltT 0 eps ->
      sigT (fun N : nat => forall m n : nat,
        (N <= m)%nat -> (N <= n)%nat ->
        And (real_lt (real_plus (u m) (real_opp (u n))) (real_const eps))
            (real_lt (real_plus (u n) (real_opp (u m))) (real_const eps)))) ->
    (forall eps : Q, QltT 0 eps ->
      sigT (fun N : nat => forall m n : nat,
        (N <= m)%nat -> (N <= n)%nat ->
        And (real_lt (real_plus (regularized_family u m) (real_opp (regularized_family u n))) (real_const eps))
            (real_lt (real_plus (regularized_family u n) (real_opp (regularized_family u m))) (real_const eps)))).
Proof.
  intros u Hcau eps Heps.
  destruct (Hcau eps Heps) as [N HN].
  exists N.
  intros m n Hm Hn.
  destruct (HN m n Hm Hn) as [Hlt1 Hlt2].
  split.
  - (* 方向 1：real_lt (v_m − v_n) (const eps)
       链：v_m − v_n ≈ u_m − u_n（差外延）< const eps ⟹ real_lt（real_eq_lt_lt） *)
    apply (real_eq_lt_lt (real_plus (regularized_family u m) (real_opp (regularized_family u n)))
                          (real_plus (u m) (real_opp (u n)))
                          (real_const eps)).
    + (* real_eq (v_m − v_n) (u_m − u_n)：由 v_m ≈ u_m、v_n ≈ u_n 及差外延 *)
      apply (real_eq_minus_compat (regularized_family u m) (regularized_family u n) (u m) (u n)).
      * apply regularized_family_same.
      * apply regularized_family_same.
    + exact Hlt1.
  - (* 方向 2：对称 *)
    apply (real_eq_lt_lt (real_plus (regularized_family u n) (real_opp (regularized_family u m)))
                          (real_plus (u n) (real_opp (u m)))
                          (real_const eps)).
    + apply (real_eq_minus_compat (regularized_family u n) (regularized_family u m) (u n) (u m)).
      * apply regularized_family_same.
      * apply regularized_family_same.
    + exact Hlt2.
Qed.

(* 双向实值差界 ⟹ 逐点差界：
   real_lt (x−y) (const eps) ∧ real_lt (y−x) (const eps)
   ⟹ ∃M ∀k≥M: |x k − y k| < eps。
   证明：e1 < eps − (x k − y k) ⟹ x k − y k < eps − e1 < eps；
         e2 < eps − (y k − x k) ⟹ −eps < x k − y k（e2 > 0）；
         q_abs_lt_two_sided 组装。 *)
Lemma real_lt_pair_abs_bound :
  forall (x y : Real) (eps : Q) (Heps : QltT 0 eps),
    real_lt (real_plus x (real_opp y)) (real_const eps) ->
    real_lt (real_plus y (real_opp x)) (real_const eps) ->
    sigT (fun M : nat => forall k : nat, (M <= k)%nat ->
      QltT (Qabs (projT1 x k - projT1 y k)) eps).
Proof.
  intros x y eps Heps H1 H2.
  destruct H1 as [e1 [He1 [M1 HM1]]].
  destruct H2 as [e2 [He2 [M2 HM2]]].
  exists (max M1 M2).
  intros k Hk.
  assert (Hk1 : (M1 <= k)%nat) by (apply Nat.le_trans with (max M1 M2); [apply Nat.le_max_l | exact Hk]).
  assert (Hk2 : (M2 <= k)%nat) by (apply Nat.le_trans with (max M1 M2); [apply Nat.le_max_r | exact Hk]).
  (* 展开：projT1 (const eps) k == eps；projT1 (x − y) k == x k − y k *)
  assert (Hpt1 : projT1 (real_const eps) k - projT1 (real_plus x (real_opp y)) k
                 == eps - (projT1 x k - projT1 y k)).
  {
    assert (Hc : projT1 (real_const eps) k == eps) by (apply real_const_proj).
    assert (Hp : projT1 (real_plus x (real_opp y)) k == projT1 x k + projT1 (real_opp y) k)
      by (apply real_plus_proj).
    assert (Ho : projT1 (real_opp y) k == - projT1 y k) by (apply real_opp_proj).
    setoid_rewrite Hc. setoid_rewrite Hp. setoid_rewrite Ho.
    ring.
  }
  assert (Hpt2 : projT1 (real_const eps) k - projT1 (real_plus y (real_opp x)) k
                 == eps - (projT1 y k - projT1 x k)).
  {
    assert (Hc : projT1 (real_const eps) k == eps) by (apply real_const_proj).
    assert (Hp : projT1 (real_plus y (real_opp x)) k == projT1 y k + projT1 (real_opp x) k)
      by (apply real_plus_proj).
    assert (Ho : projT1 (real_opp x) k == - projT1 x k) by (apply real_opp_proj).
    setoid_rewrite Hc. setoid_rewrite Hp. setoid_rewrite Ho.
    ring.
  }
  (* e1 < eps − (x k − y k)：HM1 k 经 Hpt1 换形 *)
  assert (Hlt1 : Qlt e1 (eps - (projT1 x k - projT1 y k))).
  {
    pose proof (HM1 k (NatLe_lift _ _ Hk1)) as HM1k.
    apply QltT_to_Qlt in HM1k.
    setoid_rewrite Hpt1 in HM1k.
    exact HM1k.
  }
  assert (Hlt2 : Qlt e2 (eps - (projT1 y k - projT1 x k))).
  {
    pose proof (HM2 k (NatLe_lift _ _ Hk2)) as HM2k.
    apply QltT_to_Qlt in HM2k.
    setoid_rewrite Hpt2 in HM2k.
    exact HM2k.
  }
  (* 上界：x k − y k < eps（由 e1 < eps − d 且 0 < e1 传递） *)
  assert (Hup : Qlt (projT1 x k - projT1 y k) eps).
  {
    apply (proj2 (Qlt_minus_iff (projT1 x k - projT1 y k) eps)).
    (* 目标：0 < eps − d；由 0 < e1 < eps − d 传递 *)
    assert (He1pos : Qlt 0 e1) by (apply QltT_to_Qlt; exact He1).
    apply (Qlt_trans _ e1 _).
    - exact He1pos.
    - exact Hlt1.
  }
  (* 下界：−eps < x k − y k（e2 > 0 且 e2 < eps + (x k − y k)） *)
  assert (Hlo : Qlt (- eps) (projT1 x k - projT1 y k)).
  {
    (* e2 < eps − (y k − x k) == eps + (x k − y k) *)
    assert (Hd2 : Qlt e2 (eps + (projT1 x k - projT1 y k))).
    {
      setoid_replace (eps + (projT1 x k - projT1 y k))
        with (eps - (projT1 y k - projT1 x k)) by ring.
      exact Hlt2.
    }
    (* 目标：−eps < d ⟺ 0 < d + eps（Qlt_minus_iff 反向）；d := x k − y k *)
    apply Qlt_minus_iff.
    (* 由 Hd2：0 < eps + d − e2 == d + (eps − e2) *)
    assert (Hpos : Qlt 0 ((projT1 x k - projT1 y k) + (eps - e2))).
    {
      apply Qlt_minus_iff in Hd2.
      setoid_replace (eps + (projT1 x k - projT1 y k) - e2)
        with ((projT1 x k - projT1 y k) + (eps - e2)) in Hd2 by ring.
      exact Hd2.
    }
    (* 0 < d + (eps−e2) ∧ 0 < e2 ⟹ 0 < d + eps（0+0 < (d+eps−e2)+e2） *)
    assert (He2pos : Qlt 0 e2) by (apply QltT_to_Qlt; exact He2).
    assert (Hsum : Qlt (0 + 0) ((projT1 x k - projT1 y k) + (eps - e2) + e2)).
    { apply Qplus_lt_compat; [exact Hpos | exact He2pos]. }
    setoid_replace ((projT1 x k - projT1 y k) + (eps - e2) + e2)
      with ((projT1 x k - projT1 y k) + eps) in Hsum by ring.
    rewrite Qplus_0_l in Hsum.
    (* 目标 0 < d + -(-eps)（Qlt_minus_iff 展开）；将目标中的 -(-eps) 换为 eps *)
    setoid_replace (- (- eps)) with eps by (apply Qopp_involutive).
    exact Hsum.
  }
  (* |d| < eps：q_abs_lt_two_sided *)
  apply Qlt_to_QltT.
  apply (q_abs_lt_two_sided (projT1 x k - projT1 y k) eps (QltT_to_Qlt 0 eps Heps)).
  - exact Hlo.
  - exact Hup.
Qed.

(* 辅助：N ≤ a ∧ N ≤ b ⟹ N ≤ Nat.min a b（分 min 分支） *)
Lemma nat_le_min : forall (N a b : nat),
  (N <= a)%nat -> (N <= b)%nat -> (N <= Nat.min a b)%nat.
Proof.
  intros N a b Ha Hb.
  destruct (Nat.le_gt_cases a b) as [Hab | Hba].
  - rewrite (nat_min_l a b Hab). exact Ha.
  - rewrite (nat_min_r a b (Nat.lt_le_incl _ _ Hba)). exact Hb.
Qed.

(* Q 层：0 < eps ⟹ 0 < 2·eps（2eps = eps+eps > 0） *)
Lemma q_two_eps_pos : forall eps : Q, Qlt 0 eps -> Qlt 0 (2 * eps).
Proof.
  intros eps Heps.
  setoid_replace (2 * eps) with (eps + eps) by ring.
  assert (Hsum : Qlt (0 + 0) (eps + eps)) by (apply Qplus_lt_compat; [exact Heps | exact Heps]).
  setoid_replace (0 + 0) with 0%Q in Hsum by ring.
  exact Hsum.
Qed.

(* Q 层：0 < eps ⟹ eps < 3·eps（Qlt_minus_iff：0 < 3eps − eps == 2eps） *)
Lemma q_eps_lt_three : forall eps : Q, Qlt 0 eps -> Qlt eps (3 * eps).
Proof.
  intros eps Heps.
  apply Qlt_minus_iff.
  setoid_replace (3 * eps + - eps) with (2 * eps) by ring.
  apply q_two_eps_pos. exact Heps.
Qed.

(* Q 层：0 < eps ⟹ eps/9 < eps/3（eps < (eps/3)·9 == 3eps） *)
Lemma q_ninth_lt_third : forall eps : Q, Qlt 0 eps -> Qlt (eps / 9) (eps / 3).
Proof.
  intros eps Heps.
  apply Qlt_shift_div_r; [reflexivity | ].
  setoid_replace ((eps / 3) * 9) with (3 * eps) by field.
  apply q_eps_lt_three. exact Heps.
Qed.

(* Q 层：0 < eps ⟹ eps/3 < eps *)
Lemma q_third_lt : forall eps : Q, Qlt 0 eps -> Qlt (eps / 3) eps.
Proof.
  intros eps Heps.
  apply Qlt_shift_div_r; [reflexivity | ].
  setoid_replace (eps * 3) with (3 * eps) by ring.
  apply q_eps_lt_three. exact Heps.
Qed.

(* ============================================================ *)
(* Bishop 正则化：对角线极限（完备性核心）                     *)
(* ============================================================ *)
(* 正则化族 v 的对角线 l_k := v_k(k) 是柯西序列。
   证明：eps/9 统一分割（q_arch_inv 取 N0 使 1/(N0+2) < eps/9）。
   对 m,n ≥ N0，令 M := min m n（≥ N0）：
   |l_m − l_n| = |v_m(m) − v_n(n)|
     ≤ |v_m(m) − v_m(M)| + |v_m(M) − v_n(M)| + |v_n(M) − v_n(n)|  （q_chain3）
   项 1、3：统一模（与 m 无关）< 1/(M+2) ≤ 1/(N0+2) < eps/9。
   项 2：|v_m(M) − v_n(M)| ≤ |v_m(M) − v_m(L)| + |v_m(L) − v_n(L)| + |v_n(L) − v_n(M)|
     （q_three_bound；L := max M_pw N0，M_pw 为实值双柯西逐点阈值）
     —— 首/末：统一模 < 1/(min(M,L)+2) ≤ 1/(N0+2) < eps/9（M,L ≥ N0）；
     —— 中项：L ≥ M_pw ⟹ |v_m(L) − v_n(L)| < eps/9（real_lt_pair_abs_bound）。
   三项各 < eps/3 ⟹ |l_m − l_n| < eps（q_chain3 外层）。 *)
Lemma regularized_diag_cauchy :
  forall (u : nat -> Real),
    (forall eps : Q, QltT 0 eps ->
      sigT (fun N : nat => forall m n : nat,
        (N <= m)%nat -> (N <= n)%nat ->
        And (real_lt (real_plus (u m) (real_opp (u n))) (real_const eps))
            (real_lt (real_plus (u n) (real_opp (u m))) (real_const eps)))) ->
    cauchy (fun k : nat => projT1 (regularized_family u k) k).
Proof.
  intros u Hcau eps Heps.
  (* eps/9 分割：正性 + N0（统一模 1/(N0+2) < eps/9）+ N1（实值双柯西序列阈值） *)
  assert (Heps9 : QltT 0 (eps / 9)%Q).
  {
    assert (Hq : Qlt 0 (eps / 9)).
    { apply Qlt_shift_div_l; [reflexivity | simpl; apply QltT_to_Qlt; exact Heps]. }
    exact (Qlt_to_QltT 0 (eps / 9) Hq).
  }
  assert (Heps9q : Qlt 0 (eps / 9)) by (apply QltT_to_Qlt; exact Heps9).
  destruct (q_arch_inv (eps / 9)%Q Heps9q) as [N0 HN0].
  (* 正则化族实值双柯西在 eps/9 的序列阈值 N1 *)
  assert (Hdc : forall eps' : Q, QltT 0 eps' ->
      sigT (fun N : nat => forall m' n' : nat,
        (N <= m')%nat -> (N <= n')%nat ->
        And (real_lt (real_plus (regularized_family u m') (real_opp (regularized_family u n'))) (real_const eps'))
            (real_lt (real_plus (regularized_family u n') (real_opp (regularized_family u m'))) (real_const eps'))))
    by (apply regularized_family_double_cauchy; exact Hcau).
  destruct (Hdc (eps / 9)%Q Heps9) as [N1 HN1].
  (* 对角线阈值 N := max N0 N1 *)
  exists (max N0 N1).
  intros m n Hm Hn.
  (* m,n ≥ N0、m,n ≥ N1 *)
  assert (HmN0 : (N0 <= m)%nat) by (apply Nat.le_trans with (max N0 N1); [apply Nat.le_max_l | exact (NatLe_drop _ _ Hm)]).
  assert (HnN0 : (N0 <= n)%nat) by (apply Nat.le_trans with (max N0 N1); [apply Nat.le_max_l | exact (NatLe_drop _ _ Hn)]).
  assert (HmN1 : (N1 <= m)%nat) by (apply Nat.le_trans with (max N0 N1); [apply Nat.le_max_r | exact (NatLe_drop _ _ Hm)]).
  assert (HnN1 : (N1 <= n)%nat) by (apply Nat.le_trans with (max N0 N1); [apply Nat.le_max_r | exact (NatLe_drop _ _ Hn)]).
  set (M := Nat.min m n).
  (* M ≥ N0、M ≥ N1（M = min m n 且 m,n ≥ N0/N1） *)
  assert (HMN0 : (N0 <= M)%nat).
  {
    unfold M.
    destruct (Nat.le_gt_cases m n) as [Hmn | Hnm].
    - rewrite (nat_min_l m n Hmn). exact HmN0.
    - rewrite (nat_min_r m n (Nat.lt_le_incl _ _ Hnm)). exact HnN0.
  }
  assert (HMN1 : (N1 <= M)%nat).
  {
    unfold M.
    destruct (Nat.le_gt_cases m n) as [Hmn | Hnm].
    - rewrite (nat_min_l m n Hmn). exact HmN1.
    - rewrite (nat_min_r m n (Nat.lt_le_incl _ _ Hnm)). exact HnN1.
  }
  (* 外层三点链：x := v_m(m), p := v_m(M), q := v_n(M), y := v_n(n) *)
  apply Qlt_to_QltT.
  apply (q_chain3 (projT1 (regularized_family u m) m)
                  (projT1 (regularized_family u m) M)
                  (projT1 (regularized_family u n) M)
                  (projT1 (regularized_family u n) n)
                  eps (QltT_to_Qlt 0 eps Heps)).
  - (* 项 1：|v_m(m) − v_m(M)| < eps/3：统一模 < 1/(M+2) ≤ 1/(N0+2) < eps/9 < eps/3 *)
    assert (Hum : Qlt (Qabs (projT1 (regularized_family u m) m - projT1 (regularized_family u m) M))
                      (1 / (Z.of_nat (Nat.min m M + 2) # 1)))
      by (apply regularized_family_uniform_mod).
    assert (HmM : (M <= m)%nat) by (unfold M; lia).
    assert (Hmin : Nat.min m M = M) by (apply nat_min_r; exact HmM).
    assert (Harch : Qlt (1 / (Z.of_nat (M + 2) # 1)) (eps / 9)%Q)
      by (apply (q_arch_inv_mono (eps / 9)%Q N0 M HMN0); exact HN0).
    setoid_rewrite Hmin in Hum.
    apply (Qlt_trans _ (eps / 9)%Q _ (Qlt_trans _ (1 / (Z.of_nat (M + 2) # 1)) _ Hum Harch)
           (q_ninth_lt_third eps (QltT_to_Qlt 0 eps Heps))).
  - (* 项 2：|v_m(M) − v_n(M)| < eps/3 *)
    destruct (HN1 m n HmN1 HnN1) as [HltA HltB].
    (* 逐点阈值 Mpw：∀k ≥ Mpw: |v_m(k) − v_n(k)| < eps/9 *)
    assert (Hpw : sigT (fun Mpw : nat => forall k : nat, (Mpw <= k)%nat ->
        QltT (Qabs (projT1 (regularized_family u m) k - projT1 (regularized_family u n) k)) (eps / 9)%Q))
      by (apply (real_lt_pair_abs_bound (regularized_family u m) (regularized_family u n) (eps / 9)%Q Heps9 HltA HltB)).
    destruct Hpw as [Mpw HMpw].
    (* L := max Mpw N0：L ≥ Mpw（逐点界）、L ≥ N0（统一模项） *)
    set (L := max Mpw N0).
    assert (HLpw : (Mpw <= L)%nat) by (unfold L; apply Nat.le_max_l).
    assert (HLN0 : (N0 <= L)%nat) by (unfold L; apply Nat.le_max_r).
    (* 内层三点链（q_three_bound，各 < eps/9 ⟹ 和 < eps/3）：
       |v_m(M)−v_n(M)| ≤ |v_m(M)−v_m(L)| + |v_m(L)−v_n(L)| + |v_n(L)−v_n(M)| *)
    assert (Ht2 : Qlt (Qabs ((projT1 (regularized_family u m) M - projT1 (regularized_family u m) L)
                           + (projT1 (regularized_family u m) L - projT1 (regularized_family u n) L)
                           + (projT1 (regularized_family u n) L - projT1 (regularized_family u n) M)))
                      (eps / 3)%Q).
    {
      apply (q_three_bound (eps / 3)%Q
              (projT1 (regularized_family u m) M - projT1 (regularized_family u m) L)
              (projT1 (regularized_family u m) L - projT1 (regularized_family u n) L)
              (projT1 (regularized_family u n) L - projT1 (regularized_family u n) M)).
      - exact Heps9q.
      - (* 项 2a：|v_m(M) − v_m(L)| < eps/9：统一模 min(M,L) ≥ N0 *)
        assert (HmL : (N0 <= Nat.min M L)%nat) by (apply nat_le_min; exact HMN0 || exact HLN0).
        assert (Hum : Qlt (Qabs (projT1 (regularized_family u m) M - projT1 (regularized_family u m) L))
                          (1 / (Z.of_nat (Nat.min M L + 2) # 1)))
          by (apply regularized_family_uniform_mod).
        assert (Harch : Qlt (1 / (Z.of_nat (Nat.min M L + 2) # 1)) (eps / 9)%Q).
        { apply (q_arch_inv_mono (eps / 9)%Q N0 (Nat.min M L)); [exact HmL | exact HN0]. }
        (* 换形 eps/9 == (eps/3)/3 匹配 q_three_bound 的 eps/3 参数 *)
        setoid_replace (eps / 9) with ((eps / 3) / 3) in Harch by field.
        exact (Qlt_trans _ (1 / (Z.of_nat (Nat.min M L + 2) # 1)) _ Hum Harch).
      - (* 项 2b：|v_m(L) − v_n(L)| < eps/9：L ≥ Mpw ⟹ 逐点界 *)
        assert (H2b : QltT (Qabs (projT1 (regularized_family u m) L - projT1 (regularized_family u n) L)) (eps / 9)%Q)
          by (apply (HMpw L HLpw)).
        (* 目标：(eps/3)/3（q_three_bound 参数 eps/3）；换形目标侧 *)
        setoid_replace ((eps / 3) / 3) with (eps / 9) by field.
        apply QltT_to_Qlt. exact H2b.
      - (* 项 2c：|v_n(L) − v_n(M)| < eps/9：统一模 min(L,M) ≥ N0 *)
        assert (HmL : (N0 <= Nat.min L M)%nat) by (apply nat_le_min; exact HLN0 || exact HMN0).
        assert (Hum : Qlt (Qabs (projT1 (regularized_family u n) L - projT1 (regularized_family u n) M))
                          (1 / (Z.of_nat (Nat.min L M + 2) # 1)))
          by (apply regularized_family_uniform_mod).
        assert (Harch : Qlt (1 / (Z.of_nat (Nat.min L M + 2) # 1)) (eps / 9)%Q).
        { apply (q_arch_inv_mono (eps / 9)%Q N0 (Nat.min L M)); [exact HmL | exact HN0]. }
        setoid_replace (eps / 9) with ((eps / 3) / 3) in Harch by field.
        exact (Qlt_trans _ (1 / (Z.of_nat (Nat.min L M + 2) # 1)) _ Hum Harch).
    }
    (* 换形：|v_m(M) − v_n(M)| == |三项和|（ring） ⟹ exact Ht2 *)
    setoid_replace (projT1 (regularized_family u m) M - projT1 (regularized_family u n) M)
      with ((projT1 (regularized_family u m) M - projT1 (regularized_family u m) L)
          + (projT1 (regularized_family u m) L - projT1 (regularized_family u n) L)
          + (projT1 (regularized_family u n) L - projT1 (regularized_family u n) M)) by ring.
    exact Ht2.
  - (* 项 3：|v_n(M) − v_n(n)| < eps/3：统一模 < 1/(M+2) ≤ 1/(N0+2) < eps/9 < eps/3 *)
    assert (Hum : Qlt (Qabs (projT1 (regularized_family u n) M - projT1 (regularized_family u n) n))
                      (1 / (Z.of_nat (Nat.min M n + 2) # 1)))
      by (apply regularized_family_uniform_mod).
    assert (HMn : (M <= n)%nat) by (unfold M; lia).
    assert (Hmin : Nat.min M n = M) by (apply nat_min_l; exact HMn).
    assert (Harch : Qlt (1 / (Z.of_nat (M + 2) # 1)) (eps / 9)%Q)
      by (apply (q_arch_inv_mono (eps / 9)%Q N0 M HMN0); exact HN0).
    setoid_rewrite Hmin in Hum.
    apply (Qlt_trans _ (eps / 9)%Q _ (Qlt_trans _ (1 / (Z.of_nat (M + 2) # 1)) _ Hum Harch)
           (q_ninth_lt_third eps (QltT_to_Qlt 0 eps Heps))).
Qed.

(* ============================================================ *)
(* Bishop 正则化：real_lim 逐点界（完备性的 real_lim 部分）    *)
(* ============================================================ *)
(* 核心：|u_n(k) − l_k| < eps 对 k ≥ C(n)（C 依赖 n，因 v_n ≈ u_n 的
   阈值依赖 n；real_lt 内部坐标阈值可依赖 n，合法）。
   分解：|u_n(k) − l_k| ≤ |u_n(k) − v_n(k)| + |v_n(k) − v_k(k)|。
   — 项 A：v_n ≈ u_n（regularized_family_same）在 eps/2 ⟹ < eps/2，k ≥ C0(n)；
   — 项 B：|v_n(k) − v_k(k)|，L := max M_pw N0（M_pw 为 v 实值双柯西 eps/6
     的逐点阈值，real_lt_pair_abs_bound）：
     ≤ |v_n(k) − v_n(L)| + |v_n(L) − v_k(L)| + |v_k(L) − v_k(k)|
     —— 首/末：统一模 < 1/(N0+2) < eps/6（k,L ≥ N0）；
     —— 中项：L ≥ M_pw ⟹ < eps/6。
     项 B < eps/6+eps/6+eps/6 = eps/2（q_chain3）。总 < eps/2 + eps/2 = eps。
   返回 N1（v 实值双柯西 eps/6 序列阈值）使 n ≥ N1 可用中项。 *)
Lemma regularized_diag_close :
  forall (u : nat -> Real),
    (forall eps : Q, QltT 0 eps ->
      sigT (fun N : nat => forall m n : nat,
        (N <= m)%nat -> (N <= n)%nat ->
        And (real_lt (real_plus (u m) (real_opp (u n))) (real_const eps))
            (real_lt (real_plus (u n) (real_opp (u m))) (real_const eps)))) ->
    forall (eps : Q) (Heps : QltT 0 eps),
      sigT (fun N1 : nat => forall n : nat, (N1 <= n)%nat ->
        sigT (fun C : nat => forall k : nat, (C <= k)%nat ->
          QltT (Qabs (projT1 (u n) k - projT1 (regularized_family u k) k)) eps)).
Proof.
  intros u Hcau eps Heps.
  (* eps/2、eps/6 正性 *)
  assert (Heps2 : QltT 0 (eps / 2)%Q).
  {
    assert (Hq : Qlt 0 (eps / 2)).
    { apply Qlt_shift_div_l; [reflexivity | simpl; apply QltT_to_Qlt; exact Heps]. }
    exact (Qlt_to_QltT 0 (eps / 2) Hq).
  }
  assert (Heps6 : QltT 0 (eps / 6)%Q).
  {
    assert (Hq : Qlt 0 (eps / 6)).
    { apply Qlt_shift_div_l; [reflexivity | simpl; apply QltT_to_Qlt; exact Heps]. }
    exact (Qlt_to_QltT 0 (eps / 6) Hq).
  }
  (* N0：统一模控制 1/(N0+2) < eps/6 *)
  destruct (q_arch_inv (eps / 6)%Q (QltT_to_Qlt 0 (eps / 6) Heps6)) as [N0 HN0].
  (* N1：v 实值双柯西 eps/6 序列阈值（项 B 中项） *)
  assert (Hdc6 : forall eps' : Q, QltT 0 eps' ->
      sigT (fun N : nat => forall m' n' : nat,
        (N <= m')%nat -> (N <= n')%nat ->
        And (real_lt (real_plus (regularized_family u m') (real_opp (regularized_family u n'))) (real_const eps'))
            (real_lt (real_plus (regularized_family u n') (real_opp (regularized_family u m'))) (real_const eps'))))
    by (apply regularized_family_double_cauchy; exact Hcau).
  destruct (Hdc6 (eps / 6)%Q Heps6) as [N1 HN1].
  exists (max N0 N1).
  intros n Hn.
  assert (HnN0 : (N0 <= n)%nat) by (apply Nat.le_trans with (max N0 N1); [apply Nat.le_max_l | exact Hn]).
  assert (HnN1 : (N1 <= n)%nat) by (apply Nat.le_trans with (max N0 N1); [apply Nat.le_max_r | exact Hn]).
  (* 项 A 的阈值：v_n ≈ u_n 在 eps/2 给 C0（依赖 n） *)
  assert (Hsame : real_eq (regularized_family u n) (u n)) by (apply regularized_family_same).
  destruct (Hsame (eps / 2)%Q Heps2) as [C0 HC0].
  exists (max C0 (max N0 N1)).
  intros k Hk.
  assert (HkC0 : (C0 <= k)%nat) by (apply Nat.le_trans with (max C0 (max N0 N1)); [apply Nat.le_max_l | exact Hk]).
  assert (HkN0 : (N0 <= k)%nat) by (apply Nat.le_trans with (max N0 N1); [apply Nat.le_max_l | apply Nat.le_trans with (max C0 (max N0 N1)); [apply Nat.le_max_r | exact Hk]]).
  assert (HkN1 : (N1 <= k)%nat) by (apply Nat.le_trans with (max N0 N1); [apply Nat.le_max_r | apply Nat.le_trans with (max C0 (max N0 N1)); [apply Nat.le_max_r | exact Hk]]).
  (* 目标：|u_n(k) − v_k(k)| < eps *)
  apply Qlt_to_QltT.
  (* 项 A：|u_n(k) − v_n(k)| < eps/2（HC0 给 |v_n − u_n|，对称换形） *)
  assert (HA : Qlt (Qabs (projT1 (u n) k - projT1 (regularized_family u n) k)) (eps / 2)%Q).
  {
    assert (Hc : QltT (Qabs (projT1 (regularized_family u n) k - projT1 (u n) k)) (eps / 2)%Q)
      by (apply (HC0 k (NatLe_lift _ _ HkC0))).
    (* Hc 转 Qlt，再在 Qlt 层用 Qeq 换形（Qlt 兼容 Qeq 的 Proper 已有） *)
    pose proof (QltT_to_Qlt _ _ Hc) as Hcq.
    (* 目标：Qlt (Qabs (u_n − v_n)) (eps/2)；Hcq：Qlt (Qabs (v_n − u_n)) (eps/2)。
       Qabs (u_n − v_n) == Qabs (v_n − u_n)（q_abs_minus_sym）⟹ setoid_rewrite 于 Qlt *)
    setoid_rewrite (q_abs_minus_sym (projT1 (u n) k) (projT1 (regularized_family u n) k)).
    exact Hcq.
  }
  (* 项 B：|v_n(k) − v_k(k)| < eps/2（q_chain3，各 < eps/6） *)
  destruct (HN1 n k HnN1 HkN1) as [HltA HltB].
  assert (Hpw : sigT (fun Mpw : nat => forall j : nat, (Mpw <= j)%nat ->
      QltT (Qabs (projT1 (regularized_family u n) j - projT1 (regularized_family u k) j)) (eps / 6)%Q))
    by (apply (real_lt_pair_abs_bound (regularized_family u n) (regularized_family u k) (eps / 6)%Q Heps6 HltA HltB)).
  destruct Hpw as [Mpw HMpw].
  set (L := max Mpw N0).
  assert (HLpw : (Mpw <= L)%nat) by (unfold L; apply Nat.le_max_l).
  assert (HLN0 : (N0 <= L)%nat) by (unfold L; apply Nat.le_max_r).
  assert (HB : Qlt (Qabs (projT1 (regularized_family u n) k - projT1 (regularized_family u k) k)) (eps / 2)%Q).
  {
    apply (q_chain3 (projT1 (regularized_family u n) k)
                    (projT1 (regularized_family u n) L)
                    (projT1 (regularized_family u k) L)
                    (projT1 (regularized_family u k) k)
                    (eps / 2)%Q (QltT_to_Qlt 0 (eps / 2) Heps2)).
    - (* |v_n(k) − v_n(L)| < (eps/2)/3 = eps/6：统一模 < 1/(N0+2) < eps/6 *)
      assert (HmL : (N0 <= Nat.min k L)%nat) by (apply nat_le_min; exact HkN0 || exact HLN0).
      assert (Hum : Qlt (Qabs (projT1 (regularized_family u n) k - projT1 (regularized_family u n) L))
                        (1 / (Z.of_nat (Nat.min k L + 2) # 1)))
        by (apply regularized_family_uniform_mod).
      assert (Harch : Qlt (1 / (Z.of_nat (Nat.min k L + 2) # 1)) (eps / 6)%Q).
      { apply (q_arch_inv_mono (eps / 6)%Q N0 (Nat.min k L)); [exact HmL | exact HN0]. }
      setoid_replace ((eps / 2) / 3) with (eps / 6) by field.
      exact (Qlt_trans _ (1 / (Z.of_nat (Nat.min k L + 2) # 1)) _ Hum Harch).
    - (* |v_n(L) − v_k(L)| < eps/6：L ≥ Mpw ⟹ 逐点界 *)
      assert (H2b : QltT (Qabs (projT1 (regularized_family u n) L - projT1 (regularized_family u k) L)) (eps / 6)%Q)
        by (apply (HMpw L HLpw)).
      setoid_replace ((eps / 2) / 3) with (eps / 6) by field.
      apply QltT_to_Qlt. exact H2b.
    - (* |v_k(L) − v_k(k)| < eps/6：统一模 *)
      assert (HmL : (N0 <= Nat.min L k)%nat) by (apply nat_le_min; exact HLN0 || exact HkN0).
      assert (Hum : Qlt (Qabs (projT1 (regularized_family u k) L - projT1 (regularized_family u k) k))
                        (1 / (Z.of_nat (Nat.min L k + 2) # 1)))
        by (apply regularized_family_uniform_mod).
      assert (Harch : Qlt (1 / (Z.of_nat (Nat.min L k + 2) # 1)) (eps / 6)%Q).
      { apply (q_arch_inv_mono (eps / 6)%Q N0 (Nat.min L k)); [exact HmL | exact HN0]. }
      setoid_replace ((eps / 2) / 3) with (eps / 6) by field.
      exact (Qlt_trans _ (1 / (Z.of_nat (Nat.min L k + 2) # 1)) _ Hum Harch).
  }
  (* 总：|u_n(k) − v_k(k)| ≤ |u_n(k) − v_n(k)| + |v_n(k) − v_k(k)| < eps/2 + eps/2 = eps *)
  assert (Hsum : Qlt (Qabs (projT1 (u n) k - projT1 (regularized_family u n) k) +
                          Qabs (projT1 (regularized_family u n) k - projT1 (regularized_family u k) k))
                     eps).
  {
    (* eps/2 + eps/2 == eps，故需证明 < eps 由 HA+HB < eps/2+eps/2 == eps 严格成立：
       直接：HA < eps/2 且 HB < eps/2 ⟹ 和 < eps（Qlt 加法保序到 == 的目标） *)
    assert (Hhalf_sum : eps / 2 + eps / 2 == eps). { field. }
    assert (Hsum_lt : Qlt (Qabs (projT1 (u n) k - projT1 (regularized_family u n) k) +
                               Qabs (projT1 (regularized_family u n) k - projT1 (regularized_family u k) k))
                          (eps / 2 + eps / 2)).
    { apply Qplus_lt_compat; [exact HA | exact HB]. }
    apply (Qlt_le_trans _ (eps / 2 + eps / 2) _ Hsum_lt).
    setoid_rewrite Hhalf_sum. apply Qle_refl.
  }
  assert (Htri : Qle (Qabs (projT1 (u n) k - projT1 (regularized_family u k) k))
                     (Qabs (projT1 (u n) k - projT1 (regularized_family u n) k) +
                      Qabs (projT1 (regularized_family u n) k - projT1 (regularized_family u k) k))).
  {
    (* |a − c| = |(a − b) + (b − c)| ≤ |a − b| + |b − c|（Qabs_triangle） *)
    setoid_replace (Qabs (projT1 (u n) k - projT1 (regularized_family u k) k))
      with (Qabs ((projT1 (u n) k - projT1 (regularized_family u n) k) +
                  (projT1 (regularized_family u n) k - projT1 (regularized_family u k) k)))
      by (apply Qabs_wd; ring).
    apply Qabs_triangle.
  }
  exact (Qle_lt_trans _ _ _ Htri Hsum).
Qed.

(* ============================================================ *)
(* 柯西完备性（正则化版，零 Variable）：                        *)
(* real_cauchy_complete 不再依赖 real_cauchy_pointwise          *)
(* ============================================================ *)
(* l := 正则化对角线（regularized_diag_cauchy 证柯西）。
   real_lim u l：∀eps ∃N ∀n≥N 双向 eps/2 夹逼。
   — 逐点界 |u_n(k) − l_k| < eps/2 由 regularized_diag_close（eps/2）给出，
     阈值 C(n) 依赖 n（real_lt 内部坐标阈值可依赖 n，合法）；
   — 方向 1：real_lt (u n) (l + eps)：见证 eps/2，阈值 C(n)，
     (l_k + eps) − u_n(k) == eps − (u_n(k) − l_k) > eps/2（q_bound_eps_half）；
   — 方向 2：real_lt (l − eps) (u n)：对称（q_bound_eps_half_comm）。 *)
Theorem real_cauchy_complete :
  forall (u : nat -> Real),
    (forall eps : Q, QltT 0 eps ->
      sigT (fun N : nat => forall m n : nat,
        (N <= m)%nat -> (N <= n)%nat ->
        And (real_lt (real_plus (u m) (real_opp (u n))) (real_const eps))
            (real_lt (real_plus (u n) (real_opp (u m))) (real_const eps)))) ->
    sigT (fun l : Real => real_lim u l).
Proof.
  intros u Hcau.
  (* l := 正则化对角线 *)
  set (l := existT _ (fun k : nat => projT1 (regularized_family u k) k)
                   (regularized_diag_cauchy u Hcau)).
  exists l.
  (* real_lim u l：∀eps ∃N ∀n≥N 双向夹逼 *)
  intros eps Heps.
  (* eps/2 分割 *)
  assert (Heps2 : QltT 0 (eps / 2)%Q).
  {
    assert (Hq : Qlt 0 (eps / 2)).
    { apply Qlt_shift_div_l; [reflexivity | simpl; apply QltT_to_Qlt; exact Heps]. }
    exact (Qlt_to_QltT 0 (eps / 2) Hq).
  }
  (* 逐点界：regularized_diag_close u Hcau (eps/2) Heps2 给 N1，∀n≥N1 ∃C ∀k≥C:
     |u_n(k) − l_k| < eps/2 *)
  destruct (regularized_diag_close u Hcau (eps / 2)%Q Heps2) as [N1 HN1].
  exists N1.
  intros n Hn.
  destruct (HN1 n Hn) as [C HC].
  split.
  - (* 方向 1：real_lt (u n) (l + eps)：见证 eps/2，阈值 C *)
    exists (eps / 2)%Q. split.
    + exact Heps2.
    + exists C. intros k Hk.
      (* 目标：QltT (eps/2) (projT1 (real_plus l (real_const eps)) k − projT1 (u n) k) *)
      apply Qlt_to_QltT.
      (* 展开投影（定义性归约）：projT1 (l + eps) k == projT1 l k + eps == v_k(k) + eps *)
      change (projT1 (real_plus l (real_const eps)) k) with (projT1 (regularized_family u k) k + eps).
      (* 换形：v_k(k) + eps − u_n(k) == (v_k(k) − u_n(k)) + eps *)
      setoid_replace (projT1 (regularized_family u k) k + eps - projT1 (u n) k)
        with ((projT1 (regularized_family u k) k - projT1 (u n) k) + eps) by ring.
      (* 由 HC k Hk：|u_n(k) − v_k(k)| < eps/2；需 |v_k(k) − u_n(k)| < eps/2（对称） *)
      assert (Hd : Qlt (Qabs (projT1 (u n) k - projT1 (regularized_family u k) k)) (eps / 2)%Q)
        by (apply QltT_to_Qlt; apply (HC k (NatLe_drop _ _ Hk))).
      assert (Hd2 : Qlt (Qabs (projT1 (regularized_family u k) k - projT1 (u n) k)) (eps / 2)%Q).
      {
        (* 目标 Qlt (Qabs (v_k−u_n)) (eps/2)；Hd : Qlt (Qabs (u_n−v_k)) (eps/2)。
           Qabs (v_k−u_n) == Qabs (u_n−v_k)（q_abs_minus_sym v_k u_n） *)
        setoid_rewrite (q_abs_minus_sym (projT1 (regularized_family u k) k) (projT1 (u n) k)).
        exact Hd.
      }
      exact (q_bound_eps_half (projT1 (regularized_family u k) k - projT1 (u n) k) eps
             (QltT_to_Qlt 0 eps Heps) Hd2).
  - (* 方向 2：real_lt (l − eps) (u n)：见证 eps/2，阈值 C *)
    exists (eps / 2)%Q. split.
    + exact Heps2.
    + exists C. intros k Hk.
      (* 目标：QltT (eps/2) (projT1 (u n) k − projT1 (real_plus l (real_opp (real_const eps))) k) *)
      apply Qlt_to_QltT.
      (* 展开投影：projT1 (l + (−eps)) k == v_k(k) + (−eps) *)
      change (projT1 (real_plus l (real_opp (real_const eps))) k) with (projT1 (regularized_family u k) k + (- eps)).
      (* 目标：Qlt (eps/2) (u_n(k) − (v_k(k) + −eps)) == eps + (u_n(k) − v_k(k)) *)
      assert (Hd : Qlt (Qabs (projT1 (u n) k - projT1 (regularized_family u k) k)) (eps / 2)%Q)
        by (apply QltT_to_Qlt; apply (HC k (NatLe_drop _ _ Hk))).
      setoid_replace (projT1 (u n) k - (projT1 (regularized_family u k) k + (- eps)))
        with (eps + (projT1 (u n) k - projT1 (regularized_family u k) k)) by ring.
      exact (q_bound_eps_half_comm (projT1 (u n) k - projT1 (regularized_family u k) k) eps
             (QltT_to_Qlt 0 eps Heps) Hd).
Qed.

(* 混合传递（接口形态） *)
Lemma real_lt_le_trans : forall x y z : Real, real_lt x y -> real_le y z -> real_lt x z.
Proof.
  intros x y z Hlt Hle. destruct Hle as [Hlt' | Heq'].
  - exact (real_lt_trans x y z Hlt Hlt').
  - exact (real_lt_eq_lt x y z Hlt Heq').
Qed.

Lemma real_le_lt_trans : forall x y z : Real, real_le x y -> real_lt y z -> real_lt x z.
Proof.
  intros x y z Hle Hlt. destruct Hle as [Hlt' | Heq].
  - exact (real_lt_trans x y z Hlt' Hlt).
  - exact (real_eq_lt_lt x y z Heq Hlt).
Qed.

(* real_le 反对称：互 ≤ ⟹ real_eq（lt+lt 矛盾，其余 real_eq_sym/直接） *)
Lemma real_le_antisym : forall x y : Real, real_le x y -> real_le y x -> real_eq x y.
Proof.
  intros x y Hxy Hyx.
  destruct Hxy as [Hlt | Heq]; destruct Hyx as [Hlt' | Heq'].
  - exact (match (real_lt_irrefl x (real_lt_trans x y x Hlt Hlt')) with end).
  - exact (real_eq_sym y x Heq').
  - exact Heq.
  - exact Heq.
Qed.

(* lt_le_iff（接口形态：Or (real_lt x y) (Id x y) -> real_le x y） *)
Lemma real_lt_le_iff : forall x y : Real, Or (real_lt x y) (Id x y) -> real_le x y.
Proof.
  intros x y H.
  destruct H as [Hlt | Hid].
  - left. exact Hlt.
  - destruct Hid. right. apply real_eq_refl.
Qed.
(* ============================================================ *)
(* real_lim 收敛代数（柯西完备骨架的应用强化）                  *)
(* ------------------------------------------------------------ *)
(* real_lim 加法保持：u→l1、v→l2 ⟹ u+v → l1+l2。               *)
(* 核心：real_lt 加性平移（real_lt a b → real_lt c d ⟹           *)
(* real_lt (a+c) (b+d)，见证 e1+e2 + 逐点 ring）——交接文档       *)
(* 候选的"real_lt 加性平移引理"落地。                            *)
(* ============================================================ *)

(* real_lt 加性平移：a<b ∧ c<d ⟹ a+c < b+d（见证 e1+e2，逐点 Qplus_lt_compat） *)
Lemma real_lt_plus_compat : forall (a b c d : Real),
  real_lt a b -> real_lt c d -> real_lt (real_plus a c) (real_plus b d).
Proof.
  intros a b c d Hab Hcd.
  destruct Hab as [e1 [He1 [N1 HN1]]].
  destruct Hcd as [e2 [He2 [N2 HN2]]].
  exists (e1 + e2)%Q.
  split.
  - (* 正性：0 < e1 + e2（Qplus_lt_compat + Qplus_0_l） *)
    assert (Hlt1 : Qlt 0 e1) by (apply QltT_to_Qlt; exact He1).
    assert (Hlt2 : Qlt 0 e2) by (apply QltT_to_Qlt; exact He2).
    assert (Hsum : Qlt (0 + 0) (e1 + e2)) by (apply Qplus_lt_compat; [exact Hlt1 | exact Hlt2]).
    assert (H0 : 0 + 0 == 0) by (apply Qplus_0_l).
    rewrite H0 in Hsum.
    apply Qlt_to_QltT. exact Hsum.
  - exists (max N1 N2). intros n Hn.
    assert (Hn1 : (N1 <= n)%nat) by (apply Nat.le_trans with (max N1 N2); [apply Nat.le_max_l | exact (NatLe_drop _ _ Hn)]).
    assert (Hn2 : (N2 <= n)%nat) by (apply Nat.le_trans with (max N1 N2); [apply Nat.le_max_r | exact (NatLe_drop _ _ Hn)]).
    (* 逐点展开投影：projT1 (b+d) n == projT1 b n + projT1 d n；projT1 (a+c) n == a_n + c_n *)
    assert (Hpt_bd : projT1 (real_plus b d) n == projT1 b n + projT1 d n)
      by (apply real_plus_proj).
    assert (Hpt_ac : projT1 (real_plus a c) n == projT1 a n + projT1 c n)
      by (apply real_plus_proj).
    apply Qlt_to_QltT.
    (* 目标：e1+e2 < (b_n + d_n) − (a_n + c_n) == (b_n − a_n) + (d_n − c_n) *)
    setoid_rewrite Hpt_bd.
    setoid_rewrite Hpt_ac.
    assert (Hr : (projT1 b n + projT1 d n) - (projT1 a n + projT1 c n)
                 == (projT1 b n - projT1 a n) + (projT1 d n - projT1 c n)) by ring.
    setoid_rewrite Hr.
    apply Qplus_lt_compat.
    + apply QltT_to_Qlt. apply HN1. apply NatLe_lift. exact Hn1.
    + apply QltT_to_Qlt. apply HN2. apply NatLe_lift. exact Hn2.
Qed.

(* real_eq 辅助：((l1+e/2)+(l2+e/2)) == (l1+l2)+e（逐点 ring；eps/2 双份合 eps） *)
Lemma real_eq_plus_eps_halves :
  forall (a b : Real) (eps : Q),
    real_eq (real_plus (real_plus a (real_const (eps / 2)%Q))
                       (real_plus b (real_const (eps / 2)%Q)))
            (real_plus (real_plus a b) (real_const eps)).
Proof.
  intros a b eps eps' Heps'.
  exists O. intros n Hn.
  apply Qlt_to_QltT.
  (* 逐点展开：|((a_n+e/2)+(b_n+e/2)) − ((a_n+b_n)+e)| == 0 < eps' *)
  assert (Hpt : projT1 (real_plus (real_plus a (real_const (eps / 2)%Q))
                                  (real_plus b (real_const (eps / 2)%Q))) n
                == (projT1 a n + eps / 2) + (projT1 b n + eps / 2)).
  {
    setoid_rewrite (real_plus_proj (real_plus a (real_const (eps / 2)%Q))
                                   (real_plus b (real_const (eps / 2)%Q)) n).
    setoid_rewrite (real_plus_proj a (real_const (eps / 2)%Q) n).
    setoid_rewrite (real_plus_proj b (real_const (eps / 2)%Q) n).
    setoid_rewrite (real_const_proj (eps / 2)%Q n).
    reflexivity.
  }
  assert (Hpt2 : projT1 (real_plus (real_plus a b) (real_const eps)) n
                 == (projT1 a n + projT1 b n) + eps).
  {
    setoid_rewrite (real_plus_proj (real_plus a b) (real_const eps) n).
    setoid_rewrite (real_plus_proj a b n).
    setoid_rewrite (real_const_proj eps n).
    reflexivity.
  }
  assert (Hzero : Qabs ((projT1 a n + eps / 2) + (projT1 b n + eps / 2)
                        - ((projT1 a n + projT1 b n) + eps)) == 0).
  {
    apply (Qeq_trans _ (Qabs 0) _).
    - apply Qabs_wd. field.
    - apply (Qeq_trans _ (-0) _).
      + apply Qabs_neg. apply Qle_refl.
      + apply Qeq_refl.
  }
  (* 目标 QltT (Qabs (X − Y)) eps'，X−Y == 0：Qcompare_comp 模式 *)
  assert (H0lt : Qlt 0 eps') by (apply QltT_to_Qlt; exact Heps').
  assert (Hcmp0 : Qcompare 0 eps' = Lt) by (apply Qlt_alt; exact H0lt).
  assert (Hcmp : Qcompare (Qabs (projT1 (real_plus (real_plus a (real_const (eps / 2)%Q))
                                                  (real_plus b (real_const (eps / 2)%Q))) n
                                - projT1 (real_plus (real_plus a b) (real_const eps)) n)) eps'
                     = Lt).
  {
    assert (Hdiff : Qabs (projT1 (real_plus (real_plus a (real_const (eps / 2)%Q))
                                            (real_plus b (real_const (eps / 2)%Q))) n
                          - projT1 (real_plus (real_plus a b) (real_const eps)) n) == 0).
    {
      setoid_rewrite Hpt.
      setoid_rewrite Hpt2.
      exact Hzero.
    }
    assert (Hc1 : Qcompare (Qabs (projT1 (real_plus (real_plus a (real_const (eps / 2)%Q))
                                                    (real_plus b (real_const (eps / 2)%Q))) n
                                  - projT1 (real_plus (real_plus a b) (real_const eps)) n)) eps'
                     = Qcompare 0 eps').
    { exact (Qcompare_comp (Qabs (projT1 (real_plus (real_plus a (real_const (eps / 2)%Q))
                                                    (real_plus b (real_const (eps / 2)%Q))) n
                                  - projT1 (real_plus (real_plus a b) (real_const eps)) n)) 0
                           Hdiff eps' eps' (Qeq_refl eps')). }
    rewrite Hc1. exact Hcmp0.
  }
  exact Hcmp.
Qed.

(* real_eq 辅助：((l1−e/2)+(l2−e/2)) == (l1+l2)−e（逐点 ring；符号反向版） *)
Lemma real_eq_plus_opp_eps_halves :
  forall (a b : Real) (eps : Q),
    real_eq (real_plus (real_plus a (real_opp (real_const (eps / 2)%Q)))
                       (real_plus b (real_opp (real_const (eps / 2)%Q))))
            (real_plus (real_plus a b) (real_opp (real_const eps))).
Proof.
  intros a b eps eps' Heps'.
  exists O. intros n Hn.
  apply Qlt_to_QltT.
  assert (Hpt : projT1 (real_plus (real_plus a (real_opp (real_const (eps / 2)%Q)))
                                  (real_plus b (real_opp (real_const (eps / 2)%Q)))) n
                == (projT1 a n - eps / 2) + (projT1 b n - eps / 2)).
  {
    destruct a as [ua Ha]. destruct b as [ub Hb].
    simpl. ring.
  }
  assert (Hpt2 : projT1 (real_plus (real_plus a b) (real_opp (real_const eps))) n
                 == (projT1 a n + projT1 b n) - eps).
  {
    destruct a as [ua Ha]. destruct b as [ub Hb].
    simpl. ring.
  }
  assert (Hzero : Qabs ((projT1 a n - eps / 2) + (projT1 b n - eps / 2)
                        - ((projT1 a n + projT1 b n) - eps)) == 0).
  {
    apply (Qeq_trans _ (Qabs 0) _).
    - apply Qabs_wd. field.
    - apply (Qeq_trans _ (-0) _).
      + apply Qabs_neg. apply Qle_refl.
      + apply Qeq_refl.
  }
  assert (H0lt : Qlt 0 eps') by (apply QltT_to_Qlt; exact Heps').
  assert (Hcmp0 : Qcompare 0 eps' = Lt) by (apply Qlt_alt; exact H0lt).
  assert (Hcmp : Qcompare (Qabs (projT1 (real_plus (real_plus a (real_opp (real_const (eps / 2)%Q)))
                                                  (real_plus b (real_opp (real_const (eps / 2)%Q)))) n
                                - projT1 (real_plus (real_plus a b) (real_opp (real_const eps))) n)) eps'
                     = Lt).
  {
    assert (Hdiff : Qabs (projT1 (real_plus (real_plus a (real_opp (real_const (eps / 2)%Q)))
                                            (real_plus b (real_opp (real_const (eps / 2)%Q)))) n
                          - projT1 (real_plus (real_plus a b) (real_opp (real_const eps))) n) == 0).
    {
      setoid_rewrite Hpt.
      setoid_rewrite Hpt2.
      exact Hzero.
    }
    assert (Hc1 : Qcompare (Qabs (projT1 (real_plus (real_plus a (real_opp (real_const (eps / 2)%Q)))
                                                    (real_plus b (real_opp (real_const (eps / 2)%Q)))) n
                                  - projT1 (real_plus (real_plus a b) (real_opp (real_const eps))) n)) eps'
                     = Qcompare 0 eps').
    { exact (Qcompare_comp (Qabs (projT1 (real_plus (real_plus a (real_opp (real_const (eps / 2)%Q)))
                                                    (real_plus b (real_opp (real_const (eps / 2)%Q)))) n
                                  - projT1 (real_plus (real_plus a b) (real_opp (real_const eps))) n)) 0
                           Hdiff eps' eps' (Qeq_refl eps')). }
    rewrite Hc1. exact Hcmp0.
  }
  exact Hcmp.
Qed.

(* real_lim 加法保持：u→l1、v→l2 ⟹ u+v → l1+l2
   非平凡：eps/2 分割（Heps2）+ real_lt_plus_compat 加性平移 +
   real_eq_plus_eps_halves / real_eq_plus_opp_eps_halves 换形
   （(l1+e/2)+(l2+e/2) == (l1+l2)+e、((l1−e/2)+(l2−e/2)) == (l1+l2)−e）
   + real_lt_eq_lt / real_eq_lt_lt 外延替换。 *)
Theorem real_lim_plus : forall (u v : nat -> Real) (l1 l2 : Real),
  real_lim u l1 -> real_lim v l2 ->
  real_lim (fun n => real_plus (u n) (v n)) (real_plus l1 l2).
Proof.
  intros u v l1 l2 Hlim1 Hlim2 eps Heps.
  (* eps/2 分割 *)
  assert (Heps2 : QltT 0 (eps / 2)%Q).
  {
    assert (Hq : Qlt 0 (eps / 2)).
    { apply Qlt_shift_div_l; [reflexivity | simpl; apply QltT_to_Qlt; exact Heps]. }
    exact (Qlt_to_QltT 0 (eps / 2) Hq).
  }
  destruct (Hlim1 (eps / 2)%Q Heps2) as [N1 HN1].
  destruct (Hlim2 (eps / 2)%Q Heps2) as [N2 HN2].
  exists (max N1 N2).
  intros n Hn.
  assert (Hn1 : (N1 <= n)%nat) by (apply Nat.le_trans with (max N1 N2); [apply Nat.le_max_l | exact Hn]).
  assert (Hn2 : (N2 <= n)%nat) by (apply Nat.le_trans with (max N1 N2); [apply Nat.le_max_r | exact Hn]).
  destruct (HN1 n Hn1) as [Hup1 Hdn1].
  destruct (HN2 n Hn2) as [Hup2 Hdn2].
  split.
  - (* 上界：real_lt (u n + v n) ((l1+l2) + eps) *)
    (* 由加性平移：(u n + v n) < (l1+e/2) + (l2+e/2) *)
    assert (Hsum_lt : real_lt (real_plus (u n) (v n))
                              (real_plus (real_plus l1 (real_const (eps / 2)%Q))
                                         (real_plus l2 (real_const (eps / 2)%Q))))
      by (apply real_lt_plus_compat; [exact Hup1 | exact Hup2]).
    (* 换形：右端 == (l1+l2) + eps（real_eq_plus_eps_halves） *)
    apply (real_lt_eq_lt (real_plus (u n) (v n))
                         (real_plus (real_plus l1 (real_const (eps / 2)%Q))
                                    (real_plus l2 (real_const (eps / 2)%Q)))
                         (real_plus (real_plus l1 l2) (real_const eps))).
    + exact Hsum_lt.
    + exact (real_eq_plus_eps_halves l1 l2 eps).
  - (* 下界：real_lt ((l1+l2) − eps) (u n + v n) *)
    (* 由加性平移：(l1−e/2) + (l2−e/2) < (u n + v n) *)
    assert (Hsum_dn : real_lt (real_plus (real_plus l1 (real_opp (real_const (eps / 2)%Q)))
                                         (real_plus l2 (real_opp (real_const (eps / 2)%Q))))
                              (real_plus (u n) (v n)))
      by (apply real_lt_plus_compat; [exact Hdn1 | exact Hdn2]).
    (* 换形：左端 == (l1+l2) − eps（real_eq_plus_opp_eps_halves，经 real_eq_lt_lt） *)
    apply (real_eq_lt_lt (real_plus (real_plus l1 l2) (real_opp (real_const eps)))
                         (real_plus (real_plus l1 (real_opp (real_const (eps / 2)%Q)))
                                    (real_plus l2 (real_opp (real_const (eps / 2)%Q))))
                         (real_plus (u n) (v n))).
    + apply (real_eq_sym _ _ (real_eq_plus_opp_eps_halves l1 l2 eps)).
    + exact Hsum_dn.
Qed.

(* 逐点投影：projT1 (real_mult (real_const c) l) m == c·projT1 l m（real_mult 逐点 u·v） *)
Lemma real_mult_const_proj : forall (c : Q) (l : Real) (m : nat),
  projT1 (real_mult (real_const c) l) m == projT1 (real_const c) m * projT1 l m.
Proof.
  intros c [ll Hll] m. reflexivity.
Qed.

(* real_lim 标量缩放：u → l ⟹ c·u → c·l（c : Q 有理标量经 real_const 嵌入）。
   非平凡：eps' := eps/(2(|c|+1)) 分割（保证分母正）+ real_lt_abs_bound
   双向夹逼逐点界 + q_scal_eps_half/neg 缩放（c 可正可负，|c|+1 归一）
   + 投影 change 归约（real_mult/real_plus/real_const 逐点展开）。 *)
Theorem real_lim_scal : forall (u : nat -> Real) (l : Real) (c : Q),
  real_lim u l ->
  real_lim (fun n => real_mult (real_const c) (u n)) (real_mult (real_const c) l).
Proof.
  intros u l c Hlim eps Heps.
  (* eps' := eps / (2·(|c|+1))（> 0，因 2·(|c|+1) > 0） *)
  set (eps' := eps / (2 * (Qabs c + 1))).
  assert (Heps' : QltT 0 eps').
  {
    unfold eps'.
    apply Qlt_to_QltT.
    (* 目标 Qlt 0 (eps / (2(|c|+1)))：Qlt_shift_div_l 转前提 0·(2(|c|+1)) < eps *)
    apply Qlt_shift_div_l.
    - (* 0 < 2·(|c|+1) *)
      apply Qmult_lt_0_compat.
      + reflexivity.
      + apply Qlt_le_trans with 1%Q.
        * reflexivity.
        * setoid_replace (Qabs c + 1) with (1 + Qabs c) by ring.
          apply q_le_plus_nonneg_r_q. apply Qabs_nonneg.
    - (* 前提：0·(2(|c|+1)) < eps == 0 < eps *)
      setoid_replace (0 * (2 * (Qabs c + 1))) with 0 by ring.
      apply QltT_to_Qlt. exact Heps.
  }
  assert (Heps_half : QltT 0 (eps / 2)%Q).
  {
    assert (Hq : Qlt 0 (eps / 2)).
    { apply Qlt_shift_div_l; [reflexivity | simpl; apply QltT_to_Qlt; exact Heps]. }
    exact (Qlt_to_QltT 0 (eps / 2) Hq).
  }
  destruct (Hlim eps' Heps') as [N HN].
  exists N.
  intros n Hn.
  (* HN n Hn : And (real_lt (u n) (l + eps')) (real_lt (l − eps') (u n))；
     用 real_lt_abs_bound 得逐点界 |u_n(m) − l_m| < eps'（对 m ≥ M） *)
  destruct (real_lt_abs_bound u l eps' Heps' N HN n Hn) as [M HM].
  split.
  - (* 上方向：real_lt (c·u n) (c·l + eps)：见证 eps/2，阈值 M *)
    exists (eps / 2)%Q. split.
    + exact Heps_half.
    + exists M. intros m Hm.
      (* HM m Hm : QltT (Qabs (projT1 (u n) m - projT1 l m)) eps' *)
      apply Qlt_to_QltT.
      (* 逐点展开投影：real_plus_proj + real_const_proj + real_mult_const_proj
         （projT1 (real_mult (real_const c) x) m == c·projT1 x m，x := l / u n） *)
      setoid_rewrite (real_plus_proj (real_mult (real_const c) l) (real_const eps) m).
      setoid_rewrite (real_const_proj eps m).
      assert (Hml : projT1 (real_mult (real_const c) l) m == c * projT1 l m)
        by (setoid_rewrite (real_mult_const_proj c l m); setoid_rewrite (real_const_proj c m); reflexivity).
      setoid_rewrite Hml.
      assert (Hmu : projT1 (real_mult (real_const c) (u n)) m == c * projT1 (u n) m)
        by (setoid_rewrite (real_mult_const_proj c (u n) m); setoid_rewrite (real_const_proj c m); reflexivity).
      setoid_rewrite Hmu.
      (* 目标：Qlt (eps/2) (c·l_m + eps − c·u_n(m)) == eps − c·(u_n(m) − l_m) *)
      assert (Hd : Qlt (Qabs (projT1 (u n) m - projT1 l m)) eps')
        by (apply QltT_to_Qlt; exact (HM m (NatLe_drop _ _ Hm))).
      (* c·(u_n(m) − l_m) < eps/2（q_scal_eps_half）；换形目标为 eps/2 < eps − c·Δ *)
      assert (Hscal : Qlt (c * (projT1 (u n) m - projT1 l m)) (eps / 2))
        by (unfold eps'; apply q_scal_eps_half; [apply QltT_to_Qlt; exact Heps | exact Hd]).
      (* 目标 eps/2 < c·l_m + eps − c·u_n(m) ⟺ eps/2 < eps − c·(u_n(m) − l_m)（ring）
         ⟺ c·(u_n(m) − l_m) < eps/2（Qlt_minus_iff 反向） *)
      (* 目标：eps/2 < c·l_m + eps − c·u_n(m)（ring 换形后的目标）
         链：eps/2 < c·l_m+eps−c·u_n(m) ⟺ 0 < (c·l_m+eps−c·u_n(m)) − eps/2（Qlt_minus_iff proj2）
         ⟺ 0 < eps/2 − c·(u_n(m)−l_m)（ring）⟸ c·(u_n(m)−l_m) < eps/2（Qlt_minus_iff proj1，Hscal） *)
      apply (proj2 (Qlt_minus_iff (eps / 2) (c * projT1 l m + eps - c * projT1 (u n) m))).
      setoid_replace (c * projT1 l m + eps - c * projT1 (u n) m + - (eps / 2))
        with (eps / 2 - c * (projT1 (u n) m - projT1 l m)) by field.
      apply (proj1 (Qlt_minus_iff (c * (projT1 (u n) m - projT1 l m)) (eps / 2))).
      exact Hscal.
  - (* 下方向：real_lt (c·l − eps) (c·u n)：见证 eps/2，阈值 M *)
    exists (eps / 2)%Q. split.
    + exact Heps_half.
    + exists M. intros m Hm.
      apply Qlt_to_QltT.
      (* 逐点展开投影：real_plus_proj + real_opp_proj + real_const_proj + real_mult_const_proj *)
      setoid_rewrite (real_plus_proj (real_mult (real_const c) l) (real_opp (real_const eps)) m).
      setoid_rewrite (real_opp_proj (real_const eps) m).
      setoid_rewrite (real_const_proj eps m).
      assert (Hml : projT1 (real_mult (real_const c) l) m == c * projT1 l m)
        by (setoid_rewrite (real_mult_const_proj c l m); setoid_rewrite (real_const_proj c m); reflexivity).
      setoid_rewrite Hml.
      assert (Hmu : projT1 (real_mult (real_const c) (u n)) m == c * projT1 (u n) m)
        by (setoid_rewrite (real_mult_const_proj c (u n) m); setoid_rewrite (real_const_proj c m); reflexivity).
      setoid_rewrite Hmu.
      (* 目标：Qlt (eps/2) (c·u_n(m) − (c·l_m − eps)) == eps + c·(u_n(m) − l_m)
         即 −(c·(u_n(m) − l_m)) < eps/2（q_scal_eps_half_neg） *)
      assert (Hd : Qlt (Qabs (projT1 (u n) m - projT1 l m)) eps') by (apply QltT_to_Qlt; exact (HM m (NatLe_drop _ _ Hm))).
      assert (Hscal : Qlt (- (c * (projT1 (u n) m - projT1 l m))) (eps / 2))
        by (unfold eps'; apply q_scal_eps_half_neg; [apply QltT_to_Qlt; exact Heps | exact Hd]).
      (* 目标 eps/2 < c·u_n(m) − (c·l_m − eps) ⟺ eps/2 < eps + c·(u_n(m) − l_m)（ring）
         而 −(c·(u_n(m) − l_m)) < eps/2 ⟺ 0 < eps/2 + c·(u_n(m) − l_m)（Qlt_minus_iff 反向，Hscal） *)
      setoid_replace (c * projT1 (u n) m - (c * projT1 l m + (- eps)))
        with (eps + c * (projT1 (u n) m - projT1 l m)) by ring.
      apply (proj2 (Qlt_minus_iff (eps / 2) (eps + c * (projT1 (u n) m - projT1 l m)))).
      setoid_replace (eps + c * (projT1 (u n) m - projT1 l m) + - (eps / 2))
        with (eps / 2 + c * (projT1 (u n) m - projT1 l m)) by field.
      (* 目标 0 < eps/2 + X（X := c·Δ）；由 Hscal : −X < eps/2 用 Qlt_minus_iff 正向：
         proj1 给 0 < eps/2 + −(−X)，先换 X == −(−X)（Qeq_sym Qopp_involutive） *)
      setoid_replace (eps / 2 + c * (projT1 (u n) m - projT1 l m))
        with (eps / 2 + - - (c * (projT1 (u n) m - projT1 l m))).
      { apply (proj1 (Qlt_minus_iff (- (c * (projT1 (u n) m - projT1 l m))) (eps / 2))).
        exact Hscal. }
      { (* 换 LHS 的 c·X == −(−X)（Qeq_sym Qopp_involutive），setoid_rewrite at 1 只换 LHS *)
        setoid_rewrite (Qeq_sym _ _ (Qopp_involutive (c * (projT1 (u n) m - projT1 l m)))) at 1.
        reflexivity. }
Qed.

(* ============================================================ *)
(* real_lim 乘性保持（u·v → l1·l2）：前置有界引理             *)
(* ============================================================ *)
(* real_lim 逐点界提取：real_lim u l ⟹ 对 n ≥ N（eps 处），
   ∃M(n) ∀k ≥ M(n): |u_n(k) − l_k| < eps。
   证明：real_lim 的双向 real_lt（u n 在 l±eps 之间）⟹
   real_lt (u n − l) (const eps) 双向（差实值小）⟹ real_lt_pair_abs_bound。 *)
Lemma real_lim_pointwise_bound :
  forall (u : nat -> Real) (l : Real) (Hlim : real_lim u l)
         (eps : Q) (Heps : QltT 0 eps),
    sigT (fun N : nat => forall n : nat, (N <= n)%nat ->
      sigT (fun M : nat => forall k : nat, (M <= k)%nat ->
        QltT (Qabs (projT1 (u n) k - projT1 l k)) eps)).
Proof.
  intros u l Hlim eps Heps.
  destruct (Hlim eps Heps) as [N HN].
  exists N.
  intros n Hn.
  destruct (HN n Hn) as [Hup Hdn].
  (* Hup : real_lt (u n) (l + eps)；Hdn : real_lt (l − eps) (u n)。
     需转成 real_lt (u n − l) (const eps) 双向，供 real_lt_pair_abs_bound。
     直接：real_lt_pair_abs_bound 需要 real_lt (real_plus x (real_opp y)) (real_const eps)
     其中 x := u n, y := l——即 real_lt (u n − l) (const eps)。
     而 real_lim 给的是 real_lt (u n) (l + eps)——(u n) < l + eps ⟺ (u n − l) < eps。
     用 real_lt_plus 类平移：由 real_lt (u n) (l + eps) 和 real_eq 平移得
     real_lt (u n − l) (const eps)？—— 直接构造（仿 real_lt_pair_abs_bound 展开）。 *)
  (* 直接展开构造：Hup 给 e1 > 0, M1，∀k≥M1: e1 < (l_k + eps) − u_n(k)；
     Hdn 给 e2 > 0, M2，∀k≥M2: e2 < u_n(k) − (l_k − eps)。
     即 eps − (u_n(k) − l_k) > e1 > 0 ⟹ u_n(k) − l_k < eps − e1 < eps；
         (u_n(k) − l_k) + eps > e2 > 0 ⟹ −eps < u_n(k) − l_k。
     双向 ⟹ |u_n(k) − l_k| < eps（q_abs_lt_two_sided）。 *)
  destruct Hup as [e1 [He1 [M1 HM1]]].
  destruct Hdn as [e2 [He2 [M2 HM2]]].
  exists (max M1 M2).
  intros k Hk.
  assert (Hk1 : (M1 <= k)%nat) by (apply Nat.le_trans with (max M1 M2); [apply Nat.le_max_l | exact Hk]).
  assert (Hk2 : (M2 <= k)%nat) by (apply Nat.le_trans with (max M1 M2); [apply Nat.le_max_r | exact Hk]).
  (* HM1 k : QltT e1 ((l+eps)_k − (u n)_k)；展开投影 l_k + eps − u_n(k) *)
  assert (Hpt1 : projT1 (real_plus l (real_const eps)) k - projT1 (u n) k
                 == projT1 l k + eps - projT1 (u n) k).
  {
    assert (Hp : projT1 (real_plus l (real_const eps)) k == projT1 l k + projT1 (real_const eps) k)
      by (apply real_plus_proj).
    assert (Hc : projT1 (real_const eps) k == eps) by (apply real_const_proj).
    setoid_rewrite Hp. setoid_rewrite Hc. reflexivity.
  }
  (* HM2 k : QltT e2 ((u n)_k − (l−eps)_k)；展开 l_k − eps *)
  assert (Hpt2 : projT1 (u n) k - projT1 (real_plus l (real_opp (real_const eps))) k
                 == projT1 (u n) k - (projT1 l k - eps)).
  {
    assert (Hp : projT1 (real_plus l (real_opp (real_const eps))) k == projT1 l k + projT1 (real_opp (real_const eps)) k)
      by (apply real_plus_proj).
    assert (Ho : projT1 (real_opp (real_const eps)) k == - projT1 (real_const eps) k)
      by (apply real_opp_proj).
    assert (Hc : projT1 (real_const eps) k == eps) by (apply real_const_proj).
    setoid_rewrite Hp. setoid_rewrite Ho. setoid_rewrite Hc. reflexivity.
  }
  (* 上界：u_n(k) − l_k < eps（由 e1 < eps − (u_n(k) − l_k) 且 e1 > 0） *)
  assert (Hlt1 : Qlt e1 (eps - (projT1 (u n) k - projT1 l k))).
  {
    pose proof (HM1 k (NatLe_lift _ _ Hk1)) as HM1k.
    apply QltT_to_Qlt in HM1k.
    setoid_rewrite Hpt1 in HM1k.
    (* 目标 e1 < eps − (u_n k − l k)；HM1k : e1 < l_k + eps − u_n k == eps − (u_n k − l k)
       用 setoid_replace 换 HM1k 的项（Qlt 兼容 Qeq） *)
    setoid_replace (projT1 l k + eps - projT1 (u n) k)
      with (eps - (projT1 (u n) k - projT1 l k)) in HM1k by ring.
    exact HM1k.
  }
  assert (Hlt2 : Qlt e2 (projT1 (u n) k - (projT1 l k - eps))).
  {
    pose proof (HM2 k (NatLe_lift _ _ Hk2)) as HM2k.
    apply QltT_to_Qlt in HM2k.
    setoid_rewrite Hpt2 in HM2k.
    exact HM2k.
  }
  (* 下界：−eps < u_n(k) − l_k（由 e2 < u_n(k) − l_k + eps 且 e2 > 0） *)
  assert (Hlo : Qlt (- eps) (projT1 (u n) k - projT1 l k)).
  {
    (* e2 < u_n k − l_k + eps；目标 −eps < d ⟺ 0 < d + eps，由 e2 < d + eps 且 0 < e2 *)
    assert (Hd2 : Qlt e2 (eps + (projT1 (u n) k - projT1 l k))).
    {
      (* 目标 e2 < eps + (u_n k − l k)；Hlt2 : e2 < u_n k − (l k − eps)，
         换 Hlt2 的 RHS == eps + (u_n k − l k) *)
      setoid_replace (projT1 (u n) k - (projT1 l k - eps))
        with (eps + (projT1 (u n) k - projT1 l k)) in Hlt2 by ring.
      exact Hlt2.
    }
    apply Qlt_minus_iff.
    (* 目标 0 < d + -(-eps) == d + eps；由 e2 < d + eps：0 < (d+eps) − e2 == d + (eps − e2)，
       且 0 < e2 ⟹ 0 < d + eps *)
    assert (Hpos : Qlt 0 ((projT1 (u n) k - projT1 l k) + (eps - e2))).
    {
      apply Qlt_minus_iff in Hd2.
      setoid_replace (eps + (projT1 (u n) k - projT1 l k) - e2)
        with ((projT1 (u n) k - projT1 l k) + (eps - e2)) in Hd2 by ring.
      exact Hd2.
    }
    assert (He2pos : Qlt 0 e2) by (apply QltT_to_Qlt; exact He2).
    assert (Hsum : Qlt (0 + 0) ((projT1 (u n) k - projT1 l k) + (eps - e2) + e2)).
    { apply Qplus_lt_compat; [exact Hpos | exact He2pos]. }
    setoid_replace ((projT1 (u n) k - projT1 l k) + (eps - e2) + e2)
      with ((projT1 (u n) k - projT1 l k) + eps) in Hsum by ring.
    rewrite Qplus_0_l in Hsum.
    setoid_replace (- (- eps)) with eps by (apply Qopp_involutive).
    exact Hsum.
  }
  (* 上界：u_n(k) − l_k < eps（由 0 < e1 且 e1 < eps − d） *)
  assert (Hup' : Qlt (projT1 (u n) k - projT1 l k) eps).
  {
    apply (proj2 (Qlt_minus_iff (projT1 (u n) k - projT1 l k) eps)).
    assert (He1pos : Qlt 0 e1) by (apply QltT_to_Qlt; exact He1).
    apply (Qlt_trans _ e1 _).
    - exact He1pos.
    - exact Hlt1.
  }
  (* |d| < eps：q_abs_lt_two_sided *)
  apply Qlt_to_QltT.
  apply (q_abs_lt_two_sided (projT1 (u n) k - projT1 l k) eps (QltT_to_Qlt 0 eps Heps)).
  - exact Hlo.
  - exact Hup'.
Qed.

(* ============================================================ *)
(* real_lim 乘性保持（u·v → l1·l2）                           *)
(* ============================================================ *)
(* 核心逐点界：对固定 n（序列下标），∃M(n) ∀m ≥ M(n):
   |u_n(m)·v_n(m) − l1(m)·l2(m)| < eps。
   分解（q_prod_diff_bound）：≤ |u_n(m)|·|v_n(m)−l2(m)| + |u_n(m)−l1(m)|·|l2(m)|
   —— |u_n(m)| ≤ 1 + Ml1'（u→l1 逐点界在 eps:=1 + l1 有界，**常数不依赖 n**！）；
   —— 项①：|v_n(m)−l2(m)| < eps/(4(1+Ml1'))（v→l2 逐点界，N 固定）⟹ q_abs_mul_bound
      ⟹ < (1+Ml1')·eps/(4(1+Ml1')) = eps/4；
   —— 项②：|u_n(m)−l1(m)| < eps/(4(Ml2'+1))（u→l1 逐点界）且 |l2(m)| ≤ Ml2'
      ⟹ q_abs_mul_bound ⟹ < Ml2'·eps/(4(Ml2'+1)) ≤ eps/4。
   总 < eps/2 < eps。M(n) 依赖 n 合法（real_lim 的 ∀n 内，real_lt 阈值可依赖 n）。 *)
Lemma real_lim_mult_pointwise :
  forall (u v : nat -> Real) (l1 l2 : Real),
    real_lim u l1 -> real_lim v l2 ->
    forall (eps : Q) (Heps : QltT 0 eps),
      sigT (fun N : nat => forall n : nat, (N <= n)%nat ->
        sigT (fun M : nat => forall m : nat, (M <= m)%nat ->
          QltT (Qabs (projT1 (real_mult (u n) (v n)) m - projT1 (real_mult l1 l2) m)) eps)).
Proof.
  intros u v l1 l2 Hlim1 Hlim2 eps Heps.
  (* eps/4 正性 *)
  assert (Heps4 : QltT 0 (eps / 4)%Q).
  {
    assert (Hq : Qlt 0 (eps / 4)).
    { apply Qlt_shift_div_l; [reflexivity | simpl; apply QltT_to_Qlt; exact Heps]. }
    exact (Qlt_to_QltT 0 (eps / 4) Hq).
  }
  (* l1、l2 实值范数一致有界（real_norm_bounded）：Ml1'、Ml2' 严格正且
     |l1_k| ≤ Ml1'、|l2_k| ≤ Ml2'——l1/l2 是柯西实数，界不依赖 n *)
  destruct (real_norm_bounded l1) as [Ml1' [HMl1'_pos HMl1']].
  destruct (real_norm_bounded l2) as [Ml2' [HMl2'_pos HMl2']].
  (* |u_n(m)| ≤ 1 + Ml1'：u→l1 逐点界在 eps:=1（N_u1 固定）+ l1 有界 *)
  assert (Hone : QltT 0 1%Q).
  { apply Qlt_to_QltT. reflexivity. }
  destruct (real_lim_pointwise_bound u l1 Hlim1 1%Q Hone) as [Nu1 HNu1].
  (* u→l1 逐点界在 eps/(4(Ml2'+1))（项②的 u−l1 界，Nu2 固定）——Set 链：HMl2'_pos 直接用 *)
  assert (Heps_u : QltT 0 (eps / (4 * (Ml2' + 1)))%Q).
  { apply (qltT_div_pos eps (4 * (Ml2' + 1))).
    - exact Heps.
    - apply (qmult_ltT_0_compat 4 (Ml2' + 1)).
      + exact qltT_0_4.
      + apply (qltT_plus_pos_r Ml2' 1). exact HMl2'_pos. exact qltT_0_1. }
  destruct (real_lim_pointwise_bound u l1 Hlim1 (eps / (4 * (Ml2' + 1)))%Q Heps_u) as [Nu2 HNu2].
  (* 1+Ml1' 非负（Set 版：0 ≤T 1 ≤T 1+Ml1'；HMl1'_pos 经 Set 弱化 qltT_leT'，无降级） *)
  assert (H1Ml1'nonnegT : QleT' 0 (1 + Ml1')).
  { apply (qleT'_trans 0 1 (1 + Ml1')).
    - apply Qle_to_QleT'. apply Qlt_le_weak. reflexivity.
    - apply (qleT'_plus_compat 1 1 0 Ml1').
      + apply qleT'_refl.
      + apply qltT_leT'. exact HMl1'_pos. }
  (* v→l2 逐点界在 eps/(4(1+Ml1'+1))——Set 链：0 <T (1+Ml1') 由 0 <T 1 且 1 ≤T 1+Ml1' *)
  assert (Heps_v : QltT 0 (eps / (4 * (1 + Ml1' + 1)))%Q).
  { apply (qltT_div_pos eps (4 * (1 + Ml1' + 1))).
    - exact Heps.
    - apply (qmult_ltT_0_compat 4 (1 + Ml1' + 1)).
      + exact qltT_0_4.
      + apply (qltT_plus_pos_r (1 + Ml1') 1).
        * apply (qltT_leT'_ltT 0 1 (1 + Ml1')).
          -- exact qltT_0_1.
          -- apply (qleT'_plus_compat 1 1 0 Ml1').
             ++ apply qleT'_refl.
             ++ apply qltT_leT'. exact HMl1'_pos.
        * exact qltT_0_1. }
  destruct (real_lim_pointwise_bound v l2 Hlim2 (eps / (4 * (1 + Ml1' + 1)))%Q Heps_v) as [Nv HNv].
  (* 序列阈值 N := max Nu1 (max Nu2 Nv) *)
  exists (max Nu1 (max Nu2 Nv)).
  intros n Hn.
  assert (Hn1 : (Nu1 <= n)%nat) by (apply Nat.le_trans with (max Nu1 (max Nu2 Nv)); [apply Nat.le_max_l | exact Hn]).
  assert (Hn2 : (Nu2 <= n)%nat) by (apply Nat.le_trans with (max Nu2 Nv); [apply Nat.le_max_l | apply Nat.le_trans with (max Nu1 (max Nu2 Nv)); [apply Nat.le_max_r | exact Hn]]).
  assert (Hnv : (Nv <= n)%nat) by (apply Nat.le_trans with (max Nu2 Nv); [apply Nat.le_max_r | apply Nat.le_trans with (max Nu1 (max Nu2 Nv)); [apply Nat.le_max_r | exact Hn]]).
  (* 逐点界阈值（依赖 n）：M1(n) := max(M_u1(n), M_v(n), M_u2(n)) *)
  destruct (HNu1 n Hn1) as [Mu1 HMu1].
  destruct (HNv n Hnv) as [Mv HMv].
  destruct (HNu2 n Hn2) as [Mu2 HMu2].
  exists (max Mu1 (max Mv Mu2)).
  intros m Hm.
  assert (Hm1 : (Mu1 <= m)%nat)
    by (apply Nat.le_trans with (max Mu1 (max Mv Mu2)); [apply Nat.le_max_l | exact Hm]).
  assert (Hmv : (Mv <= m)%nat)
    by (apply Nat.le_trans with (max Mv Mu2); [apply Nat.le_max_l | apply Nat.le_trans with (max Mu1 (max Mv Mu2)); [apply Nat.le_max_r | exact Hm]]).
  assert (Hm2 : (Mu2 <= m)%nat)
    by (apply Nat.le_trans with (max Mv Mu2); [apply Nat.le_max_r | apply Nat.le_trans with (max Mu1 (max Mv Mu2)); [apply Nat.le_max_r | exact Hm]]).
  (* 目标：|u_n(m)·v_n(m) − l1(m)·l2(m)| <T eps——Set 链（HMl1'/HMl2' 直接，无降级） *)
  apply (qltT_eq_compat_l (Qabs (projT1 (u n) m * projT1 (v n) m - projT1 l1 m * projT1 l2 m))
                          (Qabs (projT1 (real_mult (u n) (v n)) m - projT1 (real_mult l1 l2) m))
                          eps).
  - apply Qabs_wd.
    setoid_rewrite (real_mult_proj (u n) (v n) m).
    setoid_rewrite (real_mult_proj l1 l2 m).
    reflexivity.
  - assert (HbdT : QleT' (Qabs (projT1 (u n) m * projT1 (v n) m - projT1 l1 m * projT1 l2 m))
                       (Qabs (projT1 (u n) m) * Qabs (projT1 (v n) m - projT1 l2 m)
                        + Qabs (projT1 l2 m) * Qabs (projT1 (u n) m - projT1 l1 m))).
  { apply Qle_to_QleT'.
    assert (Hp : Qle (Qabs (projT1 (u n) m * projT1 (v n) m - projT1 l1 m * projT1 l2 m))
                     (Qabs (projT1 (u n) m) * Qabs (projT1 (v n) m - projT1 l2 m)
                      + Qabs (projT1 (u n) m - projT1 l1 m) * Qabs (projT1 l2 m))) by apply q_prod_diff_bound.
    eapply Qle_trans; [exact Hp |].
    apply qeq_imp_qle. ring. }
  (* |u_n(m)| ≤T 1 + Ml1'（三角 + <T1 与 ≤T Ml1' 之和；HMl1' 直接） *)
  assert (HunT : QleT' (Qabs (projT1 (u n) m)) (1 + Ml1')).
  { apply (qleT'_trans (Qabs (projT1 (u n) m))
                       (Qabs (projT1 (u n) m - projT1 l1 m) + Qabs (projT1 l1 m))
                       (1 + Ml1')).
    - apply Qle_to_QleT'.
      apply (Qle_trans _ (Qabs ((projT1 (u n) m - projT1 l1 m) + projT1 l1 m)) _).
      + setoid_replace (Qabs ((projT1 (u n) m - projT1 l1 m) + projT1 l1 m))
          with (Qabs (projT1 (u n) m)) by (apply Qabs_wd; ring).
        apply Qle_refl.
      + apply Qabs_triangle.
    - apply qltT_leT'.
      apply (qltT_plus_leT'_ltT (Qabs (projT1 (u n) m - projT1 l1 m)) 1
                                (Qabs (projT1 l1 m)) Ml1').
      + apply (HMu1 m Hm1).
      + apply HMl1'. }
  (* 项①：|u|·|v−l2| <T (1+Ml1')·(eps/(4(1+Ml1'+1))) *)
  assert (Ht1aT : QltT (Qabs (projT1 (u n) m) * Qabs (projT1 (v n) m - projT1 l2 m))
                       ((1 + Ml1') * (eps / (4 * (1 + Ml1' + 1))))).
  { apply (qleT'_mult_ltT_compat (Qabs (projT1 (u n) m)) (1 + Ml1')
                                 (Qabs (projT1 (v n) m - projT1 l2 m))
                                 (eps / (4 * (1 + Ml1' + 1)))).
    - apply (qltT_leT'_ltT 0 1 (1 + Ml1')).
      + exact qltT_0_1.
      + apply (qleT'_plus_compat 1 1 0 Ml1').
        * apply qleT'_refl.
        * apply qltT_leT'. exact HMl1'_pos.
    - apply qabs_nonnegT.
    - exact HunT.
    - apply (HMv m Hmv). }
  (* 项①上界 ≤T eps/4：因 (1+Ml1') ≤ (1+Ml1'+1) 且 (1+Ml1'+1)·X == eps/4 *)
  assert (Ht1bT : QleT' ((1 + Ml1') * (eps / (4 * (1 + Ml1' + 1)))) (eps / 4)).
  { apply Qle_to_QleT'.
    apply (Qle_trans _ ((1 + Ml1' + 1) * (eps / (4 * (1 + Ml1' + 1)))) _).
    - apply Qmult_le_compat_r.
      + apply Qle_plus_nonneg_r. apply Qle_0_1.
      + apply Qlt_le_weak. exact (QltT_to_Qlt 0 (eps / (4 * (1 + Ml1' + 1))) Heps_v).
    - assert (Hf : (1 + Ml1' + 1) * (eps / (4 * (1 + Ml1' + 1))) == eps / 4).
      { field.
        intro Hz.
        apply (qltT_not_eq_zero (1 + Ml1' + 1)).
        - apply (qltT_plus_pos_r (1 + Ml1') 1).
          + apply (qltT_leT'_ltT 0 1 (1 + Ml1')).
            * exact qltT_0_1.
            * apply (qleT'_plus_compat 1 1 0 Ml1').
              -- apply qleT'_refl.
              -- apply qltT_leT'. exact HMl1'_pos.
          + exact qltT_0_1.
        - exact Hz. }
      setoid_rewrite Hf. apply Qle_refl. }
  assert (Ht1T : QltT (Qabs (projT1 (u n) m) * Qabs (projT1 (v n) m - projT1 l2 m)) (eps / 4))
    by (apply (qltT_leT'_ltT _ _ _ Ht1aT Ht1bT)).
  (* 项②：|l2|·|u−l1| <T Ml2'·(eps/(4(Ml2'+1)))（HMl2' 与 HMu2 直接） *)
  assert (Ht2aT : QltT (Qabs (projT1 l2 m) * Qabs (projT1 (u n) m - projT1 l1 m))
                       (Ml2' * (eps / (4 * (Ml2' + 1))))).
  { apply (qleT'_mult_ltT_compat (Qabs (projT1 l2 m)) Ml2'
                                 (Qabs (projT1 (u n) m - projT1 l1 m))
                                 (eps / (4 * (Ml2' + 1)))).
    - exact HMl2'_pos.
    - apply qabs_nonnegT.
    - apply HMl2'.
    - apply (HMu2 m Hm2). }
  assert (Ht2bT : QleT' (Ml2' * (eps / (4 * (Ml2' + 1)))) (eps / 4)).
  { apply Qle_to_QleT'.
    apply (Qle_trans _ ((Ml2' + 1) * (eps / (4 * (Ml2' + 1)))) _).
    - apply Qmult_le_compat_r.
      + apply Qle_plus_nonneg_r. apply Qle_0_1.
      + apply Qlt_le_weak. exact (QltT_to_Qlt 0 (eps / (4 * (Ml2' + 1))) Heps_u).
    - assert (Hf : (Ml2' + 1) * (eps / (4 * (Ml2' + 1))) == eps / 4).
      { field.
        intro Hz.
        apply (qltT_not_eq_zero (Ml2' + 1)).
        - apply (qltT_plus_pos_r Ml2' 1).
          + exact HMl2'_pos.
          + exact qltT_0_1.
        - exact Hz. }
      setoid_rewrite Hf. apply Qle_refl. }
  assert (Ht2T : QltT (Qabs (projT1 l2 m) * Qabs (projT1 (u n) m - projT1 l1 m)) (eps / 4))
    by (apply (qltT_leT'_ltT _ _ _ Ht2aT Ht2bT)).
  (* 结论：|差| ≤T 和 <T eps/4+eps/4 ==T eps/2 <T eps *)
  apply (qleT'_ltT_ltT (Qabs (projT1 (u n) m * projT1 (v n) m - projT1 l1 m * projT1 l2 m))
                       (Qabs (projT1 (u n) m) * Qabs (projT1 (v n) m - projT1 l2 m)
                        + Qabs (projT1 l2 m) * Qabs (projT1 (u n) m - projT1 l1 m))
                       eps);
    [ exact HbdT
    | apply (qltT_leT'_ltT _ (eps / 2) eps);
      [ apply (qltT_leT'_ltT _ (eps / 4 + eps / 4) (eps / 2));
        [ apply (qltT_plus_ltT (Qabs (projT1 (u n) m) * Qabs (projT1 (v n) m - projT1 l2 m))
                               (eps / 4)
                               (Qabs (projT1 l2 m) * Qabs (projT1 (u n) m - projT1 l1 m))
                               (eps / 4));
          [ exact Ht1T | exact Ht2T ]
        | apply qeq_leT';
          assert (Hq : eps / 4 + eps / 4 == eps / 2) by field;
          exact Hq ]
      | apply qltT_leT'; apply qltT_half_lt_selfT; exact Heps ] ].
Qed.

(* 柯西完备性的 real_lim 部分（乘性保持）：u→l1 ∧ v→l2 ⟹ u·v→l1·l2。
   双向 eps/2 夹逼，逐点界由 real_lim_mult_pointwise（eps/2 处）给出。 *)
Theorem real_lim_mult : forall (u v : nat -> Real) (l1 l2 : Real),
  real_lim u l1 -> real_lim v l2 ->
  real_lim (fun n => real_mult (u n) (v n)) (real_mult l1 l2).
Proof.
  intros u v l1 l2 Hlim1 Hlim2 eps Heps.
  assert (Heps2 : QltT 0 (eps / 2)%Q).
  {
    assert (Hq : Qlt 0 (eps / 2)).
    { apply Qlt_shift_div_l; [reflexivity | simpl; apply QltT_to_Qlt; exact Heps]. }
    exact (Qlt_to_QltT 0 (eps / 2) Hq).
  }
  destruct (real_lim_mult_pointwise u v l1 l2 Hlim1 Hlim2 (eps / 2)%Q Heps2) as [N HNP].
  exists N.
  intros n Hn.
  destruct (HNP n Hn) as [M HM].
  split.
  - (* 方向 1：real_lt ((u·v) n) ((l1·l2) + eps)：见证 eps/2，阈值 M *)
    exists (eps / 2)%Q. split.
    + exact Heps2.
    + exists M. intros m Hm.
      apply Qlt_to_QltT.
      (* 投影展开：real_plus_proj + real_const_proj *)
      assert (Hp1 : projT1 (real_plus (real_mult l1 l2) (real_const eps)) m
                   == projT1 (real_mult l1 l2) m + projT1 (real_const eps) m)
        by (apply real_plus_proj).
      assert (Hc1 : projT1 (real_const eps) m == eps) by (apply real_const_proj).
      setoid_rewrite Hp1. setoid_rewrite Hc1.
      setoid_replace (projT1 (real_mult l1 l2) m + eps - projT1 (real_mult (u n) (v n)) m)
        with (eps - (projT1 (real_mult (u n) (v n)) m - projT1 (real_mult l1 l2) m)) by ring.
      assert (Hd : Qlt (Qabs (projT1 (real_mult (u n) (v n)) m - projT1 (real_mult l1 l2) m)) (eps / 2)%Q)
        by (apply QltT_to_Qlt; apply (HM m (NatLe_drop _ _ Hm))).
      apply (proj2 (Qlt_minus_iff (eps / 2) (eps - (projT1 (real_mult (u n) (v n)) m - projT1 (real_mult l1 l2) m)))).
      setoid_replace (eps - (projT1 (real_mult (u n) (v n)) m - projT1 (real_mult l1 l2) m) + - (eps / 2))
        with (eps / 2 - (projT1 (real_mult (u n) (v n)) m - projT1 (real_mult l1 l2) m)) by field.
      apply (proj1 (Qlt_minus_iff (projT1 (real_mult (u n) (v n)) m - projT1 (real_mult l1 l2) m) (eps / 2))).
      apply Qle_lt_trans with (Qabs (projT1 (real_mult (u n) (v n)) m - projT1 (real_mult l1 l2) m)).
      * apply Qle_Qabs.
      * exact Hd.
  - (* 方向 2：real_lt ((l1·l2) − eps) ((u·v) n)：见证 eps/2，阈值 M *)
    exists (eps / 2)%Q. split.
    + exact Heps2.
    + exists M. intros m Hm.
      apply Qlt_to_QltT.
      (* 投影展开：real_plus_proj + real_opp_proj + real_const_proj *)
      assert (Hp2 : projT1 (real_plus (real_mult l1 l2) (real_opp (real_const eps))) m
                   == projT1 (real_mult l1 l2) m + projT1 (real_opp (real_const eps)) m)
        by (apply real_plus_proj).
      assert (Ho2 : projT1 (real_opp (real_const eps)) m == - projT1 (real_const eps) m)
        by (apply real_opp_proj).
      assert (Hc2 : projT1 (real_const eps) m == eps) by (apply real_const_proj).
      setoid_rewrite Hp2. setoid_rewrite Ho2. setoid_rewrite Hc2.
      setoid_replace (projT1 (real_mult (u n) (v n)) m - (projT1 (real_mult l1 l2) m + (- eps)))
        with (eps + (projT1 (real_mult (u n) (v n)) m - projT1 (real_mult l1 l2) m)) by ring.
      assert (Hd : Qlt (Qabs (projT1 (real_mult (u n) (v n)) m - projT1 (real_mult l1 l2) m)) (eps / 2)%Q)
        by (apply QltT_to_Qlt; apply (HM m (NatLe_drop _ _ Hm))).
      apply (proj2 (Qlt_minus_iff (eps / 2) (eps + (projT1 (real_mult (u n) (v n)) m - projT1 (real_mult l1 l2) m)))).
      setoid_replace (eps + (projT1 (real_mult (u n) (v n)) m - projT1 (real_mult l1 l2) m) + - (eps / 2))
        with (eps / 2 + (projT1 (real_mult (u n) (v n)) m - projT1 (real_mult l1 l2) m)) by field.
      (* 目标 0 < eps/2 + diff：q_abs_gt_neg 给 -(eps/2) < diff ⟹ proj1(Qlt_minus_iff) 给
         0 < diff + -(-(eps/2))，换形 -(-(eps/2)) == eps/2 且换序 == 目标 *)
      assert (Hlo : Qlt (- (eps / 2)) (projT1 (real_mult (u n) (v n)) m - projT1 (real_mult l1 l2) m))
        by (apply (q_abs_gt_neg (projT1 (real_mult (u n) (v n)) m - projT1 (real_mult l1 l2) m) (eps / 2)%Q
                   (QltT_to_Qlt 0 (eps / 2) Heps2) Hd)).
      (* 目标换形：eps/2 + diff == diff + -(-(eps/2))（ring + Qopp_involutive） *)
      setoid_replace (eps / 2 + (projT1 (real_mult (u n) (v n)) m - projT1 (real_mult l1 l2) m))
        with (projT1 (real_mult (u n) (v n)) m - projT1 (real_mult l1 l2) m + (- (- (eps / 2))))
        by (rewrite (Qopp_involutive (eps / 2)); ring).
      exact (proj1 (Qlt_minus_iff (- (eps / 2)) (projT1 (real_mult (u n) (v n)) m - projT1 (real_mult l1 l2) m)) Hlo).
Qed.

