assert (Hne : (Ne <= n)%nat) by lia.
assert (Hna : (NA <= n)%nat) by lia.
assert (Hn1 : (N1 <= n)%nat) by lia.
apply Qlt_to_QltT.
set (An := projT1 A n).
set (hn := projT1 (real_abs h) n).
set (e3n := projT1 eps3 n).
set (en' := projT1 eps' n).
