apply QltT_to_Qlt.
exact Hs0.
- apply (Qlt_le_trans _ (sn - projT1 real_zero n) _).
+ apply QltT_to_Qlt.
exact (HNs n (NatLe_lift _ _ Hns)).
+ apply qeq_le.
rewrite Hz.
ring.
}    assert (Hbn : Qle 0 bn).
{ apply Qlt_le_weak.
apply (Qlt_trans _ b0 _).
- apply QltT_to_Qlt.
exact Hb0.
- apply (Qlt_le_trans _ (bn - projT1 real_zero n) _).
+ apply QltT_to_Qlt.
exact (HNb n (NatLe_lift _ _ Hnb)).
+ apply qeq_le.
rewrite Hz.
ring.
}    assert (Hcn : Qle 0 cn).
{ apply Qlt_le_weak.
apply (Qlt_trans _ c0 _).
- apply QltT_to_Qlt.
exact Hc0.
- apply (Qlt_le_trans _ (cn - projT1 real_zero n) _).
+ apply QltT_to_Qlt.
