                  apply (real_eq_trans (real_plus (real_mult eps2 (real_abs h)) (real_mult eps2 (real_abs h)))
                                       (real_mult (real_plus eps2 eps2) (real_abs h))
                                       (real_mult eps (real_abs h))).
