                  apply (RealSetoid.real_eq_plus_compat (real_plus (real_mult eps_f epsq_g2) (real_mult M epsq_g2))
                                                        (real_plus (real_mult eps_f eps_tri_g2) (real_plus epsq_f (real_plus marg2 eps_tri)))
