                     --- apply (real_eq_trans (real_mult (real_mult eps_f (real_inv_pos eps_f Heps_f)) (real_mult half (real_mult half (real_mult half eps'))))
                                              (real_mult real_one (real_mult half (real_mult half (real_mult half eps'))))
